
@font-face{font-family:"Chulalongkorn";src:url(fonts/chula-1.woff) format("woff");font-weight:400;font-style:normal;font-display:swap}
@font-face{font-family:"Chulalongkorn";src:url(fonts/chula-2.woff) format("woff");font-weight:700;font-style:normal;font-display:swap}
/* Layout: single study column (max 760px), fixed bottom tab bar. Brand: MYCROSOC sticker red on blush paper; one bold pink hero (TU countdown) and a pink footer bookend. */
:root{
  --paper:#FBF3F2; --surface:#FFFFFF; --sunk:#F5E6E4;
  --ink:#2B1A1F; --muted:#7B6267; --line:#EDDAD7;
  --primary:#E0262E; --primary-ink:#FFFFFF; --primary-soft:#FDE4E3;
  --accent:#E8792B; --accent-soft:#FDEBDD;
  --board:#2B1A1F; --board-fg:#FFF5F4; --board-mute:#C9AFB3;
  --pink-a:#FF7E7E; --pink-b:#F2525A; --pink-c:#DC2F3B; --pink-ink:#D9131B;
  --good:#23845A; --good-soft:#DDF2E7; --bad:#C9302C; --bad-soft:#FCE1DF;
  --shadow:0 1px 2px rgba(80,20,30,.05),0 8px 24px rgba(80,20,30,.07);
  --f-display:"Chulalongkorn","IBM Plex Sans Thai",system-ui,sans-serif;
  --f-body:"Chulalongkorn","IBM Plex Sans Thai",system-ui,-apple-system,"Segoe UI",sans-serif;
  --f-mono:"IBM Plex Mono","Chulalongkorn",ui-monospace,Menlo,monospace;
  --r:16px;
}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){
  --paper:#170F11; --surface:#22171A; --sunk:#2C1E22;
  --ink:#F7ECEC; --muted:#BBA0A5; --line:#3A292D;
  --primary:#FF6B6E; --primary-ink:#1A0C0E; --primary-soft:#3D1D21;
  --accent:#F5A05E; --accent-soft:#3A2618;
  --board:#2C1E22; --board-fg:#FFF2F2; --board-mute:#BBA0A5;
  --pink-a:#E8606A; --pink-b:#CF3C47; --pink-c:#A92330; --pink-ink:#FF6B6E;
  --good:#5FCB97; --good-soft:#18342A; --bad:#FF8A84; --bad-soft:#3C1E1E;
  --shadow:0 1px 2px rgba(0,0,0,.3);
  color-scheme:dark;}}
:root[data-theme="dark"]{
  --paper:#170F11; --surface:#22171A; --sunk:#2C1E22;
  --ink:#F7ECEC; --muted:#BBA0A5; --line:#3A292D;
  --primary:#FF6B6E; --primary-ink:#1A0C0E; --primary-soft:#3D1D21;
  --accent:#F5A05E; --accent-soft:#3A2618;
  --board:#2C1E22; --board-fg:#FFF2F2; --board-mute:#BBA0A5;
  --pink-a:#E8606A; --pink-b:#CF3C47; --pink-c:#A92330; --pink-ink:#FF6B6E;
  --good:#5FCB97; --good-soft:#18342A; --bad:#FF8A84; --bad-soft:#3C1E1E;
  --shadow:0 1px 2px rgba(0,0,0,.3);
  color-scheme:dark;}
*{box-sizing:border-box}
html,body{background:var(--paper);color:var(--ink)}
body{font-family:var(--f-body);font-size:16px;line-height:1.65;padding-inline:16px;padding-block:0 calc(92px + env(safe-area-inset-bottom,0px))}
.app{max-width:760px;margin:0 auto}
h1,h2,h3{font-family:var(--f-display);font-weight:700;line-height:1.3;text-wrap:balance;margin:0}
h1{font-size:1.65rem} h2{font-size:1.25rem} h3{font-size:1.05rem}
p{margin:0}
button{font:inherit;color:inherit;cursor:pointer}
button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible,a:focus-visible{outline:2px solid var(--primary);outline-offset:2px}
.mono{font-family:var(--f-mono);font-variant-numeric:tabular-nums}
.eyebrow{font-family:var(--f-mono);font-size:.72rem;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.muted{color:var(--muted)}
.stack{display:flex;flex-direction:column;gap:16px}
.row{display:flex;gap:10px;flex-wrap:wrap;align-items:center}

/* header */
.top{position:sticky;top:env(safe-area-inset-top,0px);z-index:5;background:var(--paper);padding-block:14px 10px;display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid var(--line)}
.brand{display:flex;flex-direction:column;min-width:0}
.brand b{font-family:var(--f-display);font-weight:700;font-size:1.05rem;letter-spacing:.01em}
.seg{display:flex;background:var(--sunk);border-radius:999px;padding:3px;flex-shrink:0}
.seg button{border:0;background:transparent;padding:6px 12px;border-radius:999px;font-size:.85rem;color:var(--muted)}
.seg button[aria-pressed="true"]{background:var(--surface);color:var(--ink);font-weight:600;box-shadow:0 1px 2px rgba(0,0,0,.12)}

main{padding-block:20px 8px}

/* nav */
.nav{position:fixed;left:0;right:0;bottom:0;z-index:10;background:var(--surface);border-top:1px solid var(--line);padding:6px 8px calc(6px + env(safe-area-inset-bottom,0px));display:flex;justify-content:center}
.nav-in{display:grid;grid-template-columns:repeat(6,1fr);width:100%;max-width:760px}
.nav button{border:0;background:none;display:flex;flex-direction:column;align-items:center;gap:2px;padding:6px 2px;font-size:.72rem;color:var(--muted);border-radius:8px}
.nav button svg{width:22px;height:22px;stroke:currentColor;fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.nav button[aria-current="page"]{color:var(--primary);font-weight:600}

/* panels */
.panel{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:18px}
.flat{padding:0;border:0;background:none}
.btn{border:1px solid var(--line);background:var(--surface);padding:10px 16px;border-radius:999px;font-weight:500;font-size:.92rem}
.btn:hover{border-color:var(--primary)}
.btn.primary{background:var(--primary);color:var(--primary-ink);border-color:var(--primary)}
.btn.ghost{background:none}
.btn.small{padding:6px 12px;font-size:.84rem}
.link{border:0;background:none;color:var(--primary);padding:0;font-weight:500}

/* countdown */
.count{display:grid;grid-template-columns:auto 1fr;gap:18px;align-items:center}
.count .num{font-family:var(--f-display);font-weight:700;font-size:3.2rem;line-height:1;color:var(--primary)}
.count input{font:inherit;padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--ink);max-width:100%}
.streak{display:inline-flex;gap:6px;align-items:center;background:var(--accent-soft);color:var(--ink);padding:4px 10px;border-radius:999px;font-size:.82rem}
.streak i{width:8px;height:8px;border-radius:50%;background:var(--accent);display:inline-block}



/* footer: light directory block, then dark contact block, then marigold CTA */
body{padding-block-end:0}
main{padding-block-end:24px}
body.nofoot main{padding-block-end:calc(100px + env(safe-area-inset-bottom,0px))}
.foot{margin-inline:-16px;margin-top:32px}
.foot-in{max-width:760px;margin:0 auto;padding-inline:16px}
.foot-a{background:var(--sunk);padding-block:32px 36px}
.mark{display:inline-flex;flex-direction:column;justify-content:flex-end;gap:2px;width:148px;aspect-ratio:1;max-width:100%;background:var(--primary);color:var(--primary-ink);padding:14px;position:relative;overflow:hidden}
.mark b{font-family:var(--f-display);font-weight:700;font-size:1.55rem;line-height:1;letter-spacing:.02em}
.mark small{font-family:var(--f-mono);font-size:.6rem;letter-spacing:.12em;opacity:.85}
.mark svg{position:absolute;top:12px;right:12px;width:46px;height:46px}
.logo{display:block;width:148px;height:auto;max-width:100%;aspect-ratio:1}
.hlogo{width:38px;height:38px;border-radius:8px;flex-shrink:0}
.brandwrap{display:flex;align-items:center;gap:10px;min-width:0}
.dir{display:grid;grid-template-columns:1fr 1fr;gap:28px 24px;margin-top:28px}
.dir h3{font-size:1.15rem;margin-bottom:10px}
.dir ul{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px}
.dir li{min-width:0}
.dir button,.dir a{border:0;background:none;padding:0;color:var(--ink);text-align:left;font-size:.98rem;text-decoration:none;line-height:1.45}
.dir button:hover,.dir a:hover{color:var(--primary)}
.dir .hot{color:var(--primary)}
.foot-b{background:linear-gradient(160deg,var(--pink-a) 0%,var(--pink-b) 45%,var(--pink-c) 100%);color:#FFFFFF;padding-block:36px calc(108px + env(safe-area-inset-bottom,0px))}
.foot-b h2{font-size:1.45rem;font-weight:400;color:#FFFFFF}
.foot-b h2 b{font-weight:700}
.foot-b .addr{color:rgba(255,255,255,.9);margin-top:14px;max-width:46ch}
.clist{list-style:none;margin:22px 0 0;padding:0;display:flex;flex-direction:column;gap:14px}
.clist li{display:grid;grid-template-columns:26px 1fr;gap:14px;align-items:center;min-width:0}
.clist svg{width:24px;height:24px;stroke:#FFFFFF;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.clist a,.clist span{color:#FFFFFF;text-decoration:none;font-size:1.02rem;overflow-wrap:anywhere}
.clist a:hover{text-decoration:underline}
.fnote{margin-top:30px;display:grid;grid-template-columns:26px 1fr;gap:14px;color:rgba(255,255,255,.88);font-size:.9rem}
.fnote svg{width:24px;height:24px;stroke:rgba(255,255,255,.88);fill:none;stroke-width:1.7}
.cta{display:flex;justify-content:center;align-items:center;gap:12px;margin-top:28px;background:#FFFFFF;color:var(--pink-ink);padding:22px 16px;font-family:var(--f-display);font-weight:700;font-size:1.3rem;text-decoration:none;border:4px solid var(--pink-ink)}
.cta svg{width:26px;height:26px;stroke:var(--pink-ink);fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.cta:hover{background:#FFF1F1}
@media (max-width:360px){.dir{grid-template-columns:1fr}}


/* tutor + results */
.finalist{border-radius:14px;overflow:hidden;border:1px solid var(--line);background:var(--surface)}
.fin-hd{background:linear-gradient(160deg,var(--pink-a) 0%,var(--pink-b) 45%,var(--pink-c) 100%);color:#FFFFFF;padding:20px 18px;display:flex;flex-direction:column;gap:6px}
.fin-hd .eyebrow{color:rgba(255,255,255,.9)}
.fin-hd h2{font-size:1.5rem;color:#FFFFFF}
.fin-hd p{color:rgba(255,255,255,.92);max-width:60ch}
.fin-bd{padding:18px;display:flex;flex-direction:column;gap:18px}
.subj{display:grid;grid-template-columns:1fr 1fr;gap:12px}
@media (max-width:520px){.subj{grid-template-columns:1fr}}
.subj div{background:var(--sunk);border-radius:10px;padding:12px 14px}
.subj h3{font-size:1.05rem}
.subj p{font-size:.9rem;color:var(--muted)}
.fmt{display:flex;gap:8px;flex-wrap:wrap}
.fmt span{font-size:.8rem;padding:4px 10px;border-radius:999px;border:1px solid var(--pink-b);color:var(--pink-ink)}
.tutor{display:grid;grid-template-columns:64px 1fr;gap:14px;align-items:start}
.ava{width:64px;height:64px;border-radius:50%;background:linear-gradient(160deg,var(--pink-a),var(--pink-c));color:#FFFFFF;display:grid;place-items:center;font-family:var(--f-display);font-weight:700;font-size:1.5rem}
.tutor h3{font-size:1.2rem}
.tutor .role{color:var(--muted);font-size:.9rem}
.cv{display:flex;flex-direction:column;gap:12px;margin-top:4px}
.cv h4{margin:0;font-family:var(--f-mono);font-size:.72rem;letter-spacing:.08em;color:var(--muted);font-weight:600}
.cv ul{margin:4px 0 0;padding-left:1.15em;display:flex;flex-direction:column;gap:4px;font-size:.94rem}
.cv .yr{font-family:var(--f-mono);font-size:.78rem;color:var(--pink-ink);margin-left:6px;white-space:nowrap}
.scores{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}
.sc{border:1px solid var(--line);border-radius:10px;padding:12px 14px;display:flex;flex-direction:column;gap:4px}
.sc .top{display:flex;justify-content:space-between;align-items:center;gap:8px}
.sc .rank{font-size:.75rem;font-weight:700;padding:2px 9px;border-radius:999px;background:var(--pink-ink);color:#FFFFFF}
.sc .rank.t{background:transparent;color:var(--pink-ink);border:1.5px solid var(--pink-ink)}
.sc b{font-family:var(--f-mono);font-size:1.6rem;font-variant-numeric:tabular-nums;line-height:1.1}
.sc small{color:var(--muted);font-size:.8rem}

/* exam board */
.board{background:var(--board);color:var(--board-fg);border-radius:14px;padding:20px 18px;display:flex;flex-direction:column;gap:6px}
.board .eyebrow{color:var(--accent)}
.board .bmeta{color:var(--board-mute);font-size:.9rem}
.board .bsub{color:var(--board-mute);font-size:.8rem;font-family:var(--f-mono);margin-top:4px}
.cd{display:grid;grid-template-columns:repeat(4,1fr);margin-top:8px}
.cd>div{display:flex;flex-direction:column;align-items:center;gap:2px;padding:4px 0;border-left:1.5px dashed var(--line)}
.cd>div:first-child{border-left:0}
.cd b{font-family:var(--f-mono);font-weight:600;font-variant-numeric:tabular-nums;font-size:1.5rem;line-height:1.1}
.cd span{font-size:.72rem;color:var(--muted);letter-spacing:.04em}
.cd.big{margin-block:12px 4px}
.cd.big>div{border-left-color:var(--board-mute)}
.cd.big b{font-size:clamp(2rem,9vw,3rem);color:var(--board-fg)}
.cd.big span{color:var(--board-mute)}
.cd-done{grid-column:1/-1;font-family:var(--f-display);text-align:center;padding:8px 0}
.exrow{display:flex;flex-direction:column;gap:6px;padding-block:14px;border-top:1px solid var(--line)}
.exrow:nth-child(2){border-top:0;padding-top:10px}
.exhd{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}
.exhd>div{min-width:0}
.exhd p{font-size:.85rem}
.dinput{font:inherit;padding:6px 10px;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--ink);max-width:100%}

/* ecomap */
.eco svg{width:100%;height:auto;display:block;max-width:440px;margin:0 auto}
.eco .node{cursor:pointer}
.eco .node:hover circle{stroke:var(--primary)}
.eco .node:focus-visible{outline:none}
.eco .node:focus-visible circle{stroke:var(--primary);stroke-width:3}
.legend{display:flex;flex-wrap:wrap;gap:14px;font-size:.8rem;color:var(--muted);justify-content:center}
.legend span{display:inline-flex;align-items:center;gap:6px}

.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.stat{background:var(--sunk);border-radius:8px;padding:10px 12px}
.stat b{display:block;font-family:var(--f-mono);font-size:1.15rem;font-variant-numeric:tabular-nums}
.stat span{font-size:.76rem;color:var(--muted)}
@media (max-width:520px){.stats{grid-template-columns:repeat(2,1fr)}}

.todo{display:flex;flex-direction:column}
.todo button{display:grid;grid-template-columns:28px 1fr auto;gap:12px;align-items:center;text-align:left;border:0;border-top:1px solid var(--line);background:none;padding:14px 0}
.todo button:first-child{border-top:0}
.todo .ic{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:var(--primary-soft);color:var(--primary);font-family:var(--f-mono);font-size:.8rem}
.todo small{display:block;color:var(--muted);font-size:.82rem}

/* topic list */
.topic{display:grid;grid-template-columns:1fr auto;gap:6px 14px;align-items:center;text-align:left;width:100%;border:1px solid var(--line);background:var(--surface);border-radius:var(--r);padding:14px 16px}
.topic:hover{border-color:var(--primary)}
.topic .meta{font-size:.82rem;color:var(--muted)}
.bar{grid-column:1/-1;height:6px;background:var(--sunk);border-radius:99px;overflow:hidden}
.bar i{display:block;height:100%;background:var(--primary);border-radius:99px}
.chk{font-family:var(--f-mono);font-size:.75rem;padding:3px 8px;border-radius:999px;background:var(--sunk);color:var(--muted);white-space:nowrap}
.chk.on{background:var(--good-soft);color:var(--good)}

/* lesson */
.lesson h2{margin-top:6px}
.lesson section{display:flex;flex-direction:column;gap:10px}
.lesson .body{max-width:65ch;display:flex;flex-direction:column;gap:10px}
.lesson ul,.lesson ol{margin:0;padding-left:1.3em;display:flex;flex-direction:column;gap:6px}
.lesson table{border-collapse:collapse;width:100%;font-size:.92rem}
.lesson th,.lesson td{border-bottom:1px solid var(--line);padding:8px 10px;text-align:left;vertical-align:top}
.lesson th{font-weight:600;background:var(--sunk)}
.tbl{overflow-x:auto}
.key{background:var(--accent-soft);border-radius:var(--r);padding:16px 18px}
.key ul{margin:8px 0 0;padding-left:1.2em}
.en{font-family:var(--f-mono);font-size:.8rem;color:var(--muted)}

/* chips */
.chips{display:flex;gap:8px;flex-wrap:wrap}
.chip{border:1px solid var(--line);background:var(--surface);border-radius:999px;padding:6px 12px;font-size:.85rem}
.chip[aria-pressed="true"]{background:var(--ink);color:var(--paper);border-color:var(--ink)}

/* modes */
.modes{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
@media (max-width:520px){.modes{grid-template-columns:1fr}}
.mode{text-align:left;border:1px solid var(--line);background:var(--surface);border-radius:var(--r);padding:16px;display:flex;flex-direction:column;gap:6px}
.mode:hover{border-color:var(--primary)}
.mode .tag{font-family:var(--f-mono);font-size:.72rem;color:var(--accent);letter-spacing:.06em}
.mode p{font-size:.88rem;color:var(--muted)}

/* quiz */
.qhead{display:flex;justify-content:space-between;align-items:center;gap:10px}
.qtext{font-size:1.08rem;font-weight:500;max-width:65ch}
.choices{display:flex;flex-direction:column;gap:10px}
.choice{display:grid;grid-template-columns:30px 1fr;gap:10px;align-items:start;text-align:left;border:1px solid var(--line);background:var(--surface);border-radius:var(--r);padding:12px 14px}
.choice:hover:not([disabled]){border-color:var(--primary)}
.choice .l{font-family:var(--f-mono);width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:var(--sunk);font-size:.82rem}
.choice.sel{border-color:var(--primary);background:var(--primary-soft)}
.choice.ok{border-color:var(--good);background:var(--good-soft)}
.choice.no{border-color:var(--bad);background:var(--bad-soft)}
.choice[disabled]{cursor:default}
.explain{border-left:3px solid var(--accent);background:var(--accent-soft);padding:12px 14px;border-radius:0 8px 8px 0;font-size:.94rem}
.prog{height:4px;background:var(--sunk);border-radius:99px;overflow:hidden}
.prog i{display:block;height:100%;background:var(--accent)}
.grid-n{display:grid;grid-template-columns:repeat(10,1fr);gap:6px}
.grid-n button{border:1px solid var(--line);background:var(--surface);border-radius:6px;padding:6px 0;font-family:var(--f-mono);font-size:.78rem}
.grid-n button.done{background:var(--primary-soft);border-color:var(--primary)}
.grid-n button.cur{outline:2px solid var(--accent)}
.grid-n button.ok{background:var(--good-soft);border-color:var(--good)}
.grid-n button.no{background:var(--bad-soft);border-color:var(--bad)}
.timer{font-family:var(--f-mono);font-variant-numeric:tabular-nums;background:var(--sunk);padding:4px 10px;border-radius:6px}
.timer.low{background:var(--bad-soft);color:var(--bad)}
.score{font-family:var(--f-display);font-size:2.8rem;font-weight:700;color:var(--primary);line-height:1}

/* flashcards */
.fc{perspective:1200px}
.fc-in{position:relative;min-height:230px;transition:transform .45s;transform-style:preserve-3d;cursor:pointer}
.fc-in.flip{transform:rotateY(180deg)}
.face{position:absolute;inset:0;backface-visibility:hidden;-webkit-backface-visibility:hidden;border:1px solid var(--line);background:var(--surface);border-radius:14px;padding:22px;display:flex;flex-direction:column;justify-content:center;gap:8px}
.face.back{transform:rotateY(180deg);background:var(--primary-soft)}
.face .term{font-family:var(--f-display);font-size:1.6rem;font-weight:700}
@media (prefers-reduced-motion:reduce){.fc-in{transition:none}}

/* case file */
.casefile{border:1px solid var(--line);background:var(--surface);border-radius:var(--r);overflow:hidden}
.casefile .hd{display:grid;grid-template-columns:repeat(3,1fr);border-bottom:1px solid var(--line);background:var(--sunk)}
.casefile .hd div{padding:8px 12px;border-right:1px solid var(--line);min-width:0}
.casefile .hd div:last-child{border-right:0}
.casefile .hd span{display:block;font-family:var(--f-mono);font-size:.68rem;color:var(--muted);letter-spacing:.06em}
.casefile .hd b{font-weight:500;font-size:.9rem}
.casefile .bd{padding:16px 18px;display:flex;flex-direction:column;gap:12px}
.pts{font-family:var(--f-mono);font-size:.78rem;padding:2px 8px;border-radius:999px}
.pts.p2{background:var(--good-soft);color:var(--good)} .pts.p1{background:var(--accent-soft);color:var(--accent)} .pts.p0{background:var(--bad-soft);color:var(--bad)}

/* essay */
textarea{width:100%;min-height:220px;font:inherit;line-height:1.7;padding:12px 14px;border:1px solid var(--line);border-radius:var(--r);background:var(--surface);color:var(--ink);resize:vertical}
.rub label{display:flex;gap:10px;align-items:flex-start;padding:8px 0;border-top:1px solid var(--line);font-size:.93rem}
.rub label:first-of-type{border-top:0}
.rub input{margin-top:5px;accent-color:var(--primary)}
.note{font-size:.8rem;color:var(--muted);max-width:65ch}
.back{display:inline-flex;gap:6px;align-items:center}

/* Thai labels: use the Thai face, no wide tracking (Plex Mono has no Thai glyphs) */
.eyebrow,.cv h4,.mode .tag,.chk,.casefile .hd span,.bsub,.yr,.note.mono{font-family:var(--f-body);letter-spacing:.01em;text-transform:none}
.eyebrow,.cv h4{font-size:.8rem;font-weight:700}
.cv h4{color:var(--pink-ink);font-size:.88rem}
.mode .tag{font-weight:700;font-size:.8rem}
.chk{font-size:.8rem}
.casefile .hd span{font-size:.75rem}
.yr{font-size:.82rem}

/* ===== polish pass ===== */
body{font-size:17px;line-height:1.6}
h1{font-size:2rem;line-height:1.2} h2{font-size:1.4rem} h3{font-size:1.15rem}
.top{background:color-mix(in srgb,var(--paper) 88%,transparent);backdrop-filter:saturate(1.4) blur(10px);-webkit-backdrop-filter:saturate(1.4) blur(10px);border-bottom:0;box-shadow:0 1px 0 var(--line)}
.brand b{font-size:1.1rem}
.brand .eyebrow{color:var(--primary)}
.hlogo{width:42px;height:42px;border-radius:11px;box-shadow:var(--shadow)}
.seg{background:var(--sunk)}
.seg button{font-weight:700;padding:7px 14px}
.seg button[aria-pressed="true"]{background:var(--primary);color:var(--primary-ink);box-shadow:0 2px 8px color-mix(in srgb,var(--primary) 35%,transparent)}
main{padding-block-start:22px}
.stack{gap:20px}
.panel{border:0;box-shadow:var(--shadow);border-radius:var(--r);padding:20px}
.topic,.mode,.choice,.casefile,.finalist,.sc{border-color:transparent;box-shadow:var(--shadow);border-radius:var(--r)}
.topic:hover,.mode:hover,.choice:hover:not([disabled]){border-color:var(--primary);transform:translateY(-1px)}
.topic,.mode,.choice{transition:transform .15s ease,border-color .15s ease}
@media (prefers-reduced-motion:reduce){.topic,.mode,.choice{transition:none}.topic:hover,.mode:hover,.choice:hover:not([disabled]){transform:none}}
.btn{font-weight:700;padding:11px 20px}
.btn.primary{box-shadow:0 4px 14px color-mix(in srgb,var(--primary) 30%,transparent)}
.link{font-weight:700}
.chip{font-weight:700;border-color:var(--line)}
.chip[aria-pressed="true"]{background:var(--primary);border-color:var(--primary);color:var(--primary-ink)}
.bar{height:8px}
.bar i{background:linear-gradient(90deg,var(--pink-a),var(--primary))}
.stat{background:var(--surface);box-shadow:var(--shadow);border-radius:14px;padding:14px}
.stat b{color:var(--primary);font-size:1.3rem}
.todo .ic{background:var(--primary);color:var(--primary-ink);font-weight:600}
.todo button{padding:15px 0}
.streak{background:var(--primary-soft);font-weight:700}
.streak i{background:var(--primary)}
.nav{background:color-mix(in srgb,var(--surface) 92%,transparent);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border-top:1px solid var(--line)}
.nav button{font-size:.78rem;font-weight:700;position:relative}
.nav button[aria-current="page"]::before{content:"";position:absolute;top:2px;left:50%;transform:translateX(-50%);width:48px;height:30px;border-radius:999px;background:var(--primary-soft);z-index:-1}
.nav button[aria-current="page"] svg{stroke-width:2.2}
.eco{padding:16px}
.key{background:var(--primary-soft);border-radius:var(--r)}
.key h3{color:var(--primary)}
.explain{border-left-color:var(--primary);background:var(--primary-soft)}
.prog i{background:linear-gradient(90deg,var(--pink-a),var(--primary))}
.face{border:0;box-shadow:var(--shadow);border-radius:20px}
.face.back{background:linear-gradient(160deg,var(--pink-a),var(--pink-c));color:#FFFFFF}
.face.back .eyebrow{color:rgba(255,255,255,.9)}
.face .term{font-size:1.9rem;color:var(--primary)}
.casefile .hd{background:var(--primary-soft)}
.casefile .hd div{border-right-color:var(--line)}
.score{color:var(--primary)}
/* hero countdown: logo sticker style */
.board{background:linear-gradient(155deg,var(--pink-a) 0%,var(--pink-b) 48%,var(--pink-c) 100%);color:#FFFFFF;border-radius:22px;padding:24px 20px 20px;box-shadow:0 12px 30px color-mix(in srgb,var(--pink-c) 30%,transparent)}
.board .eyebrow{color:rgba(255,255,255,.92)}
.board h2{color:#FFFFFF;font-size:1.55rem}
.board .bmeta{color:rgba(255,255,255,.92)}
.board .bsub{color:rgba(255,255,255,.85)}
.cd.big>div{border-left:2px dashed rgba(255,255,255,.55)}
.cd.big b{color:#FFFFFF;font-family:var(--f-display);font-weight:700;font-size:clamp(2.4rem,11vw,3.6rem);line-height:1.05;text-shadow:0 0 0 #D9131B,2px 0 0 #D9131B,-2px 0 0 #D9131B,0 2px 0 #D9131B,0 -2px 0 #D9131B,2px 2px 0 #D9131B,-2px -2px 0 #D9131B,2px -2px 0 #D9131B,-2px 2px 0 #D9131B,3px 0 0 #D9131B,-3px 0 0 #D9131B,0 3px 0 #D9131B,0 -3px 0 #D9131B,0 6px 10px rgba(120,0,10,.25);font-variant-numeric:tabular-nums}
.cd.big span{color:rgba(255,255,255,.95);font-weight:700}
.cd b{color:var(--primary)}
.exrow h3{font-size:1.1rem}
/* finalist: blush header so the page keeps just two pink blocks */
.fin-hd{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);color:#fff}
.fin-hd .eyebrow{color:rgba(255,255,255,.92);text-shadow:0 1px 2px rgba(120,0,0,.25)}
.fin-hd h2{color:#fff;font-size:1.6rem;text-shadow:0 2px 6px rgba(120,0,0,.35)}
.fin-hd p{color:#fff;text-shadow:0 1px 3px rgba(120,0,0,.3)}
.subj div{background:var(--paper)}
.sc b{color:var(--primary)}
.foot-a{background:var(--sunk)}

/* CTA: white embossed pill, pink lettering */
.cta{border:0;border-radius:999px;margin-top:32px;padding:20px 24px;
  background:linear-gradient(180deg,#FFFFFF 0%,#FFF4F4 55%,#FFE3E3 100%);
  box-shadow:inset 0 2px 0 rgba(255,255,255,1),inset 0 -4px 8px rgba(242,74,74,.16),0 3px 0 #F5C9C9,0 14px 26px rgba(150,20,35,.32);
  transition:transform .12s ease,box-shadow .12s ease}
.cta span{background:linear-gradient(180deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent}
.cta svg{stroke:#F24A4A;stroke-width:2.2}
.cta:hover{background:linear-gradient(180deg,#FFFFFF 0%,#FFF7F7 55%,#FFEAEA 100%);transform:translateY(-1px)}
.cta:active{transform:translateY(2px);box-shadow:inset 0 2px 0 #fff,inset 0 -2px 6px rgba(242,74,74,.2),0 1px 0 #F5C9C9,0 6px 12px rgba(150,20,35,.28)}
@media (prefers-reduced-motion:reduce){.cta{transition:none}}

/* small countdowns: same sticker numerals as the hero */
.cd:not(.big) b{font-family:var(--f-display);font-weight:700;font-size:clamp(2rem,8vw,2.6rem);line-height:1.1;color:#FFFFFF;text-shadow:2px 0px 0 #D9131B,-2px 0px 0 #D9131B,0px 2px 0 #D9131B,0px -2px 0 #D9131B,2px 2px 0 #D9131B,-2px -2px 0 #D9131B,2px -2px 0 #D9131B,-2px 2px 0 #D9131B,0 4px 8px rgba(150,20,35,.18)}
.cd:not(.big)>div{border-left:2px dashed var(--line)}
.cd:not(.big)>div:first-child{border-left:0}
.cd:not(.big) span{font-weight:700}
.board .bsub{font-family:var(--f-body);font-size:.88rem}

/* SWPC card: white fade, pink numerals same size as hero, no outline */
.swcard{background:linear-gradient(180deg,#FFFFFF 0%,#FFF5F5 55%,#FFE4E4 100%);border-radius:22px;box-shadow:inset 0 2px 0 #FFFFFF,0 3px 0 #F7D0D0,0 12px 28px rgba(150,20,35,.12)}
.cd:not(.big) b{font-size:clamp(2.4rem,11vw,3.6rem);line-height:1.05;text-shadow:none;
  background:linear-gradient(180deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent;padding-inline:2px}
.cd:not(.big)>div{border-left:2px dashed #F6C4C4}
.cd:not(.big)>div:first-child{border-left:0}
.cd:not(.big) span{color:#D93636}
.swcard .exrow{border-top-color:#F5D2D2}
.swcard .dinput{background:#FFFFFF;border-color:#F2C8C8}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]) .swcard{background:linear-gradient(180deg,#2A1C20 0%,#2E1D22 55%,#3A1F27 100%);box-shadow:var(--shadow)}
 :root:not([data-theme="light"]) .swcard .dinput{background:var(--surface);border-color:var(--line)}}
:root[data-theme="dark"] .swcard{background:linear-gradient(180deg,#2A1C20 0%,#2E1D22 55%,#3A1F27 100%);box-shadow:var(--shadow)}
:root[data-theme="dark"] .swcard .dinput{background:var(--surface);border-color:var(--line)}

/* hero numerals: plain white, no outline */
.cd.big b{text-shadow:0 3px 10px rgba(140,10,20,.22)}

.fig{margin:4px 0;display:flex;flex-direction:column;gap:8px;align-items:center}
.fig svg{width:100%;max-width:400px;height:auto;display:block}
.fig figcaption{font-size:.85rem;color:var(--muted);text-align:center;max-width:52ch}

/* results + buttons in logo pink gradient */
.sc{background:linear-gradient(180deg,#FFFFFF 0%,#FFF5F5 55%,#FFE4E4 100%);border:0;border-radius:20px;padding:16px;gap:6px;box-shadow:inset 0 2px 0 #FFFFFF,0 3px 0 #F7D0D0,0 10px 22px rgba(150,20,35,.10)}
.sc .rank{align-self:flex-start;white-space:nowrap;font-size:.78rem;padding:3px 11px;border-radius:999px;background:linear-gradient(180deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);color:#FFFFFF;border:0;box-shadow:0 2px 6px rgba(227,20,20,.25)}
.sc .rank.t{background:#FFFFFF;color:#E31414;border:1.5px solid #F24A4A;box-shadow:none}
.sc-name{font-weight:700;font-size:1rem;color:var(--ink)}
.sc b{font-family:var(--f-display);font-weight:700;font-size:clamp(2.2rem,10vw,2.8rem);line-height:1.05;background:linear-gradient(180deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent;padding-inline:2px}
.sc small{color:#D93636}
.btn.primary{background:linear-gradient(180deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);border:0;color:#FFFFFF;box-shadow:inset 0 2px 0 rgba(255,255,255,.35),0 3px 0 #C10F10,0 10px 20px rgba(227,20,20,.28)}
.btn.primary:active{transform:translateY(2px);box-shadow:inset 0 2px 0 rgba(255,255,255,.3),0 1px 0 #C10F10,0 4px 10px rgba(227,20,20,.25)}
.logo-btn{display:block;text-align:center;text-decoration:none;padding-block:15px;font-size:1.05rem}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]) .sc{background:linear-gradient(180deg,#2A1C20 0%,#2E1D22 55%,#3A1F27 100%);box-shadow:var(--shadow)}}
:root[data-theme="dark"] .sc{background:linear-gradient(180deg,#2A1C20 0%,#2E1D22 55%,#3A1F27 100%);box-shadow:var(--shadow)}

/* calendar */
.nav button{font-size:.72rem}
.phase{border-radius:22px;padding:20px;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);color:#FFFFFF;display:flex;flex-direction:column;gap:8px;box-shadow:0 12px 28px rgba(200,20,30,.25)}
.phase .eyebrow{color:rgba(255,255,255,.92)} .phase h2{color:#FFFFFF;font-size:1.5rem} .phase p{color:rgba(255,255,255,.95);max-width:60ch}
.ph-steps{display:flex;gap:6px}
.ph-steps span{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font-weight:700;font-size:.85rem;border:1.5px solid rgba(255,255,255,.6);color:#FFFFFF}
.ph-steps span.done{background:rgba(255,255,255,.3);border-color:transparent}
.ph-steps span.on{background:#FFFFFF;color:#E31414;border-color:#FFFFFF}
.ph-tasks{display:flex;flex-direction:column;gap:8px;margin-top:4px}
.ph-tasks button{display:flex;justify-content:space-between;align-items:center;gap:10px;text-align:left;border:0;border-radius:14px;padding:12px 14px;background:linear-gradient(180deg,#FFFFFF,#FFEDED);color:#C81E1E;font-weight:700;box-shadow:0 2px 0 rgba(150,10,20,.25)}
.ph-note{font-size:.8rem;opacity:.9}
.calhd{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}
.navbtn{width:40px;height:40px;border-radius:50%;border:0;background:var(--primary-soft);color:var(--primary);font-size:1.4rem;font-weight:700;line-height:1}
.grid7{display:grid;grid-template-columns:repeat(7,1fr);gap:4px}
.dow span{text-align:center;font-size:.78rem;font-weight:700;color:var(--muted);padding-block:4px}
.day{aspect-ratio:1;border:0;background:transparent;border-radius:12px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;padding:0;min-width:0}
.day span{font-size:.95rem;font-variant-numeric:tabular-nums}
.day i{display:flex;gap:2px;height:6px}
.day i b,.legend2 b{width:6px;height:6px;border-radius:50%;display:inline-block}
.day:hover{background:var(--sunk)}
.day.hot{background:var(--primary-soft)}
.day.today span{color:var(--primary);font-weight:700}
.day.today{box-shadow:inset 0 0 0 2px var(--primary)}
.day.sel{background:linear-gradient(180deg,#FF7A7A,#E31414)}
.day.sel span{color:#FFFFFF;font-weight:700}
.day.sel i b{background:#FFFFFF!important}
.k-exam{background:#E31414} .k-reg{background:var(--accent)} .k-ann{background:#8C6A73} .k-mine{background:var(--good)}
.legend2{display:flex;flex-wrap:wrap;gap:12px;margin-top:10px;font-size:.8rem;color:var(--muted)}
.legend2 span{display:inline-flex;align-items:center;gap:6px}
.evl,.agenda{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px}
.evl li{display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:center;background:var(--paper);border-radius:12px;padding:10px 12px;border-left:4px solid var(--line);min-width:0}
.evl li.k-exam{border-left-color:#E31414;background:var(--paper)} .evl li.k-reg{border-left-color:var(--accent);background:var(--paper)} .evl li.k-ann{border-left-color:#8C6A73;background:var(--paper)} .evl li.k-mine{border-left-color:var(--good);background:var(--paper)}
.evl .tag{font-size:.75rem;font-weight:700;color:var(--muted);white-space:nowrap}
.tt{min-width:0;overflow-wrap:anywhere;display:flex;flex-direction:column}
.tt small{color:var(--muted);font-size:.8rem}
.del{border:0;background:none;color:var(--bad);font-weight:700;font-size:.85rem}
.addev{display:flex;flex-direction:column;gap:10px;border-top:1px solid var(--line);padding-top:14px}
.addrow{display:grid;grid-template-columns:1fr auto auto;gap:8px}
@media (max-width:480px){.addrow{grid-template-columns:1fr 1fr}.addrow input{grid-column:1/-1}}
.addrow input,.addrow select{font:inherit;padding:10px 12px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--ink);min-width:0}
.agenda button{display:grid;grid-template-columns:48px 1fr auto;gap:12px;align-items:center;width:100%;text-align:left;border:0;background:none;padding:6px 0;border-top:1px solid var(--line)}
.agenda li:first-child button{border-top:0}
.ad{display:flex;flex-direction:column;align-items:center;border-radius:12px;background:var(--primary-soft);padding:4px 0}
.ad b{font-size:1.3rem;line-height:1.1;color:var(--primary)} .ad small{font-size:.72rem;color:var(--primary)}
.at small{background:none!important;font-size:.8rem;font-weight:700}
.at small.k-exam{color:#E31414} .at small.k-reg{color:var(--accent)} .at small.k-ann{color:#8C6A73} .at small.k-mine{color:var(--good)}
.at{display:flex;flex-direction:column;min-width:0}
.al{font-size:.8rem;font-weight:700;color:var(--muted);white-space:nowrap}
.al.hot{color:#FFFFFF;background:linear-gradient(180deg,#FF7A7A,#E31414);padding:3px 10px;border-radius:999px}
.week{display:grid;grid-template-columns:repeat(7,1fr);gap:6px}
.week div{background:var(--paper);border-radius:12px;padding:8px 6px;display:flex;flex-direction:column;gap:4px;min-width:0}
.week b{font-size:.85rem;text-align:center}
.week span{font-size:.72rem;line-height:1.35;color:var(--muted);overflow-wrap:anywhere}
.week .now{background:linear-gradient(180deg,#FF7A7A,#E31414)} .week .now b,.week .now span{color:#FFFFFF}
@media (max-width:560px){.week{grid-template-columns:1fr}.week div{flex-direction:row;align-items:baseline;gap:12px;padding:8px 12px}.week b{min-width:2em;text-align:left}.week span{font-size:.85rem}}

/* day overview + timetable */
.overview{display:flex;flex-direction:column;gap:12px}
.ov-hd{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}
.ov-hd h2{font-size:1.35rem}
.ov-sum{font-size:.88rem}
.ov-ring{position:relative;width:64px;height:64px;flex-shrink:0}
.ring{width:64px;height:64px}
.ov-ring span{position:absolute;inset:0;display:grid;place-items:center;font-weight:700;font-size:.9rem;color:var(--primary)}
.ov-h{font-size:1rem;color:var(--primary);margin-top:4px}
.offl{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px}
.offl li{display:flex;gap:8px;align-items:baseline;font-size:.92rem;background:var(--paper);border-radius:10px;padding:8px 12px}
.offl li.hot{background:var(--primary-soft);font-weight:700}
.offl b{width:8px;height:8px;border-radius:50%;flex-shrink:0;display:inline-block}
.offl small{color:var(--muted);font-weight:400}
.tl{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;position:relative}
.tl li{display:grid;grid-template-columns:56px 1fr auto;gap:12px;align-items:center;padding:8px 0;position:relative}
.tl li+li{border-top:1px dashed var(--line)}
.tm{display:flex;flex-direction:column;font-variant-numeric:tabular-nums;font-weight:700;font-size:.95rem;line-height:1.2}
.tm small{font-weight:400;color:var(--muted);font-size:.8rem}
.cn{display:flex;flex-direction:column;min-width:0;border-left:3px solid var(--primary-soft);padding-left:12px}
.cn b{font-size:1rem;overflow-wrap:anywhere} .cn small{color:var(--muted);font-size:.82rem}
.tl li.past{opacity:.5}
.tl li.live .cn{border-left-color:#E31414}
.live-tag{font-size:.75rem;font-weight:700;color:#FFFFFF;background:linear-gradient(180deg,#FF7A7A,#E31414);padding:3px 10px;border-radius:999px;white-space:nowrap}
.empty-tt{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;background:var(--paper);border-radius:12px;padding:12px 14px;font-size:.92rem;color:var(--muted)}
.checks{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px}
.checks li{display:flex;align-items:center;gap:10px;background:var(--paper);border-radius:12px;padding:10px 12px}
.checks label{display:flex;gap:12px;align-items:center;flex:1;min-width:0;cursor:pointer}
.checks input{width:22px;height:22px;accent-color:#E31414;flex-shrink:0}
.ck-t{display:flex;flex-direction:column;min-width:0}
.ck-t b{font-weight:700;overflow-wrap:anywhere} .ck-t small{color:var(--muted);font-size:.8rem}
.checks li.done .ck-t b{text-decoration:line-through;color:var(--muted)}
.soon{display:flex;flex-direction:column;gap:4px;background:var(--accent-soft);border-radius:12px;padding:10px 14px;font-size:.9rem}
.soon b{color:var(--accent)}
.ttdays{display:grid;grid-template-columns:repeat(7,1fr);gap:6px}
.ttdays button{border:0;border-radius:12px;padding:8px 0;background:var(--paper);font-weight:700;display:flex;flex-direction:column;align-items:center;line-height:1.2}
.ttdays button small{font-size:.7rem;color:var(--muted);min-height:1em}
.ttdays button[aria-selected="true"]{background:linear-gradient(180deg,#FF7A7A,#E31414);color:#FFFFFF}
.ttdays button[aria-selected="true"] small{color:rgba(255,255,255,.9)}
.ttrow{display:grid;grid-template-columns:1.4fr .8fr .8fr 1.4fr auto;gap:8px}
@media (max-width:560px){.ttrow{grid-template-columns:1fr 1fr}.ttrow #tt-sub,.ttrow #tt-rm,.ttrow .btn{grid-column:1/-1}}
.ttrow input{font:inherit;padding:10px 12px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--ink);min-width:0}

/* ===== layout rhythm ===== */
.home{display:flex;flex-direction:column;gap:36px}
.sec{display:flex;flex-direction:column;gap:12px}
.sechd{display:flex;justify-content:space-between;align-items:flex-end;gap:12px}
.sechd h2{font-size:1.45rem}
.sechd .link{white-space:nowrap;padding-bottom:4px}
.hello{display:flex;flex-direction:column;gap:10px;padding-top:4px}
.hello .eyebrow{color:var(--primary)}
.hello h1{font-size:clamp(1.8rem,7vw,2.4rem);line-height:1.25}
.hello h1 em{font-style:normal;background:linear-gradient(180deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent}
.hello-chips{display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.streak{padding:6px 12px;font-size:.85rem}
.pchip{border:0;border-radius:999px;padding:6px 12px;font-size:.85rem;font-weight:700;background:var(--surface);color:var(--ink);box-shadow:var(--shadow)}
.pagehd{display:flex;flex-direction:column;gap:6px}
.pagehd .eyebrow{color:var(--primary)}
.pagehd p{max-width:60ch}
.progress{display:flex;flex-direction:column;gap:16px}
.progress .stat{background:var(--paper);box-shadow:none}
.progress .eco{padding:0}
.eco-cap{font-size:.85rem;text-align:center;max-width:52ch;margin:0 auto}
.todo{padding-block:6px}
.overview .ov-hd h2{font-size:1.25rem}
.overview{scroll-margin-top:96px}
.sec>.board,.sec>.stack>.board{margin:0}

/* accounts */
.avatar-btn{width:40px;height:40px;border-radius:50%;border:0;flex-shrink:0;background:linear-gradient(180deg,#FF7A7A,#E31414);color:#FFFFFF;font-weight:700;font-size:1.05rem;box-shadow:0 2px 8px rgba(227,20,20,.3)}
.avatar-btn.guest{background:var(--sunk);color:var(--muted);box-shadow:none}
@media (max-width:440px){.brand{display:none}.top{gap:8px}}
body.authmode .top,body.authmode .nav{display:none}
body.authmode main{padding-block:28px 40px}
.auth{display:flex;flex-direction:column;gap:20px;max-width:480px;margin:0 auto}
.auth-hero{display:flex;flex-direction:column;align-items:center;text-align:center;gap:10px}
.auth-logo{width:96px;height:96px;border-radius:24px;box-shadow:0 10px 24px rgba(227,20,20,.25)}
.auth-hero h1{font-size:2rem;line-height:1.2}
.auth-hero h1 em,.hello h1 em{font-style:normal;background:linear-gradient(180deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent}
.auth-hero p{color:var(--muted);font-size:.95rem}
.auth-card{background:linear-gradient(180deg,#FFFFFF 0%,#FFF7F7 100%);border-radius:24px;padding:20px;box-shadow:inset 0 2px 0 #FFFFFF,0 3px 0 #F7D0D0,0 14px 30px rgba(150,20,35,.12);display:flex;flex-direction:column;gap:18px}
.auth-tabs{display:grid;grid-template-columns:1fr 1fr;background:var(--sunk);border-radius:999px;padding:4px}
.auth-tabs button{border:0;background:none;border-radius:999px;padding:10px;font-weight:700;color:var(--muted)}
.auth-tabs button[aria-selected="true"]{background:linear-gradient(180deg,#FF7A7A,#E31414);color:#FFFFFF;box-shadow:0 2px 8px rgba(227,20,20,.3)}
.fgrid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
@media (max-width:420px){.fgrid{grid-template-columns:1fr}}
.fld{display:flex;flex-direction:column;gap:6px;min-width:0}
.fld.wide{grid-column:1/-1}
.fld label,.fld .lbl{font-size:.88rem;font-weight:700}
.fld i{color:#E31414;font-style:normal}
.fld small{font-weight:400;color:var(--muted)}
.fld input,.fld select{font:inherit;padding:12px 14px;border:1.5px solid var(--line);border-radius:14px;background:var(--surface);color:var(--ink);min-width:0;width:100%}
.fld input:focus,.fld select:focus{border-color:#F24A4A;outline:none;box-shadow:0 0 0 3px rgba(242,74,74,.18)}
.fld input:disabled{background:var(--sunk);color:var(--muted)}
.goals{gap:8px}
.gchip{position:relative;cursor:pointer}
.gchip input{position:absolute;opacity:0;pointer-events:none}
.gchip span{display:inline-block;border:1.5px solid var(--line);border-radius:999px;padding:7px 14px;font-size:.88rem;font-weight:700;background:var(--surface)}
.gchip input:checked+span{background:linear-gradient(180deg,#FF7A7A,#E31414);border-color:transparent;color:#FFFFFF}
.gchip input:focus-visible+span{outline:2px solid #E31414;outline-offset:2px}
.consent{display:flex;gap:10px;align-items:flex-start;font-size:.85rem;color:var(--muted);line-height:1.5}
.consent input{width:20px;height:20px;margin-top:2px;accent-color:#E31414;flex-shrink:0}
.ferr{background:var(--bad-soft);color:var(--bad);border-radius:12px;padding:10px 14px;font-size:.9rem;font-weight:700}
.fok{background:var(--good-soft);color:var(--good);border-radius:12px;padding:10px 14px;font-size:.9rem;font-weight:700}
.btn.big{padding:15px;font-size:1.05rem;width:100%}
.small{font-size:.88rem;text-align:center}
.guest-link{align-self:center}
.auth-note{text-align:center;margin:0 auto}
.pcard{display:grid;grid-template-columns:auto 1fr;gap:16px;align-items:center;border-radius:24px;padding:22px 20px;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);color:#FFFFFF;box-shadow:0 12px 28px rgba(200,20,30,.25)}
.pcard .eyebrow{color:rgba(255,255,255,.9)} .pcard h1{color:#FFFFFF;font-size:1.8rem} .pcard p{color:#FFFFFF}
.psub{opacity:.9;font-size:.9rem}
.pava{width:72px;height:72px;border-radius:50%;background:#FFFFFF;color:#E31414;display:grid;place-items:center;font-size:2rem;font-weight:700;box-shadow:inset 0 -3px 6px rgba(242,74,74,.2)}
.pgoals{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}
.pgoals span{background:rgba(255,255,255,.22);border-radius:999px;padding:3px 10px;font-size:.8rem;font-weight:700}
.plist{margin:0;padding-left:1.2em;display:flex;flex-direction:column;gap:6px;font-size:.92rem}
.delbox{background:var(--bad-soft);border-radius:14px;padding:14px;display:flex;flex-direction:column;gap:10px}
.btn.danger{background:var(--bad);border-color:var(--bad);color:#FFFFFF}
.danger-link{color:var(--bad)}
.logout{align-self:center;min-width:200px}

/* round 3 features */
.mode.featured{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);color:#FFFFFF}
.mode.featured .tag{color:rgba(255,255,255,.95)} .mode.featured p{color:rgba(255,255,255,.92)} .mode.featured h3{color:#FFFFFF}
.lockbox{display:grid;grid-template-columns:auto 1fr;gap:12px 14px;align-items:center;background:linear-gradient(180deg,#FFFFFF,#FFF2F2);border-radius:20px;padding:18px;box-shadow:inset 0 2px 0 #FFFFFF,0 3px 0 #F7D0D0,0 10px 22px rgba(150,20,35,.10)}
.lockbox>form,.lockbox>.ferr,.lockbox>a{grid-column:1/-1}
.lk-ic{width:46px;height:46px;border-radius:14px;display:grid;place-items:center;background:linear-gradient(180deg,#FF7A7A,#E31414)}
.lk-ic svg{width:24px;height:24px;stroke:#FFFFFF;fill:none;stroke-width:2;stroke-linecap:round}
.unrow{display:grid;grid-template-columns:1fr auto;gap:8px}
.unrow input{font:inherit;padding:11px 14px;border:1.5px solid var(--line);border-radius:14px;background:var(--surface);color:var(--ink);min-width:0;letter-spacing:.05em}
.bigscore{font-family:var(--f-display);font-weight:700;font-size:4.2rem;line-height:1;color:#FFFFFF;text-shadow:0 3px 10px rgba(140,10,20,.22)}
.missions{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
@media (max-width:520px){.missions{grid-template-columns:1fr}}
.mis{border:0;text-align:left;border-radius:16px;padding:12px 14px;background:var(--surface);box-shadow:var(--shadow);display:flex;flex-direction:column;gap:8px}
.mis .mt{display:flex;justify-content:space-between;gap:8px;align-items:baseline}
.mis b{font-size:.92rem} .mis small{color:var(--muted);font-size:.8rem;white-space:nowrap}
.mbar{height:6px;border-radius:99px;background:var(--sunk);overflow:hidden;display:block}
.mbar i{display:block;height:100%;background:linear-gradient(90deg,#FF7A7A,#E31414);border-radius:99px}
.mis.done{background:linear-gradient(180deg,#FFFFFF,#FFEDED)} .mis.done small{color:#E31414;font-weight:700}
.duebar{display:flex;justify-content:space-between;align-items:center;gap:10px;border:0;text-align:left;border-radius:16px;padding:14px 16px;background:var(--accent-soft);color:var(--ink)}
.duebar small{display:block;color:var(--muted);font-size:.82rem} .duebar>span:last-child{font-weight:700;color:var(--accent);white-space:nowrap}
.wk{display:flex;flex-direction:column;gap:8px}
.wchart{width:100%;height:auto;max-width:420px;display:block;margin:0 auto}
.cloudcta{border:0;text-align:left;border-radius:16px;padding:14px 16px;background:linear-gradient(180deg,#FFF5F5,#FFE4E4);display:flex;flex-direction:column;gap:2px;color:var(--ink)}
.cloudcta b{color:#E31414} .cloudcta small{color:var(--muted)}
.consent .link{font-size:inherit}
.ivq{border-radius:22px;padding:22px 20px;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);color:#FFFFFF;display:flex;flex-direction:column;gap:12px;box-shadow:0 12px 28px rgba(200,20,30,.22)}
.ivq .eyebrow{color:rgba(255,255,255,.92)} .ivq h1{color:#FFFFFF;font-size:1.6rem}
.ivtimer{display:flex;align-items:center;gap:14px;flex-wrap:wrap}
.ivt{font-family:var(--f-display);font-weight:700;font-size:2.6rem;line-height:1;font-variant-numeric:tabular-nums}
.ivt.low{opacity:.75}
.ivq .btn.primary{background:#FFFFFF;color:#E31414;box-shadow:0 3px 0 rgba(150,10,20,.25)}
.avoid{background:var(--bad-soft);border-radius:12px;padding:10px 14px;font-size:.92rem}
.issue{background:var(--surface);border-radius:var(--r);box-shadow:var(--shadow);padding:16px 18px}
.issue summary{cursor:pointer;list-style:none;display:flex;flex-direction:column;gap:2px}
.issue summary::-webkit-details-marker{display:none}
.issue summary h3::after{content:" ›";color:var(--primary)}
.issue[open] summary{margin-bottom:10px}
.think{background:var(--primary-soft);border-radius:12px;padding:10px 14px}
.badges{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
@media (max-width:520px){.badges{grid-template-columns:repeat(2,1fr)}}
.badge{border-radius:16px;padding:14px 12px;background:var(--sunk);display:flex;flex-direction:column;align-items:center;text-align:center;gap:4px;opacity:.6}
.badge.on{opacity:1;background:linear-gradient(180deg,#FFFFFF,#FFE8E8);box-shadow:var(--shadow)}
.bm{font-size:1.8rem;line-height:1;color:var(--muted)} .badge.on .bm{color:#E31414}
.badge b{font-size:.92rem} .badge small{font-size:.75rem;color:var(--muted)}
.morelist{display:flex;flex-direction:column;gap:10px}
.lb{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px}
.lb li{display:grid;grid-template-columns:36px 1fr auto;gap:12px;align-items:center;background:var(--surface);border-radius:14px;padding:12px 14px;box-shadow:var(--shadow)}
.lb li.me{background:linear-gradient(180deg,#FFFFFF,#FFE8E8)}
.rk{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;font-weight:700;background:var(--sunk)}
.lb li:nth-child(-n+3) .rk{background:linear-gradient(180deg,#FF7A7A,#E31414);color:#FFFFFF}
.nm{font-weight:700;min-width:0;overflow-wrap:anywhere} .vl{text-align:right;font-weight:700;color:#E31414} .vl small{display:block;font-weight:400;color:var(--muted);font-size:.78rem}
.roster{min-width:640px;font-size:.88rem} .roster th{position:sticky;top:0}
.roster tr.warn td:first-child{border-left:4px solid #E31414}
.roster small{color:var(--muted)}
.privacy{display:flex;flex-direction:column;gap:10px} .privacy h3{color:var(--primary);margin-top:6px}
.sel{user-select:all}
.flink{border:0;background:none;padding:0;color:#FFFFFF;text-decoration:underline;font:inherit}

/* white-fade surfaces follow the theme */
:root{--fade-a:#FFFFFF;--fade-b:#FFEDED;--fade-edge:#F7D0D0}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){--fade-a:#2A1C20;--fade-b:#3A1F27;--fade-edge:#1A1012}}
:root[data-theme="dark"]{--fade-a:#2A1C20;--fade-b:#3A1F27;--fade-edge:#1A1012}
.mis.done,.badge.on,.lb li.me,.cloudcta{background:linear-gradient(180deg,var(--fade-a),var(--fade-b))}
.lockbox,.auth-card{background:linear-gradient(180deg,var(--fade-a),var(--fade-b));box-shadow:0 3px 0 var(--fade-edge),0 10px 22px rgba(150,20,35,.10)}
.ph-tasks button{background:linear-gradient(180deg,#FFFFFF,#FFEDED)}

.flink{justify-self:start;text-align:left}
.clist li>a,.clist li>span,.clist li>button{justify-self:start}

.socials{display:flex;justify-content:center;gap:14px;margin-top:22px}
.soc{width:52px;height:52px;border-radius:50%;display:grid;place-items:center;border:1.5px solid rgba(255,255,255,.55);background:rgba(255,255,255,.14);padding:0;cursor:pointer;transition:background .15s ease,transform .15s ease}
.soc:hover{background:rgba(255,255,255,.28);transform:translateY(-2px)}
.soc svg{width:24px;height:24px;stroke:#FFFFFF;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.soc-note{text-align:center;color:rgba(255,255,255,.9);font-size:.85rem;margin-top:10px;user-select:all}
@media (prefers-reduced-motion:reduce){.soc{transition:none}.soc:hover{transform:none}}

.subjsw{display:flex;gap:4px;background:var(--sunk);border-radius:20px;padding:5px;overflow-x:auto;scrollbar-width:none;scroll-snap-type:x proximity}.subjsw::-webkit-scrollbar{display:none}.subjsw>button{flex:1 0 auto;scroll-snap-align:start;padding-left:14px!important;padding-right:14px!important}
.subjsw button{border:0;background:none;border-radius:16px;padding:10px 6px;font-weight:700;font-size:.95rem;color:var(--muted);display:flex;flex-direction:column;align-items:center;gap:1px;line-height:1.25;min-width:0}
.subjsw button small{font-weight:400;font-size:.75rem;opacity:.85}
.subjsw button[aria-selected="true"]{background:linear-gradient(180deg,#FF7A7A,#E31414);color:#FFFFFF;box-shadow:0 3px 10px rgba(227,20,20,.28)}
.eyebrow.sara{color:var(--primary);display:block;margin-bottom:2px}

.subfilter{display:flex;flex-direction:column;gap:10px}
.subtog{align-self:flex-start;display:inline-flex;align-items:center;gap:8px;border:1.5px solid var(--line);background:var(--surface);border-radius:999px;padding:8px 14px;font-size:.92rem;color:var(--muted)}
.subtog b{color:var(--ink)}
.subtog svg{width:18px;height:18px;stroke:var(--primary);fill:none;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round;transition:transform .2s ease}
.subtog[aria-expanded="true"] svg{transform:rotate(180deg)}
.subtog[aria-expanded="true"]{border-color:var(--primary)}
@media (prefers-reduced-motion:reduce){.subtog svg{transition:none}}

.subjsw small{display:inline-flex;align-items:center;gap:3px}
.chev{width:14px;height:14px;stroke:currentColor;fill:none;stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round;transition:transform .2s ease}
.subjsw button[aria-expanded="true"] .chev{transform:rotate(180deg)}
.subfilter:empty{display:none}
@media (prefers-reduced-motion:reduce){.chev{transition:none}}

.tgroup{display:flex;flex-direction:column;gap:12px}
.tgroup+.tgroup{margin-top:18px}
.tg-hd{display:flex;align-items:baseline;justify-content:space-between;gap:10px;padding-bottom:8px;border-bottom:2px solid var(--primary-soft)}
.tg-hd h2{font-size:1.3rem;color:var(--primary)}
.tg-hd span{font-size:.85rem;color:var(--muted);font-weight:700;white-space:nowrap}
.chip-lab{font-size:.85rem;font-weight:700;color:var(--primary);margin-top:4px}

/* flashcard swipe */
#fcwrap{position:relative;touch-action:pan-y;user-select:none;-webkit-user-select:none;--ok:0;--no:0;will-change:transform}
.sw-tag{position:absolute;top:16px;z-index:5;transform-style:flat;font-weight:700;font-size:1rem;padding:6px 14px;border-radius:999px;pointer-events:none;border:2.5px solid;background:var(--surface)}
.sw-ok{left:16px;color:var(--good);border-color:var(--good);opacity:var(--ok);transform:rotate(6deg)}
.sw-no{right:16px;color:#E31414;border-color:#E31414;opacity:var(--no);transform:rotate(-6deg)}
.sw-hint{display:flex;justify-content:space-between;gap:8px;font-size:.78rem;color:var(--muted);margin-top:-6px}
.sw-hint span:nth-child(2){opacity:.7}
@media (hover:hover) and (pointer:fine){.sw-hint span:nth-child(2)::after{content:" · ใช้ลูกศร ← →"}}
main{overflow-x:clip}
.sw-tag{box-shadow:var(--shadow)}

/* flashcard learn mode */
.cmode{display:grid;grid-template-columns:1fr 1fr;gap:4px;background:var(--sunk);border-radius:999px;padding:4px}
.cmode button{border:0;background:none;border-radius:999px;padding:9px 8px;font-weight:700;font-size:.9rem;color:var(--muted)}
.cmode button[aria-selected="true"]{background:var(--surface);color:#E31414;box-shadow:var(--shadow)}
.lprog{position:relative;height:44px;display:flex;align-items:center;margin-inline:2px}
.lp-track{position:relative;flex:1;height:14px;border-radius:99px;background:var(--sunk);margin-inline:22px;overflow:visible}
.lp-track i{position:absolute;left:0;top:0;bottom:0;border-radius:99px;background:linear-gradient(90deg,#FF7A7A,#E31414);transition:width .35s ease}
.lp-seg{position:absolute;top:0;bottom:0;width:6px;margin-left:-3px;background:var(--paper)}
.lp-now,.lp-end{position:absolute;top:0;width:44px;height:44px;border-radius:50%;display:grid;place-items:center;font-weight:700;font-variant-numeric:tabular-nums}
.lp-now{background:linear-gradient(180deg,#FF7A7A,#E31414);color:#FFFFFF;box-shadow:0 3px 10px rgba(227,20,20,.3);transition:left .35s ease;z-index:2}
.lp-end{right:0;background:var(--sunk);color:var(--ink);font-size:.9rem}
.lq-card{background:var(--surface);border-radius:20px;box-shadow:var(--shadow);padding:26px 22px;min-height:160px;display:flex;flex-direction:column;justify-content:center;gap:8px}
.lq-term{font-family:var(--f-display);font-weight:700;font-size:2rem;line-height:1.2;color:var(--primary)}
.lq-def{font-size:1.15rem;line-height:1.55}
.lq-lab{font-weight:700;color:var(--muted);font-size:.92rem}
.lq-opts{display:flex;flex-direction:column;gap:10px}
.lq-opt{text-align:left;border:2px solid var(--line);background:var(--surface);border-radius:16px;padding:14px 16px;font-size:1rem;line-height:1.45;display:flex;flex-direction:column;gap:2px;transition:border-color .15s ease,background .15s ease}
.lq-opt small{color:var(--muted);font-size:.8rem}
.lq-opt:hover:not([disabled]){border-color:#F24A4A}
.lq-opt.ok{border-color:var(--good);background:var(--good-soft)}
.lq-opt.no{border-color:#E31414;background:var(--bad-soft)}
.lq-opt[disabled]{cursor:default}
.lq-opt[disabled]:not(.ok):not(.no){opacity:.55}
.lq-fb{border-radius:14px;padding:12px 16px;font-size:.95rem}
.lq-fb.good{background:var(--good-soft);color:var(--good)} .lq-fb.bad{background:var(--bad-soft);color:var(--ink)}
.lq-sum,.lq-done{background:var(--surface);border-radius:20px;box-shadow:var(--shadow);padding:20px;display:flex;flex-direction:column;gap:12px}
.lq-done{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);color:#FFFFFF}
.lq-done .eyebrow{color:rgba(255,255,255,.9)} .lq-done h2{color:#FFFFFF;font-size:1.6rem}
.lq-done .btn.primary{background:#FFFFFF;color:#E31414;align-self:flex-start}
.lq-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px}
.lq-list li{display:flex;flex-direction:column;gap:2px;padding:10px 12px;border-radius:12px;border-left:4px solid var(--good);background:var(--paper)}
.lq-list li.no{border-left-color:#E31414}
.lq-list span{font-size:.85rem;color:var(--muted)}
@media (prefers-reduced-motion:reduce){.lp-track i,.lp-now,.lq-opt{transition:none}}
.lprog{scroll-margin-top:90px}

/* card hub */
.cm-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
@media (max-width:420px){.cm-grid{grid-template-columns:1fr}}
.cm-tile{display:grid;grid-template-columns:52px 1fr;gap:12px;align-items:center;text-align:left;border:0;border-radius:18px;padding:14px;background:var(--surface);box-shadow:var(--shadow);transition:transform .15s ease}
.cm-tile:hover:not([disabled]){transform:translateY(-2px)}
.cm-tile.dim{opacity:.55;cursor:default}
.cm-ic{width:52px;height:52px;border-radius:14px;background:var(--primary-soft);display:grid;place-items:center}
.cm-ic svg{width:36px;height:36px}
.cm-tx{display:flex;flex-direction:column;gap:2px;min-width:0}
.cm-tx b{font-size:1.02rem} .cm-tx small{color:var(--muted);font-size:.8rem;line-height:1.4}
.staronly{display:flex;gap:8px;align-items:center;font-size:.9rem;font-weight:700}
.staronly input{width:18px;height:18px;accent-color:#E31414}
.cprog{display:flex;flex-direction:column;gap:10px}
.cp-row{display:grid;grid-template-columns:64px 1fr 24px;gap:14px;align-items:center;border:2px solid transparent;border-radius:18px;padding:10px 14px;background:var(--surface);box-shadow:var(--shadow);text-align:left}
.cp-row.on{border-color:#F24A4A}
