.modebar{display:flex;align-items:center;justify-content:space-between;gap:10px;padding-block:2px 4px;border-bottom:1px solid var(--line)}
.modebar .back{white-space:nowrap}
.mb-t{font-weight:700;font-size:.95rem;text-align:right} .mb-t small{font-weight:400;color:var(--muted);font-size:.85rem}
.mg-top{display:flex;justify-content:space-between;align-items:center;gap:10px}
.mg-time{font-family:var(--f-display);font-weight:700;font-size:2rem;color:#E31414;font-variant-numeric:tabular-nums}
.mg-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.mg-tile{min-height:88px;border:2px solid var(--line);border-radius:16px;background:var(--surface);padding:10px;font-weight:700;font-size:.95rem;line-height:1.35;overflow-wrap:anywhere;transition:transform .15s ease,opacity .25s ease,border-color .15s ease}
