.mg-tile.gone{opacity:0;transform:scale(.85);pointer-events:none}
@keyframes shake{0%,100%{translate:0}25%{translate:-5px}75%{translate:5px}}
@media (prefers-reduced-motion:reduce){.cm-tile,.mg-tile{transition:none;animation:none}}

/* library */
