.lh-fan span small{font-size:.6rem;color:var(--primary);font-weight:700}
.lh-fan span b{font-size:.82rem;line-height:1.3}
.lib-hero .fab{position:absolute;left:18px;bottom:16px;width:44px;height:44px;z-index:2;background:#fff!important;color:#E31414!important;box-shadow:0 6px 14px -6px rgba(120,0,0,.5)}
.lib-hero .fab svg{stroke:#E31414}
.lib-h{display:flex;justify-content:space-between;align-items:baseline;gap:8px;margin:0 0 4px}
.lib-h span{font-size:1.1rem;color:var(--ink)}
.lib-h small{font-size:.76rem;color:var(--muted);font-weight:600}
.dk-grid{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:14px 12px}
.dk{width:100%;border:0;background:none;padding:0;text-align:left;font:inherit;color:var(--ink);display:flex;flex-direction:column;gap:8px;cursor:pointer}
.dk-stack{position:relative;display:block;height:118px;margin:8px 6px 0 0}
.dk-stack i{position:absolute;inset:0;border-radius:14px;background:#fff;box-shadow:0 2px 6px rgba(150,40,40,.12)}
.dk-stack i:nth-child(1){transform:translate(8px,-8px) rotate(3deg);background:#FDE4E3}
.dk-stack i:nth-child(2){transform:translate(4px,-4px) rotate(1.5deg);background:#FFF1F0}
.dk-top{position:absolute;inset:0;border-radius:14px;background:#fff;box-shadow:0 8px 18px -10px rgba(150,40,40,.45);border-top:6px solid #F24A4A;padding:10px 12px;display:flex;flex-direction:column;gap:3px;overflow:hidden}
.dk-top small{font-size:.64rem;font-weight:700;color:var(--primary)}
.dk-top b{font-size:.98rem;line-height:1.3}
.dk-top em{margin-top:auto;font-style:normal;font-size:.72rem;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dk-n{position:absolute;right:-4px;bottom:-8px;z-index:2;display:flex;align-items:baseline;gap:2px;font-family:var(--f-display);font-weight:700;font-size:1rem;color:#fff;background:linear-gradient(155deg,#FF7A7A,#E31414);border-radius:999px;padding:3px 10px;box-shadow:0 4px 10px -4px rgba(227,20,20,.6)}
.dk-n small{font-size:.66rem;font-weight:600}
.dk-ft{display:flex;flex-direction:column;gap:4px;padding:0 2px}
.dk-sub{font-size:.74rem;color:var(--muted);line-height:1.35;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.dk-pr{display:flex;align-items:center;gap:8px}
.dk-bar{flex:1;height:5px;border-radius:99px;background:var(--sunk);overflow:hidden}
.dk-bar i{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,#FF7A7A,#E31414)}
.dk-pr b{font-family:var(--f-display);font-size:.82rem;color:var(--primary)}
.dk-all{grid-column:1/-1}
li:has(>.dk-all){grid-column:1/-1}
.dk-all .dk-stack{height:92px}
.dk.soon{cursor:default}
.dk.soon .dk-top{background:repeating-linear-gradient(135deg,#FBF1EF 0 8px,#F6E6E3 8px 16px);border-top-color:#E8C9C5;color:var(--muted)}
.dk.soon .dk-top b{color:#A08A87}
.dk.soon .dk-top em{color:var(--primary);font-weight:700}
.dk.soon .dk-stack i{opacity:.6}

.fc{--ok:0;--no:0}
.fl{gap:14px}
.fl-prog{display:flex;flex-direction:column;gap:8px}
.fl-bar{height:8px;border-radius:99px;background:var(--sunk);overflow:hidden}
.fl-bar i{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,#FF7A7A,#E31414)}
.fl-ct{display:flex;gap:14px;font-size:.78rem;color:var(--muted)}
.fl-ct span{display:flex;align-items:baseline;gap:4px}
.fl-ct b{font-family:var(--f-display);font-size:1.05rem;color:var(--ink)}
.fl-ct .ok b{color:var(--primary)}
.fl-ct .ag b{color:#F59E6B}
.fl-done{display:flex;flex-direction:column;gap:2px;background:#fff;border-radius:16px;box-shadow:var(--shadow);border-left:5px solid #F24A4A;padding:12px 14px;font-size:.86rem}
.fl-done span{color:var(--muted)}
.fl-done .link{align-self:flex-start}
.fl-desk{position:relative;padding:14px 4px 0;background:radial-gradient(120% 80% at 50% 100%,#FDE4E3 0,transparent 70%)}
.fl-pile{position:absolute;inset:14px 4px 0;pointer-events:none}
.fl-pile i{position:absolute;inset:0;border-radius:22px;background:#fff;box-shadow:0 4px 10px -4px rgba(150,40,40,.25)}
.fl-pile i:nth-child(1){transform:translateY(-14px) scale(.9);opacity:.5}
.fl-pile i:nth-child(2){transform:translateY(-7px) scale(.95);opacity:.8}
.fl .fc{position:relative}
.fl .fc-in{min-height:300px}
.fl .face{border-radius:22px;padding:18px 20px;justify-content:space-between;box-shadow:0 14px 28px -16px rgba(150,40,40,.55);background:#fff repeating-linear-gradient(180deg,transparent 0 33px,#F6ECE9 33px 34px);background-position:0 58px;border-top:8px solid #F24A4A}
.fl-top{display:flex;justify-content:space-between;gap:8px;font-size:.76rem;font-weight:700;color:var(--primary)}
.fl-top span:last-child{color:var(--muted);font-family:var(--f-display)}
.fl-mid{display:flex;flex-direction:column;align-items:center;text-align:center;gap:6px}
.fl .face .term{font-size:2rem;line-height:1.3;color:var(--ink)}
.fl .face .en{font-size:.95rem;color:var(--primary);font-weight:600;font-family:var(--f-body)}
.fl-tap{text-align:center;font-size:.76rem;color:var(--muted)}
.fl .face.back{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);border-top-color:rgba(255,255,255,.4);color:#fff}
.fl .face.back .fl-top span{color:rgba(255,255,255,.92)}
.fl-def{margin:0;font-size:1.05rem;line-height:1.7;white-space:pre-line;text-shadow:0 1px 3px rgba(120,0,0,.25)}
.fl .face.back .fl-tap{color:rgba(255,255,255,.85)}
.fl-act{display:grid;grid-template-columns:1fr auto 1fr;gap:14px;align-items:end;justify-items:center;margin-top:4px}
.fl-b{border:0;background:none;display:flex;flex-direction:column;align-items:center;gap:6px;font:inherit;color:var(--muted);cursor:pointer}
.fl-b span{display:grid;place-items:center;border-radius:50%;font-weight:700;line-height:1}
.fl-b.no span{width:64px;height:64px;font-size:1.5rem;background:#fff;color:#F59E6B;box-shadow:0 8px 18px -10px rgba(150,40,40,.5);border:2px solid #FBD6C2}
.fl-b.ok span{width:64px;height:64px;font-size:1.7rem;color:#fff;background:linear-gradient(155deg,#FF7A7A,#E31414);box-shadow:0 10px 20px -8px rgba(227,20,20,.7)}
.fl-b.sh span{width:44px;height:44px;font-size:1.1rem;background:var(--sunk);color:var(--primary)}
.fl-b small{font-size:.76rem;font-weight:700}
.fl-b.ok small{color:var(--primary)}
.fl-hint{margin:0;text-align:center;font-size:.74rem;color:var(--muted)}
.fl .sw-tag{top:30px}
.fl-top{width:100%;align-self:stretch}.fl .face{align-items:stretch}

.enr{gap:18px}
.enr .en-st{font-size:.74rem;font-weight:700;border-radius:999px;padding:3px 10px;background:var(--primary-soft);color:var(--primary);white-space:nowrap}
.en-st{font-size:.74rem;font-weight:700;border-radius:999px;padding:3px 10px;background:var(--primary-soft);color:var(--primary);white-space:nowrap}
.en-app{background:var(--surface);border-radius:16px;box-shadow:var(--shadow);padding:12px 14px;display:flex;flex-direction:column;gap:3px}
.en-ah{display:flex;justify-content:space-between;align-items:center;gap:8px}
.en-app small{font-size:.8rem;color:var(--muted)}
.en-pills{display:flex;flex-wrap:wrap;gap:6px}.en-app .en-pills{margin-top:6px}
.en-btns{display:grid;grid-template-columns:1fr 1fr;gap:8px;align-self:stretch}
.en-btns a.btn{text-decoration:none}
/* pass */
.ep{position:relative;margin-top:14px;border-radius:26px;padding:34px 20px 16px;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);box-shadow:0 18px 34px -18px rgba(227,20,20,.75);overflow:hidden;display:flex;flex-direction:column;gap:8px;isolation:isolate}
.ep::before{content:"";position:absolute;inset:0;z-index:-1;background:radial-gradient(120% 60% at 100% 0%,rgba(255,255,255,.28),transparent 55%),radial-gradient(80% 50% at 0% 100%,rgba(255,200,200,.25),transparent 60%),repeating-linear-gradient(115deg,rgba(255,255,255,.05) 0 2px,transparent 2px 12px)}
.ep-hole{position:absolute;top:12px;left:50%;width:54px;height:12px;margin-left:-27px;border-radius:999px;background:var(--bg,#FBF3F2);box-shadow:inset 0 2px 3px rgba(120,0,0,.35)}
.ep-strap{position:absolute;top:-6px;left:50%;width:30px;height:24px;margin-left:-15px;border-radius:0 0 6px 6px;background:rgba(255,255,255,.25);display:none}
.ep-top{display:flex;justify-content:space-between;align-items:center;font-size:.72rem;letter-spacing:.14em;font-weight:700;border-bottom:1px solid rgba(255,255,255,.35);padding-bottom:8px;text-shadow:0 1px 3px rgba(120,0,0,.3)}
.ep-top span{opacity:.9}
.ep h1{margin:4px 0 0;color:#fff;font-size:1.25rem;font-weight:700;line-height:1.2;display:flex;flex-direction:column;text-shadow:0 2px 6px rgba(120,0,0,.3)}
.ep h1 em{font-style:normal;font-family:var(--f-display);font-size:2.35rem;line-height:1.05;letter-spacing:.01em}
.ep>p{margin:0;font-size:.86rem;line-height:1.6;color:rgba(255,255,255,.95);text-shadow:0 1px 3px rgba(120,0,0,.2)}
.ep-row{display:grid;grid-template-columns:repeat(3,1fr);gap:0;margin-top:4px;border-radius:14px;background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.3)}
.ep-row div{display:flex;flex-direction:column;align-items:center;padding:8px 4px}
.ep-row div+div{border-left:1px dashed rgba(255,255,255,.4)}
.ep-row small{font-size:.66rem;opacity:.85}
.ep-row b{font-family:var(--f-display);font-size:1.12rem;text-shadow:0 1px 4px rgba(120,0,0,.3)}
.ep-steps{list-style:none;margin:6px 0 0;padding:0;display:grid;grid-template-columns:repeat(3,1fr);position:relative}
.ep-steps::before{content:"";position:absolute;top:15px;left:16.6%;right:16.6%;border-top:2px dotted rgba(255,255,255,.55)}
.ep-steps li{position:relative;display:flex;flex-direction:column;align-items:center;gap:5px;font-size:.72rem;text-align:center;opacity:.8}
.ep-steps b{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:#F24A4A;border:1.5px solid rgba(255,255,255,.7);font-family:var(--f-display)}
.ep-steps b svg{width:16px;height:16px}
.ep-steps li.on{opacity:1;font-weight:700}.ep-steps li.on b{background:#fff;color:#E31414;box-shadow:0 0 0 4px rgba(255,255,255,.25)}
.ep-steps li.ok{opacity:1}.ep-steps li.ok b{background:#fff;color:#E31414}
.ep-bar{margin:8px -20px -16px;padding:10px 20px;background:rgba(255,255,255,.95);display:flex;align-items:center;gap:12px}
.ep-bar i{flex:1;height:26px;background:repeating-linear-gradient(90deg,#3a2a2a 0 2px,transparent 2px 4px,#3a2a2a 4px 5px,transparent 5px 8px,#3a2a2a 8px 11px,transparent 11px 13px);opacity:.75}
.ep-bar span{font-family:var(--f-display);font-weight:700;color:#E31414;font-size:.82rem;letter-spacing:.08em}
/* brochure */
.bro{background:var(--surface);border-radius:24px;box-shadow:var(--shadow);overflow:hidden;display:flex;flex-direction:column}
.bro-hd{padding:18px 18px 14px;display:flex;flex-direction:column;gap:2px}
.bro-eb{font-size:.74rem;font-weight:700;color:#E31414;letter-spacing:.06em}
.bro-hd h2{margin:0;font-family:var(--f-display);font-size:1.9rem;line-height:1.1;display:flex;flex-direction:column;gap:4px}
.bro-hd h2 small{font-family:var(--f-body);font-size:.76rem;font-weight:600;color:var(--muted);line-height:1.4}
.bro-tags{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:0 18px 16px}
.tag{position:relative;border-radius:8px 18px 18px 8px;padding:12px 12px 12px 26px;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);box-shadow:0 10px 20px -14px rgba(227,20,20,.85);display:flex;flex-direction:column;gap:2px}
.tag.alt{background:#fff;color:var(--ink);border:1.5px solid #F2C4BF;box-shadow:none}
.tag-hole{position:absolute;left:9px;top:50%;width:9px;height:9px;margin-top:-4.5px;border-radius:50%;background:var(--surface);box-shadow:inset 0 1px 2px rgba(120,0,0,.35)}
.tag.alt .tag-hole{background:#F7D3CF;box-shadow:none}
.tag small{font-size:.72rem;font-weight:600;opacity:.95}
.tag b{font-family:var(--f-display);font-size:1.7rem;line-height:1;text-shadow:0 1px 4px rgba(120,0,0,.25);display:flex;align-items:baseline;gap:4px}
.tag.alt b{color:#E31414;text-shadow:none}
.tag b i{font-style:normal;font-family:var(--f-body);font-size:.74rem;font-weight:600}
.bro-spec{margin:0;padding:4px 18px 14px;display:flex;flex-direction:column;border-top:1px solid var(--line)}
.bro-spec div{display:flex;align-items:baseline;gap:8px;padding:9px 0;border-bottom:1px dotted #EBCFCB}
.bro-spec div:last-child{border-bottom:0}
.bro-spec dt{font-size:.8rem;color:var(--muted);white-space:nowrap;font-family:var(--f-body)}
.bro-spec dd{margin:0 0 0 auto;text-align:right;font-size:.88rem;font-weight:700;font-family:var(--f-body);line-height:1.35}
.bro-blk{padding:6px 18px 16px;display:flex;flex-direction:column;gap:10px}
.bro-blk h3{margin:0;font-size:1rem}
.bro-pts{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:9px}
.bro-pts li{display:grid;grid-template-columns:30px 1fr;gap:8px;align-items:start;font-size:.85rem;line-height:1.55}
.bro-pts i{font-style:normal;font-family:var(--f-display);font-weight:700;color:#E31414;font-size:1.05rem;line-height:1.4;border-right:2px solid #F7D3CF}
.bro-vip{margin:0 18px 16px;border-radius:18px;padding:14px;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);display:grid;grid-template-columns:auto 1fr;gap:12px;align-items:center;box-shadow:0 12px 24px -16px rgba(227,20,20,.85)}
.bro-vt{font-family:var(--f-display);font-weight:700;font-size:.92rem;line-height:1.05;letter-spacing:.06em;text-align:center;padding-right:12px;border-right:1px dashed rgba(255,255,255,.55);text-shadow:0 1px 4px rgba(120,0,0,.3)}
.bro-vip p{margin:0;font-size:.84rem;line-height:1.55;text-shadow:0 1px 3px rgba(120,0,0,.2)}
.cpn-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.cpn{position:relative;display:grid;grid-template-columns:26px 1fr;border-radius:12px;background:#FFF6F5;border:1px solid #F7D3CF;overflow:hidden;min-height:58px}
.cpn-s{writing-mode:vertical-rl;transform:rotate(180deg);display:grid;place-items:center;font-family:var(--f-display);font-weight:700;font-size:.68rem;letter-spacing:.14em;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);text-shadow:0 1px 2px rgba(120,0,0,.3)}
.cpn>div{padding:8px 10px;display:flex;flex-direction:column;gap:1px;border-left:2px dashed #F2C4BF;justify-content:center}
.cpn b{font-size:.78rem;line-height:1.3}.cpn small{font-size:.72rem;color:var(--muted)}
.bro-toc{border-top:1px solid var(--line);margin:0}
.bro-toc summary{cursor:pointer;padding:14px 18px;list-style:none;display:flex;align-items:center;gap:8px;font-weight:700}
.bro-toc summary::-webkit-details-marker{display:none}
.bro-toc summary b{font-family:var(--f-display);color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);border-radius:999px;padding:1px 10px;font-size:.78rem;text-shadow:0 1px 2px rgba(120,0,0,.3)}
.bro-toc summary::after{content:"";margin-left:auto;width:9px;height:9px;border-right:2px solid #E31414;border-bottom:2px solid #E31414;transform:rotate(45deg);transition:transform .2s}
.bro-toc[open] summary::after{transform:rotate(-135deg)}
.bro-toc ol{list-style:none;margin:0;padding:0 18px 16px;position:relative}
.bro-toc ol::before{content:"";position:absolute;left:31px;top:8px;bottom:24px;border-left:2px dotted #F2C4BF}
.bro-toc li{position:relative;display:grid;grid-template-columns:28px 1fr;gap:10px;padding:6px 0}
.bro-toc li>i{font-style:normal;width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:#fff;border:2px solid #F24A4A;color:#E31414;font-family:var(--f-display);font-weight:700;font-size:.85rem;z-index:1}
.bro-toc li b{font-size:.86rem;display:block;line-height:1.35}.bro-toc li small{font-size:.76rem;color:var(--muted);line-height:1.45}
/* paper form */
.ef{position:relative;background:#fff;border-radius:6px 6px 22px 22px;box-shadow:0 1px 0 #F2D9D6,0 18px 34px -22px rgba(120,20,20,.35);padding:20px 16px 18px;display:flex;flex-direction:column;gap:16px;overflow:hidden;border-radius:22px;padding-top:26px}
.ef::before,.er::before{content:"";position:absolute;left:0;right:0;top:0;height:7px;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%)}
.ef-wm{position:absolute;top:40%;left:50%;transform:translate(-50%,-50%) rotate(-28deg);font-family:var(--f-display);font-weight:700;font-size:4.2rem;color:rgba(227,20,20,.035);pointer-events:none;white-space:nowrap;letter-spacing:.06em}
.ef-head{display:flex;justify-content:space-between;align-items:flex-start;gap:10px;padding-bottom:12px;border-bottom:3px double #E8C6C2}
.ef-brand{display:flex;flex-direction:column}
.ef-brand b{font-family:var(--f-display);font-size:1.1rem;color:#E31414;letter-spacing:.06em}
.ef-brand small{font-size:.72rem;color:var(--muted)}
.ef-code{border:1.5px solid #E31414;border-radius:8px;padding:4px 10px;text-align:center;display:flex;flex-direction:column;line-height:1.15}
.ef-code small{font-size:.62rem;color:var(--muted)}.ef-code b{font-family:var(--f-display);color:#E31414}
.ef-title{text-align:center;display:flex;flex-direction:column;gap:2px}
.ef-title h2{margin:0;font-size:1.6rem;letter-spacing:.04em}
.ef-title small{font-size:.74rem;font-weight:700;color:var(--muted);letter-spacing:.03em}
.ef-title p{margin:6px 0 0;font-size:.78rem;color:var(--muted)}
.ef i{color:#E31414;font-style:normal}
.ef-sec{position:relative;display:flex;flex-direction:column;gap:10px;padding-top:14px;border-top:1px solid #F1DEDB}
.ef-hd{display:flex;flex-direction:column;gap:2px;margin-bottom:2px}
.ef-n{align-self:flex-start;font-size:.7rem;font-weight:700;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);border-radius:6px;padding:2px 9px;letter-spacing:.04em;text-shadow:0 1px 2px rgba(120,0,0,.3);margin-bottom:4px}
.ef-hd h2{margin:0;font-size:1.08rem}.ef-hd small{font-size:.76rem;color:var(--muted)}
.ef-q{font-size:.86rem;font-weight:700;margin-top:4px}
.ef-qr{display:flex;justify-content:space-between;align-items:center;gap:8px}
.ef-all{font:inherit;font-size:.76rem;font-weight:700;color:#E31414;background:#FFF1EF;border:1px solid #F7D3CF;border-radius:999px;padding:4px 12px;cursor:pointer}
.ef-hint{font-size:.74rem;color:var(--muted);line-height:1.5;margin:0}
.ef-f input,.ef-f textarea{font:inherit;width:100%;min-width:0;border:0;border-bottom:1.5px dotted #D9AFAA;border-radius:0;background:transparent;padding:8px 2px;color:var(--ink);box-shadow:none}
.ef-f input:focus,.ef-f textarea:focus{outline:none;border-bottom:2px solid #E31414;box-shadow:none;background:linear-gradient(0deg,#FFF5F4,transparent)}
.ef-f label{font-size:.82rem}
.ef-f textarea{min-height:76px;height:76px;resize:vertical;background-image:repeating-linear-gradient(180deg,transparent 0 31px,#EBD3D0 31px 32px);line-height:32px;padding-top:0;border-bottom:0}
.ef-o{position:relative;display:grid;grid-template-columns:22px 1fr;gap:10px;align-items:start;cursor:pointer;padding:9px 2px}
.ef-o input{position:absolute;opacity:0;pointer-events:none}
.ef-box{width:20px;height:20px;margin-top:1px;border:1.8px solid #C9A3A0;border-radius:5px;background:#fff;display:grid;place-items:center;transition:all .15s}
.ef-o input[type=radio]~.ef-box{border-radius:50%}
