.gh-rk.rk2{background:#fff;color:#E31414;box-shadow:inset 0 0 0 1.5px #F7C3C8,0 3px 8px -5px rgba(227,20,20,.6)}.gh-rk.rk2 i{background:linear-gradient(160deg,#FF7A7A,#E31414)}.gh-rk.rk2:before{color:#8E5A60;opacity:1}
.gh-hero h1{position:relative;margin:6px 0 12px;font-size:1.65rem;line-height:1.35}
.gh-hero h1 em{font-style:normal;color:#FFE2DE}
