.gh-stats small{font-size:.56rem;opacity:.9}
.gh-cont{font:inherit;color:var(--ink);text-align:left;cursor:pointer;border:0;width:100%;display:grid;grid-template-columns:78px 1fr 40px;gap:12px;align-items:center;background:#fff;border-radius:22px;padding:12px;box-shadow:var(--shadow)}
