.gh-cv b{font-size:.82rem;line-height:1.25}
.gh-cv i{position:absolute;left:12px;right:8px;bottom:10px;height:2px;background:rgba(255,255,255,.5);box-shadow:0 -5px 0 rgba(255,255,255,.35)}
.gh-cx{display:flex;flex-direction:column;gap:3px;min-width:0}
