.gh-cx>b{font-size:.95rem;line-height:1.3}
.gh-cx>span{font-size:.72rem;color:var(--muted);line-height:1.4}
.gh-cb{display:grid!important;grid-template-columns:1fr auto;gap:8px;align-items:center;margin-top:2px}
.gh-cb .kn-pr{margin:0}
.gh-cb em{font-style:normal;font-size:.62rem;font-weight:700;color:#C81010}
.gh-play{width:40px;height:40px;border-radius:50%;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);display:flex;align-items:center;justify-content:center;box-shadow:0 8px 14px -8px rgba(227,20,20,.9)}
.gh-play svg{width:18px;height:18px;fill:#fff;margin-left:2px}
.gh-plan{background:#fff;border-radius:22px;box-shadow:var(--shadow);padding:12px;margin-bottom:12px}
.gh-ph{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:8px}
.gh-tm{display:flex;gap:4px;background:#FBF3F2;border-radius:14px;padding:4px}
.gh-tm button{font:inherit;border:0;background:transparent;border-radius:10px;padding:5px 10px;cursor:pointer;font-family:var(--f-display);font-weight:700;font-size:1rem;color:var(--muted);display:flex;align-items:baseline;gap:2px}
.gh-tm small{font-size:.58rem;font-family:inherit}
.gh-tm [aria-selected="true"]{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);color:#fff;text-shadow:0 1px 2px rgba(120,0,0,.3)}
.gh-pc{display:flex;flex-direction:column;align-items:flex-end}
.gh-pc b{font-family:var(--f-display);font-size:1.1rem;line-height:1}
.gh-pc small{font-size:.6rem;color:var(--muted)}
.gh-steps{list-style:none;margin:0;padding:0;display:flex;flex-direction:column}
.gh-steps li{position:relative}
.gh-steps li:not(:last-child)::after{content:"";position:absolute;left:21px;top:44px;bottom:-4px;border-left:2px dashed #F2CFCB}
.gh-steps button{font:inherit;color:var(--ink);text-align:left;cursor:pointer;border:0;background:transparent;width:100%;display:grid;grid-template-columns:42px 1fr auto;gap:10px;align-items:center;padding:6px 0}
.gh-si{width:42px;height:42px;border-radius:14px;background:#FFF1EF;color:#E31414;display:flex;align-items:center;justify-content:center}
