.gh-sm{display:flex;flex-direction:column;min-width:0}
.gh-sm b{font-size:.86rem;line-height:1.3}
.gh-sm small{font-size:.68rem;color:var(--muted)}
.gh-steps em{font-style:normal;font-size:.66rem;font-weight:700;color:#C81010;background:#FFF1EF;border-radius:999px;padding:2px 8px;white-space:nowrap}
.gh-day{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.gh-day>button{font:inherit;color:var(--ink);text-align:left;cursor:pointer;border:0;min-width:0;border-radius:20px;min-height:170px;position:relative}
.gh-word{perspective:800px;background:transparent;padding:0}
.gh-wf,.gh-wb{position:absolute;inset:0;border-radius:20px;padding:14px 12px;display:flex;flex-direction:column;gap:4px;backface-visibility:hidden;transition:transform .5s}
.gh-wf{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);color:#fff;text-shadow:0 1px 2px rgba(120,0,0,.3);justify-content:center;align-items:center;text-align:center}
.gh-wf small{font-size:.6rem;font-weight:700;opacity:.9}
.gh-wf b{font-size:1.05rem;line-height:1.3}
.gh-wf em{font-style:normal;font-size:.7rem;opacity:.9}
.gh-wf u{text-decoration:none;font-size:.56rem;opacity:.75;margin-top:6px}
.gh-wb{background:#fff;box-shadow:var(--shadow);transform:rotateY(180deg);overflow:hidden}
.gh-wb b{font-size:.84rem;color:#E31414}
.gh-wb small{font-size:.7rem;line-height:1.5;color:var(--ink);display:-webkit-box;-webkit-line-clamp:6;-webkit-box-orient:vertical;overflow:hidden}
.gh-word.flip .gh-wf{transform:rotateY(180deg)}.gh-word.flip .gh-wb{transform:rotateY(360deg)}
.gh-news{background:#FFFDFB!important;box-shadow:var(--shadow);padding:12px!important;display:flex;flex-direction:column;gap:5px;border-top:3px solid #2B1A1F!important;background-image:radial-gradient(rgba(120,60,50,.05) 1px,transparent 1px)!important;background-size:4px 4px!important}
.gh-news b{font-size:.95rem;line-height:1.3}
.gh-news small{font-size:.7rem;color:var(--muted);line-height:1.45;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.gh-news .kn-go{margin-top:auto}
.gh-sara{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.gh-sara>button{font:inherit;color:var(--ink);cursor:pointer;border:0;border-radius:18px;background:#fff;box-shadow:var(--shadow);padding:10px 6px;display:flex;flex-direction:column;align-items:center;text-align:center;gap:2px;min-width:0}
.gh-sara>button.weak{box-shadow:0 0 0 2px #F24A4A,var(--shadow)}
.gh-sn{font-size:.58rem;font-weight:700;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);border-radius:999px;padding:1px 8px}
.gh-rg{position:relative;width:52px;height:52px;margin:4px 0 2px}
.gh-rg svg{width:100%;height:100%}
.gh-rg b{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-family:var(--f-display);font-size:.85rem}
.gh-rg b i{font-style:normal;font-size:.55rem}
.gh-sara>button>b{font-size:.78rem;line-height:1.2}
.gh-sara>button>small{font-size:.58rem;color:var(--muted)}
.gh-sx{font:inherit;border:0;cursor:pointer;border-radius:18px;background:#2B1A1F;color:#fff;padding:10px;display:flex;flex-direction:column;justify-content:center;text-align:left;gap:2px}
.gh-sx b{font-size:.84rem}.gh-sx small{font-size:.6rem;opacity:.75}.gh-sx span{font-size:.7rem;font-weight:700;color:#FF9A9A;margin-top:4px}
.gh-lic{background:#fff;border-radius:22px;box-shadow:var(--shadow);padding:14px;border-left:5px solid #E31414}
.gh-lt{display:flex;flex-direction:column;gap:1px;margin-bottom:6px}
.gh-lt small{font-size:.64rem;font-weight:700;color:#E31414}
.gh-lt b{font-size:1rem}.gh-lt span{font-size:.7rem;color:var(--muted)}
.gh-chk{margin-top:10px;background:#fff;border-radius:22px;box-shadow:var(--shadow);padding:6px 12px}
.gh-chk button{font:inherit;color:var(--ink);text-align:left;cursor:pointer;border:0;background:transparent;width:100%;display:grid;grid-template-columns:24px 1fr auto;gap:10px;align-items:center;padding:9px 0;border-bottom:1px solid #F7E9E7}
.gh-chk button:last-child{border-bottom:0}
.gh-chk i{width:22px;height:22px;border-radius:7px;border:2px solid #F2CFCB;display:flex;align-items:center;justify-content:center;color:#fff}
.gh-chk i svg{width:14px;height:14px}
.gh-chk i.ok{background:#2E9E5B;border-color:#2E9E5B}.gh-chk i.mid{border-color:#F24A4A;background:#FFF1EF}
.gh-chk span{display:flex;flex-direction:column;min-width:0}
.gh-chk b{font-size:.84rem}.gh-chk small{font-size:.66rem;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.gh-chk em{font-style:normal;font-family:var(--f-display);font-weight:700;font-size:.85rem;color:#C81010}
.gh-mini{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:10px}
.gh-mini button,.gh-exp button{font:inherit;color:var(--ink);text-align:left;cursor:pointer;border:0;border-radius:16px;background:#fff;box-shadow:var(--shadow);padding:10px;display:flex;flex-direction:column;gap:1px}
.gh-mini b{font-size:.8rem}.gh-mini small{font-size:.62rem;color:var(--muted)}
.gh-exp{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.gh-exp button{background:var(--bg);box-shadow:none;border:1px solid rgba(0,0,0,.04);min-height:92px;position:relative;padding:12px}
.gh-exp b{font-size:.9rem;line-height:1.3}.gh-exp small{font-size:.66rem;color:var(--muted);line-height:1.35}
.gh-exp span{position:absolute;right:12px;bottom:8px;font-weight:700;color:#C81010}
.gh-shelf{display:flex;gap:6px;overflow-x:auto;padding:4px 2px 12px;scroll-snap-type:x mandatory;border-bottom:6px solid #D9B8A0;border-radius:0 0 6px 6px;background:linear-gradient(180deg,transparent 0 85%,#F3E3D6 85%)}
.gh-shelf button{font:inherit;flex:none;scroll-snap-align:start;width:64px;height:170px;border:0;cursor:pointer;border-radius:6px 6px 3px 3px;background:hsl(var(--hue) 75% 62%);color:#fff;text-shadow:0 1px 2px rgba(80,0,10,.35);display:flex;flex-direction:column;align-items:center;padding:8px 4px 6px;gap:4px;box-shadow:inset -4px 0 0 rgba(0,0,0,.08),inset 0 6px 0 rgba(255,255,255,.18)}
.gh-shelf button:nth-child(even){height:154px;align-self:flex-end;background:hsl(var(--hue) 70% 78%)}
.gh-shelf button.done{background:#2B1A1F}
.gh-shelf small{font-size:.52rem;font-weight:700;opacity:.9}
.gh-shelf b{flex:1;writing-mode:vertical-rl;font-size:.74rem;line-height:1.1;overflow:hidden}
.gh-sb{width:8px;height:30px;border-radius:4px;background:rgba(255,255,255,.3);display:flex;align-items:flex-end;overflow:hidden}
.gh-sb i{display:block;width:100%;background:#fff;border-radius:4px}
.gh-shelf em{font-style:normal;font-size:.6rem;font-weight:700}
.gh-bd{margin:0}


