.tt-sji svg{width:17px;height:17px}
.tt-sj b{font-size:.86rem;line-height:1.25}
.tt-sj p{margin:0;font-size:.68rem;line-height:1.45;color:var(--muted)}
.tt-fm{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}
