.pj-vol{display:flex;flex-direction:column;border-left:1.5px solid #F2D4D0;padding-left:10px}
.pj-vol small{font-size:.5rem;letter-spacing:.2em;font-weight:700;color:var(--muted)}
.pj-vol b{font-size:.74rem;color:#C81010}
.pj-t{margin:0;font-size:.9rem;line-height:1.55;font-weight:700;color:var(--ink)}
.pj-ft{display:flex;justify-content:space-between;align-items:flex-end;gap:8px;margin-top:10px;padding-top:8px;border-top:1px dashed #F2D4D0}
.pj-tags{display:flex;flex-wrap:wrap;gap:4px}
.pj-tags i{font-style:normal;font-size:.6rem;font-weight:700;color:#C81010;background:#FFF1EF;border-radius:6px;padding:1px 7px}
.pj-c.alt .pj-tags i{background:#F1ECEC;color:#2B1A1F}
.pj-by{font-size:.6rem;color:var(--muted);white-space:nowrap}
.pj-lines{position:absolute;right:14px;bottom:44px;display:flex;flex-direction:column;gap:3px;opacity:.5}
.pj-lines i{display:block;width:30px;height:2px;border-radius:2px;background:#F2D4D0}
.pj-lines i:nth-child(2){width:22px}.pj-lines i:nth-child(3){width:26px}

.ed{display:flex;flex-direction:column}
.ed-r{display:grid;grid-template-columns:30px 1fr;gap:10px}
.ed-rail{position:relative;display:flex;justify-content:center}
.ed-rail::before{content:"";position:absolute;top:0;bottom:0;left:50%;margin-left:-1px;border-left:2px dashed #F2CFCB}
.ed-r:first-child .ed-rail::before{top:24px}
.ed-r:last-child .ed-rail::before{bottom:calc(100% - 24px)}
.ed-rail i{position:relative;z-index:1;margin-top:12px;width:24px;height:24px;border-radius:50%;background:#fff;border:2px solid #F7A9A6;font-style:normal;font-family:var(--f-display);font-weight:700;font-size:.72rem;color:#C81010;display:flex;align-items:center;justify-content:center;box-sizing:border-box}
.ed-r.now .ed-rail i{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);border-color:#fff;color:#fff;box-shadow:0 0 0 3px #FFE1DE}
.ed-c{display:grid;grid-template-columns:42px 1fr;gap:12px;align-items:start;margin-bottom:10px;border-radius:18px;padding:12px;background:#FFFDFB;border:1px solid #F4E2DF}
.ed-r:last-child .ed-c{margin-bottom:0}
.ed-ic{width:42px;height:42px;border-radius:13px;background:#FFF1EF;color:#E31414;display:flex;align-items:center;justify-content:center}
.ed-ic svg{width:21px;height:21px}
.ed-tx{display:flex;flex-direction:column;gap:2px;min-width:0}
.ed-lv{display:inline-flex;align-items:center;gap:5px;font-size:.62rem;font-weight:700;color:#C81010;letter-spacing:.02em}
.ed-tx b{font-size:.9rem;line-height:1.35}
.ed-p{display:flex;align-items:center;gap:4px;font-size:.72rem;color:var(--muted)}
.ed-p svg{width:13px;height:13px;flex:none;color:#E8918C}
.ed-n{align-self:flex-start;margin-top:5px;font-size:.64rem;font-weight:700;border-radius:999px;padding:2px 9px;background:rgba(255,255,255,.22)}
.ed-r.now .ed-c{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);border-color:transparent;color:#fff;text-shadow:0 1px 2px rgba(120,0,0,.3);box-shadow:0 14px 24px -16px rgba(227,20,20,.9)}
.ed-r.now .ed-ic{background:rgba(255,255,255,.22);color:#fff}
.ed-r.now .ed-lv,.ed-r.now .ed-p,.ed-r.now .ed-p svg{color:#fff}
.ed-r.now .ed-p{opacity:.92}
.ed-lv em{width:7px;height:7px;border-radius:50%;background:#fff;box-shadow:0 0 0 0 rgba(255,255,255,.7);animation:edp 1.8s infinite}
@keyframes edp{0%{box-shadow:0 0 0 0 rgba(255,255,255,.7)}70%{box-shadow:0 0 0 7px rgba(255,255,255,0)}100%{box-shadow:0 0 0 0 rgba(255,255,255,0)}}
@media (prefers-reduced-motion:reduce){.ed-lv em{animation:none}}

.tt-id{position:relative;margin:-44px 14px 0;background:#fff;border-radius:24px;box-shadow:0 16px 30px -18px rgba(80,10,20,.6);padding:16px 14px 14px;display:flex;flex-direction:column;gap:12px;z-index:1;overflow:hidden}
