.tt-st div{display:flex;flex-direction:column;align-items:center;text-align:center;gap:1px;border-radius:16px;padding:8px 2px 7px;background:#FBF3F2}
.tt-st div span{width:26px;height:26px;border-radius:9px;background:#fff;color:#E31414;display:flex;align-items:center;justify-content:center;margin-bottom:3px}
