.ivd-go{border:0;border-radius:999px;background:#fff;color:#E31414;font:inherit;font-weight:800;font-size:.88rem;padding:11px 14px;cursor:pointer;box-shadow:0 5px 0 rgba(150,10,10,.22)}
.ivd .ivx-wave{height:22px;padding:0}
.ivd-card{background:#fff;border:1.5px solid #F6D6D6;border-radius:22px;padding:14px;box-shadow:0 12px 22px -18px rgba(227,20,20,.55);display:flex;flex-direction:column;gap:12px}
.ivd-h{display:flex;align-items:center;gap:10px;padding-bottom:10px;border-bottom:1.5px dashed #F6D2D2}.ivd-h b{flex:1;font-size:1rem}.ivd-h small{font-size:.64rem;font-weight:800;color:#E31414;background:#FFEDED;border-radius:999px;padding:3px 10px}
.ivd-ic{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(155deg,#FF7A7A,#E31414);color:#fff}.ivd-ic svg{width:17px;height:17px;stroke:#fff}
.ivd-rev{display:flex;justify-content:space-between;align-items:center;border:1.5px dashed #F4B5B5;border-radius:16px;background:repeating-linear-gradient(-45deg,#FFF8F8 0 8px,#FFF1F1 8px 16px);padding:16px;font:inherit;font-weight:800;color:#E31414;cursor:pointer}
.ivd-rev i{font-style:normal;font-size:.68rem;background:#fff;border-radius:999px;padding:3px 10px;border:1.5px solid #F4BDBD}
.ivd-tip{margin:0;padding-left:20px;display:flex;flex-direction:column;gap:6px;font-size:.88rem;line-height:1.55}.ivd-tip li::marker{color:#E31414;font-weight:800}
.ivd-av{margin:0;padding:10px 12px;border-radius:12px;background:#FFF4F4;font-size:.82rem;line-height:1.5}.ivd-av b{display:block;color:#E31414;font-size:.72rem}
.ivd-note{min-height:130px;border:0!important;border-radius:12px!important;padding:6px 12px 6px 34px!important;line-height:28px!important;background:linear-gradient(90deg,transparent 0 24px,#F7A8A8 24px 25.5px,transparent 25.5px),repeating-linear-gradient(180deg,#FFFDFB 0 27px,#F8E2E2 27px 28px)!important;background-attachment:local!important;box-shadow:inset 0 0 0 1.5px #F6D6D6!important}
.ivd-rub{display:flex;flex-direction:column;gap:8px}
.ivd-rub label{display:grid;grid-template-columns:auto 1fr;gap:10px;align-items:center;padding:10px 12px;border-radius:14px;border:1.5px solid #F6D6D6;background:#fff;cursor:pointer;font-size:.86rem;position:relative}
.ivd-rub input{position:absolute;opacity:0;pointer-events:none}
.ivd-rub i{font-style:normal;width:26px;height:26px;border-radius:50%;display:grid;place-items:center;border:2px solid #F4B5B5;color:#E31414;font-size:.72rem;font-weight:800}
.ivd-rub label:has(input:checked){background:linear-gradient(90deg,#FFF0F0,#fff);border-color:#F4BDBD}
.ivd-rub label:has(input:checked) i{background:linear-gradient(155deg,#FF7A7A,#E31414);border-color:transparent;color:#fff;font-size:0}
.ivd-rub label:has(input:checked) i::after{content:"✓";font-size:.8rem}
.ivd-nav{display:flex;justify-content:space-between;gap:10px}

/* ---- interview script timeline ---- */
.ivd-scr{display:flex;flex-direction:column;gap:12px}
.ivd-bar{display:flex;gap:3px;height:26px;border-radius:999px;overflow:hidden;background:#FFF1F1}
.ivd-bar i{display:grid;place-items:center;font-style:normal;color:#fff;background:linear-gradient(155deg,#FF8A8A,#F24A4A)}
.ivd-bar i:nth-child(2){background:linear-gradient(155deg,#F24A4A,#E31414)}.ivd-bar i:nth-child(3){background:linear-gradient(155deg,#E31414,#C81010)}
.ivd-bar b{font-size:.62rem;letter-spacing:.06em}
.ivd-tl{list-style:none;margin:0;padding:0;display:flex;flex-direction:column}
.ivd-tl li{display:grid;grid-template-columns:46px 18px 1fr;gap:8px;align-items:start;position:relative;padding-bottom:12px}
.ivd-tl li:not(:last-child)::after{content:"";position:absolute;left:62px;top:16px;bottom:0;border-left:2px dashed #F4BDBD}
.ivd-t{font-family:var(--f-display);font-weight:800;font-size:.8rem;color:#E31414;line-height:1.1;display:flex;flex-direction:column;text-align:right;font-variant-numeric:tabular-nums}.ivd-t small{font-size:.6rem;color:var(--muted);font-weight:700}
.ivd-dot{width:14px;height:14px;margin-top:2px;border-radius:50%;background:#fff;border:3px solid #F24A4A;position:relative;z-index:1;justify-self:center}
.ivd-tl p{margin:0;font-size:.9rem;line-height:1.5;background:#FFF8F8;border:1.5px solid #F8DCDC;border-radius:4px 14px 14px 14px;padding:8px 12px}
.ivd-av{display:flex!important;gap:10px;align-items:flex-start;background:repeating-linear-gradient(-45deg,#FFF6F6 0 8px,#FFEFEF 8px 16px)!important;border:1.5px dashed #F4B5B5;border-radius:14px!important}
.ivd-x{flex:none;width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(155deg,#FF7A7A,#E31414);color:#fff;font-size:.72rem;font-weight:800}
.ivd-hero.run .ivx-wave i{animation:ivwv .9s ease-in-out infinite alternate;transform-origin:center}
.ivd-hero.run .ivx-wave i:nth-child(3n){animation-delay:.2s}.ivd-hero.run .ivx-wave i:nth-child(3n+1){animation-delay:.45s}
@keyframes ivwv{from{transform:scaleY(.35)}to{transform:scaleY(1.15)}}

/* ---- interview hero v3 ---- */
.ivd-hd{gap:10px}
.ivd-sign{display:inline-flex;align-items:center;gap:6px;font-size:.66rem;font-weight:800;letter-spacing:.16em;padding:5px 10px;border-radius:6px;background:#fff;color:#E31414;box-shadow:0 0 0 3px rgba(255,255,255,.25),0 0 18px rgba(255,255,255,.55)}
.ivd-sign i{width:7px;height:7px;border-radius:50%;background:#E31414;animation:onair 1.4s infinite}
.ivd-prog{flex:1;display:flex;gap:3px}.ivd-prog i{flex:1;height:4px;border-radius:2px;background:rgba(255,255,255,.3)}.ivd-prog i.d{background:rgba(255,255,255,.75)}.ivd-prog i.c{background:#fff;box-shadow:0 0 6px #fff}
.ivd-of{font-family:var(--f-display);font-size:.95rem;font-weight:800}.ivd-of small{font-size:.65rem;opacity:.8}
.ivd-ask{display:grid;grid-template-columns:auto 1fr;gap:10px;align-items:start}
.ivd-who{display:flex;flex-direction:column;align-items:center;gap:3px}.ivd-who svg{width:42px;height:42px;padding:9px;border-radius:50%;background:rgba(255,255,255,.2);border:1.5px solid rgba(255,255,255,.45);color:#fff}.ivd-who small{font-size:.54rem;opacity:.9}
.ivd-bub{position:relative;background:#fff;color:var(--ink);border-radius:4px 18px 18px 18px;padding:10px 14px 12px;box-shadow:0 8px 16px -10px rgba(150,10,10,.55)}
.ivd-bub::before{content:"";position:absolute;left:-7px;top:10px;border:7px solid transparent;border-right-color:#fff;border-left:0}
.ivd-bub small{font-size:.6rem;font-weight:800;color:#E31414;letter-spacing:.04em}
.ivd-bub h1{margin:2px 0 0!important;color:var(--ink)!important;font-size:1.2rem!important;line-height:1.35!important}

/* ---- general explore tiles ---- */
.gh-exp.gx{display:grid!important;grid-template-columns:1fr 1fr;gap:12px}
.gx-t{position:relative;overflow:hidden;display:flex!important;flex-direction:column;align-items:flex-start;gap:3px;min-height:0!important;padding:14px!important;border-radius:22px!important;border:1.5px solid #F6D6D6!important;background:#fff!important;font:inherit;text-align:left;color:var(--ink);cursor:pointer;box-shadow:0 12px 22px -18px rgba(227,20,20,.6)!important}
.gx-t::before{content:"";position:absolute;right:-26px;top:-26px;width:96px;height:96px;border-radius:50%;background:radial-gradient(circle,#FFE3E3 0 60%,transparent 61%)}
.gx-t::after{content:"";position:absolute;right:-8px;top:-8px;width:60px;height:60px;border-radius:50%;border:1.5px dashed #F4BDBD}
.gx-tag{position:relative;z-index:1;font-size:.54rem;font-weight:800;letter-spacing:.14em;color:#E31414;margin-bottom:4px}
.gx-ic{position:absolute;z-index:1;right:10px;top:10px;width:44px;height:44px;border-radius:14px;display:grid;place-items:center;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);box-shadow:0 8px 14px -8px rgba(227,20,20,.7);transform:rotate(-6deg)}
.gx-ic svg{width:22px;height:22px}
.gx-t>b{position:relative;z-index:1;font-size:.98rem!important;line-height:1.3;margin-top:22px;padding-right:4px}
.gx-t>small{font-size:.7rem!important;color:var(--muted)}
.gx-ft{display:flex;justify-content:space-between;align-items:center;width:100%;margin-top:10px;padding-top:9px;border-top:1.5px dashed #F6D2D2}
.gx-n{font-size:.68rem;color:var(--muted);font-weight:700}.gx-n em{font-style:normal;font-family:var(--f-display);font-size:1.15rem;color:#E31414}
.gx-go{width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:#FFEDED;color:#E31414;font-size:1rem}
.gx0{background:linear-gradient(180deg,#FFF5F5,#fff 55%)!important}
.gx1 .gx-ic{transform:rotate(5deg)}.gx2 .gx-ic{transform:rotate(-3deg)}.gx3 .gx-ic{transform:rotate(7deg)}
.gx3{background:linear-gradient(180deg,#FFF5F5,#fff 55%)!important}
.gx .gx-t span{position:static;right:auto;bottom:auto;font-weight:inherit;color:inherit}
.gx .gx-t .gx-ic{position:absolute!important;right:10px!important;top:10px!important;color:#fff!important}
.gx .gx-tag{position:relative!important;color:#E31414!important;font-weight:800!important}
.gx .gx-ft{display:flex!important}.gx .gx-n{color:var(--muted)!important;font-weight:700!important}
.gx .gx-go{display:grid!important;color:#E31414!important}
.gx-t>b{max-width:calc(100% - 46px)}

/* ---- daily word + news ---- */
.gh-day{gap:14px!important}
.gh-word{overflow:visible!important}
.gh-word::before,.gh-word::after{content:"";position:absolute;inset:0;border-radius:20px;z-index:-1;background:#FFC9C9;transform:rotate(-4deg) translate(-4px,6px)}
.gh-word::after{background:#FFE3E3;transform:rotate(3deg) translate(5px,4px)}
.gd-tag{display:inline-block;font-size:.5rem;font-weight:800;letter-spacing:.14em;background:rgba(255,255,255,.22);border-radius:999px;padding:2px 8px;margin-bottom:8px}
.gh-news{border-top:0!important;border:1.5px solid #F6D6D6!important;padding:0 12px 12px!important;overflow:hidden;background-image:repeating-linear-gradient(180deg,transparent 0 17px,rgba(242,74,74,.06) 17px 18px)!important}
.gd-mast{display:flex;justify-content:space-between;align-items:baseline;margin:0 -12px 6px;padding:8px 12px 6px;border-bottom:3px double #F24A4A;background:linear-gradient(180deg,#FFF1F1,#fff)}
.gd-mast b{font-size:.62rem;letter-spacing:.12em;color:#E31414;font-weight:800}.gd-mast small{font-size:.56rem;color:var(--muted);font-weight:700}
.gh-news .kn-cat{align-self:flex-start}
.gh-news .kn-go{color:#E31414}
#fcwrap,#fcwrap *{touch-action:pan-y!important}

/* ---- real exam report ---- */
section.rr{border-radius:24px;padding:16px;color:#fff;background:radial-gradient(120% 80% at 100% 0,rgba(255,255,255,.22),transparent 55%),linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);box-shadow:0 16px 30px -18px rgba(227,20,20,.8);display:flex;flex-direction:column;gap:12px}
.rr-hd{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}.rr-hd small{display:block;font-size:.58rem;font-weight:800;letter-spacing:.1em;opacity:.9}.rr-hd b{font-size:1.05rem}
.rr-stamp{flex:none;transform:rotate(8deg);border:2px solid #fff;outline:1px solid #fff;outline-offset:2px;border-radius:8px;padding:3px 9px;font-size:.72rem;font-weight:800}
.rr-sc{display:grid;grid-template-columns:auto 1fr;gap:16px;align-items:center}
.rr-big{display:flex;align-items:baseline;gap:2px;line-height:1}.rr-big b{font-size:3.6rem;font-family:var(--f-display)}.rr-big small{font-size:1rem;opacity:.85}
.rr-meta{display:grid;grid-template-columns:1fr 1fr;gap:6px}.rr-meta span{background:rgba(255,255,255,.16);border:1.5px solid rgba(255,255,255,.3);border-radius:12px;padding:5px 8px;font-size:.64rem;display:flex;flex-direction:column}.rr-meta i{font-style:normal;font-size:1rem;font-weight:800;font-family:var(--f-display)}
.rr-cmp{display:flex;justify-content:space-between;gap:8px;font-size:.72rem;padding-top:9px;border-top:1.5px dashed rgba(255,255,255,.35)}.rr-cmp .up{font-weight:800}.rr-cmp .dn{opacity:.9}
.rr-card,.rr-tip{background:#fff;border:1.5px solid #F6D6D6;border-radius:22px;padding:14px;box-shadow:0 12px 22px -18px rgba(227,20,20,.55)}
.rr-h{display:flex;justify-content:space-between;align-items:baseline;gap:8px;margin-bottom:10px}.rr-h small{font-size:.62rem;color:var(--muted)}
.rr-mix{display:flex;gap:3px;height:46px;margin-bottom:12px}.rr-mix i{position:relative;border-radius:8px;background:#FBEAEA;overflow:hidden}.rr-mix u{position:absolute;left:0;right:0;bottom:0;background:var(--c,#F24A4A)}
.rr-mix .m0 u,.rr-dot.m0{background:#E31414}.rr-mix .m1 u,.rr-dot.m1{background:#F24A4A}.rr-mix .m2 u,.rr-dot.m2{background:#FF7A7A}.rr-mix .m3 u,.rr-dot.m3{background:#FFA3A3}.rr-mix .m4 u,.rr-dot.m4{background:#FFC6C6}
.rr-rows{list-style:none;margin:0;padding:0;display:flex;flex-direction:column}
.rr-rows li{display:grid;grid-template-columns:10px 1fr 64px auto;gap:10px;align-items:center;padding:9px 6px;border-radius:12px}.rr-rows li+li{border-top:1.5px dashed #F6D2D2}
.rr-rows li.weak{background:#FFF1F1;border-top-color:transparent}
.rr-dot{width:10px;height:10px;border-radius:50%}
.rr-nm{display:flex;flex-direction:column;min-width:0}.rr-nm b{font-size:.88rem}.rr-nm small{font-size:.62rem;color:var(--muted)}
.rr-bar{height:7px;border-radius:4px;background:#FBE3E3;overflow:hidden}.rr-bar i{display:block;height:100%;border-radius:4px;background:linear-gradient(90deg,#FF7A7A,#E31414)}
.rr-v{display:flex;flex-direction:column;align-items:flex-end;line-height:1.15}.rr-v b{font-size:.9rem;font-family:var(--f-display)}.rr-v small{font-size:.6rem;color:#E31414;font-weight:700}
.rr-tip{display:grid;grid-template-columns:auto 1fr;gap:12px;background:linear-gradient(180deg,#FFF3F3,#fff)}
.rr-ti{width:42px;height:42px;border-radius:14px;display:grid;place-items:center;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);color:#fff}.rr-ti svg{width:22px;height:22px;stroke:#fff}
.rr-tip small{font-size:.62rem;font-weight:800;color:#E31414;letter-spacing:.04em}.rr-tip b{display:block;font-size:1rem;margin:2px 0}.rr-tip p{margin:0 0 10px;font-size:.8rem;color:var(--muted);line-height:1.5}.rr-tip em{font-style:normal;font-weight:800;color:#E31414;font-size:1rem}
.rr-btn{display:flex;flex-wrap:wrap;gap:6px}.rr-btn button,.pl-bt button,.hwc-bt button,.hwc-it button{font:inherit;font-size:.76rem;font-weight:800;border:1.5px solid #F4BDBD;background:#fff;color:#E31414;border-radius:999px;padding:7px 12px;cursor:pointer}
.rr-btn .pri,.pl-bt .pri,.hwc-bt .pri{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);color:#fff;border-color:transparent;box-shadow:0 4px 0 rgba(150,10,10,.2)}
/* ---- study plan ---- */
.pl.plx{border-radius:24px;padding:16px;color:#fff;background:radial-gradient(120% 80% at 100% 0,rgba(255,255,255,.22),transparent 55%),linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);box-shadow:0 16px 30px -18px rgba(227,20,20,.8);display:flex;flex-direction:column;gap:12px}
.plx .pl-hd{display:flex;justify-content:space-between;align-items:center}.plx .pl-hd small{display:block;font-size:.58rem;font-weight:800;letter-spacing:.1em;opacity:.9}.plx .pl-hd b{font-size:1.25rem}
.pl-cd{width:62px;height:62px;border-radius:16px;background:#fff;color:#E31414;display:flex;flex-direction:column;align-items:center;justify-content:center;line-height:1;box-shadow:0 6px 12px -6px rgba(150,10,10,.55)}.pl-cd b{font-size:1.5rem;font-family:var(--f-display)}.pl-cd small{font-size:.6rem;color:var(--muted);font-weight:700}
.pl-st{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.pl-st div{border-radius:14px;background:rgba(255,255,255,.16);border:1.5px solid rgba(255,255,255,.3);padding:8px;text-align:center;display:flex;flex-direction:column}.pl-st b{font-size:1.25rem;line-height:1.1;font-family:var(--f-display)}.pl-st b i{font-style:normal;font-size:.75rem;opacity:.8}.pl-st small{font-size:.64rem;opacity:.92}
.pl-tl{display:flex;gap:3px}.pl-tl i{flex:1;height:7px;border-radius:4px;background:rgba(255,255,255,.28)}.pl-tl i.d{background:rgba(255,255,255,.7)}.pl-tl i.c{background:#fff;box-shadow:0 0 8px #fff}.pl-tl i.r{background-image:repeating-linear-gradient(-45deg,transparent 0 3px,rgba(255,255,255,.35) 3px 6px)}
.pl-now{margin-top:12px;background:#fff;border:1.5px solid #F4BDBD;border-radius:22px;padding:14px;box-shadow:0 12px 22px -16px rgba(227,20,20,.6)}
.pl-nh{display:flex;align-items:center;gap:12px;padding-bottom:10px;border-bottom:1.5px dashed #F6D2D2}.pl-nh b{display:block;font-size:1rem}.pl-nh small{font-size:.7rem;color:var(--muted)}
.pl-wk{width:52px;height:56px;border-radius:12px;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;line-height:1}.pl-wk small{font-size:.52rem;opacity:.9}.pl-wk b{font-size:1.4rem;font-family:var(--f-display)}
.pl-ts{list-style:none;margin:6px 0 0;padding:0}.pl-ts li{display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:center;padding:10px 0}.pl-ts li+li{border-top:1.5px dashed #F8E0E0}
.pl-ck{width:24px;height:24px;border-radius:50%;border:2px solid #F4B5B5;display:grid;place-items:center}.pl-ts li.ok .pl-ck{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);border-color:transparent}.pl-ck svg{width:13px;height:13px;stroke:#fff}
.pl-tn{display:flex;flex-direction:column;min-width:0}.pl-tn b{font-size:.9rem}.pl-tn small{font-size:.64rem;color:var(--muted)}.pl-ts li.ok .pl-tn b{color:var(--muted)}
.pl-bt{display:flex;gap:5px}.pl-bt.wide{margin-top:8px}.pl-rv{margin:10px 0 0;font-size:.84rem;color:var(--muted)}
.pl-list{margin-top:12px;background:#fff;border:1.5px solid #F6D6D6;border-radius:22px;padding:12px 14px}
.pl-lh{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:6px}.pl-lh .link{font-size:.72rem}
.pl-list ol{list-style:none;margin:0;padding:0;max-height:330px;overflow:auto}
.pl-list li{display:grid;grid-template-columns:28px 1fr auto;gap:10px;align-items:center;padding:8px 2px}.pl-list li+li{border-top:1.5px dashed #F8E0E0}
.pl-n{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font-size:.72rem;font-weight:800;color:#E31414;background:#FFF1F1}
.pl-list li.cur .pl-n{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);color:#fff}.pl-list li.past{opacity:.55}.pl-list li.rev .pl-n{border:1.5px dashed #F4B5B5;background:#fff}
.pl-list li small{font-size:.6rem;color:var(--muted)}.pl-list li b{display:block;font-size:.8rem;line-height:1.35}.pl-list li em{font-style:normal;font-size:.7rem;font-weight:800;color:#E31414}
/* ---- homework ---- */
.hw-hero{display:grid;grid-template-columns:1fr auto;gap:12px;align-items:center;border-radius:24px;padding:16px;color:#fff;background:radial-gradient(120% 80% at 100% 0,rgba(255,255,255,.22),transparent 55%),linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);box-shadow:0 16px 30px -18px rgba(227,20,20,.8)}
.hw-hero small{font-size:.58rem;font-weight:800;letter-spacing:.1em;opacity:.9}.hw-hero h1{margin:2px 0 4px;color:#fff;font-size:1.5rem}.hw-hero p{margin:0;font-size:.78rem;opacity:.92;line-height:1.5}
.hw-ic{width:60px;height:60px;border-radius:18px;display:grid;place-items:center;background:#fff;color:#E31414;transform:rotate(-6deg);box-shadow:0 8px 16px -8px rgba(150,10,10,.55)}.hw-ic svg{width:30px;height:30px}
.hw-in{display:grid;grid-template-columns:1fr auto;gap:8px;margin:14px 0}.hw-in input{min-width:0}
.hw-list{display:flex;flex-direction:column;gap:14px}
.hwc{position:relative;background:#fff;border:1.5px solid #F6D6D6;border-radius:8px 22px 22px 22px;padding:14px;box-shadow:0 12px 22px -18px rgba(227,20,20,.55);display:flex;flex-direction:column;gap:10px}
.hwc.all{background:linear-gradient(180deg,#FFF3F3,#fff 60%)}
.hwc-hd{display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:start}
.hwc-pin{width:14px;height:14px;margin-top:4px;border-radius:50%;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);box-shadow:0 2px 0 rgba(150,10,10,.3),inset -2px -2px 0 rgba(150,10,10,.25)}
.hwc-hd small{font-size:.62rem;color:var(--muted)}.hwc-hd b{display:block;font-size:1rem;line-height:1.3}
.hwc-due{display:flex;flex-direction:column;align-items:flex-end;font-size:.72rem;font-weight:800;color:#E31414;background:#FFEDED;border-radius:12px;padding:4px 9px;line-height:1.25}.hwc-due small{font-size:.56rem;color:var(--muted);font-weight:700}
.hwc-due.late{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);color:#fff}.hwc-due.late small{color:rgba(255,255,255,.85)}.hwc-due.today{background:#E31414;color:#fff}.hwc-due.today small{color:#fff}
.hwc-note{margin:0;font-size:.82rem;background:#FFF8F8;border-left:3px solid #F24A4A;border-radius:0 10px 10px 0;padding:8px 10px}
.hwc-pr{display:grid;grid-template-columns:1fr auto;gap:10px;align-items:center}.hwc-pr span{height:8px;border-radius:5px;background:#FBE3E3;overflow:hidden}.hwc-pr i{display:block;height:100%;background:linear-gradient(90deg,#FF7A7A,#E31414)}.hwc-pr b{font-family:var(--f-display);color:#E31414}
.hwc-it{list-style:none;margin:0;padding:0}.hwc-it li{display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:center;padding:8px 0;font-size:.84rem}.hwc-it li+li{border-top:1.5px dashed #F8E0E0}
.hw-ck{width:22px;height:22px;border-radius:6px;border:2px solid #F4B5B5;display:grid;place-items:center}.hwc-it li.ok .hw-ck{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);border-color:transparent}.hw-ck svg{width:12px;height:12px;stroke:#fff}.hwc-it li.ok>span:nth-child(2){color:var(--muted);text-decoration:line-through;text-decoration-color:#F4A3A3}
.hwc-bt{display:flex;flex-wrap:wrap;gap:6px}.hwc-bt .ghost{border-color:transparent;color:var(--muted);margin-left:auto}
.hwc-res,.hwc-link{display:flex;flex-direction:column;gap:6px;background:#FFF8F8;border:1.5px dashed #F4B5B5;border-radius:14px;padding:10px}.hwc-res small,.hwc-link small{font-size:.64rem;color:#E31414;font-weight:800}
.hwc-res textarea,.hwc-link input{font-family:ui-monospace,Menlo,monospace;font-size:.66rem;word-break:break-all;min-height:0}
.hw-empty{display:flex;flex-direction:column;gap:4px;text-align:center;padding:26px 16px;border:1.5px dashed #F4B5B5;border-radius:20px;background:repeating-linear-gradient(-45deg,#FFFAFA 0 8px,#FFF4F4 8px 16px)}.hw-empty span{font-size:.78rem;color:var(--muted)}
.hwt-f{margin-top:14px;background:#fff;border:1.5px solid #F6D6D6;border-radius:22px;padding:14px;display:flex;flex-direction:column;gap:10px}
.hwt-f label{display:flex;flex-direction:column;gap:4px;font-size:.74rem;font-weight:800;color:var(--muted)}.hwt-2{display:grid;grid-template-columns:1fr 1.4fr;gap:8px}
.hwt-pick>b{display:flex;justify-content:space-between;font-size:.86rem}.hwt-pick em{font-style:normal;font-size:.68rem;color:#E31414;background:#FFEDED;border-radius:999px;padding:2px 8px}
.hwt-g{border:1.5px solid #F6DADA;border-radius:14px;margin-top:8px;padding:2px 10px}.hwt-g summary{cursor:pointer;font-size:.84rem;font-weight:800;padding:8px 0}
.hwt-chips{display:flex;flex-wrap:wrap;gap:6px;padding:4px 0 10px}
.hwt-chip{font:inherit;font-size:.72rem;border:1.5px solid #F4BDBD;background:#fff;color:var(--ink);border-radius:999px;padding:5px 10px;cursor:pointer}.hwt-chip.on{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);border-color:transparent;color:#fff}
.hwt-sel{margin:0;padding:8px 10px 8px 28px;background:#FFF8F8;border-radius:12px;font-size:.78rem}
.hwt-h{margin:18px 0 8px}
.hwc.tch{margin-bottom:12px}
.hwt-subs{border-top:1.5px dashed #F6D2D2;padding-top:10px;display:flex;flex-direction:column;gap:8px}.hwt-subs>b{font-size:.84rem;display:flex;justify-content:space-between}.hwt-subs em{font-style:normal;font-size:.68rem;color:#E31414}
.hwt-subs table{width:100%;border-collapse:collapse;font-size:.74rem}.hwt-subs th{text-align:left;font-size:.62rem;color:var(--muted);padding:4px}.hwt-subs td{padding:6px 4px;border-top:1px solid #F8E0E0}.hwt-subs td small{display:block;font-size:.6rem;color:var(--muted)}
.hwt-add{display:grid;grid-template-columns:1fr auto;gap:6px}.hwt-add input{min-width:0;font-size:.74rem}
.td-hw{margin-top:10px}

#app-toast,#coin-pop{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%)!important;color:#fff!important;border:0!important;box-shadow:0 14px 28px -14px rgba(227,20,20,.55)!important;font-weight:700!important}
#coin-pop *{color:#fff!important}
#hw-code,#hwt-t,#hwt-d,#hwt-n,.hwt-add input,.hwc input[readonly],.hwc textarea,.hw textarea,.hwt textarea{appearance:none;-webkit-appearance:none;width:100%;box-sizing:border-box;border:1.5px solid #F6CFCF!important;background:#FFF8F8!important;border-radius:14px!important;padding:11px 14px!important;font:inherit!important;font-size:.92rem!important;color:#2B1A1F!important;outline:none;min-height:46px}
#hw-code:focus,#hwt-t:focus,#hwt-d:focus,#hwt-n:focus,.hwt-add input:focus{border-color:#F24A4A!important;background:#fff!important;box-shadow:0 0 0 3px rgba(242,74,74,.14)}
.hwc input[readonly],.hwc textarea{font-family:ui-monospace,Menlo,monospace!important;font-size:.78rem!important;color:#B4232A!important;letter-spacing:0}
#hw-code::placeholder,#hwt-n::placeholder,.hwt-add input::placeholder{color:#C9A3A6}

.hwc-link input,.hwc-res textarea{width:100%;box-sizing:border-box;border:1.5px solid #F6CFCF!important;background:#fff!important;border-radius:12px!important;padding:10px 12px!important;font-family:ui-monospace,Menlo,monospace!important;font-size:.76rem!important;color:#B4232A!important;outline:none;resize:none}
.hwc-res textarea{height:66px!important;line-height:1.45!important;word-break:break-all;overflow:hidden}

.pl2{position:relative;border-radius:26px;padding:22px 20px 18px;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);box-shadow:0 18px 36px -20px rgba(227,20,20,.6);overflow:hidden;margin-bottom:16px}
.pl2:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 88% -10%,rgba(255,255,255,.28),transparent 45%),repeating-linear-gradient(0deg,rgba(255,255,255,.06) 0 1px,transparent 1px 26px);pointer-events:none}
.pl2>*{position:relative}
.pl2-top{display:flex;gap:14px;align-items:stretch}
.pl2-tt{flex:1;min-width:0}.pl2-tt small{font-size:.66rem;letter-spacing:.14em;font-weight:800;opacity:.85}
.pl2-tt b{display:block;font-size:1.55rem;line-height:1.25;margin:4px 0 6px}.pl2-tt p{margin:0;font-size:.82rem;opacity:.92}
.pl2-tk{position:relative;flex:0 0 96px;background:#fff;color:#E31414;border-radius:16px;padding:10px 6px 8px;text-align:center;display:flex;flex-direction:column;align-items:center;justify-content:center;box-shadow:0 10px 20px -12px rgba(120,0,0,.5)}
.pl2-tk:before,.pl2-tk:after{content:"";position:absolute;left:-7px;width:14px;height:14px;border-radius:50%;background:#F24A4A;top:calc(70% - 7px)}
.pl2-tk:after{left:auto;right:-7px}
.pl2-tk small{font-size:.66rem;color:#B86A6E;font-weight:700}.pl2-tk b{font-size:2rem;line-height:1.05;font-weight:800}
.pl2-tk span{margin-top:6px;padding-top:6px;border-top:1.5px dashed #F6CFCF;width:100%;font-size:.66rem;font-weight:800;color:#E31414}
.pl2-pr{display:flex;align-items:center;gap:10px;margin:16px 0 4px}.pl2-pr span{flex:1;height:8px;border-radius:9px;background:rgba(255,255,255,.28);overflow:hidden}
.pl2-pr i{display:block;height:100%;min-width:8px;border-radius:9px;background:#fff}.pl2-pr b{font-size:.8rem}
.pl2-tr{display:flex;align-items:flex-start;gap:6px;margin-top:16px;padding:14px 12px 10px;border-radius:18px;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.25)}
.pl2-m{display:flex;flex-direction:column;gap:6px;min-width:0}.pl2-m small{font-size:.64rem;font-weight:700;opacity:.9;padding-left:1px}
.pl2-m+.pl2-m{border-left:1px dashed rgba(255,255,255,.4);padding-left:5px}
.pl2-ws{display:flex;gap:3px}.pl2-ws i{position:relative;flex:1;height:14px;border-radius:5px;background:rgba(255,255,255,.3)}
.pl2-ws i.d{background:rgba(255,255,255,.85)}.pl2-ws i.r{background:repeating-linear-gradient(135deg,rgba(255,255,255,.55) 0 3px,rgba(255,255,255,.18) 3px 6px)}
.pl2-ws i.c{background:#fff;box-shadow:0 0 0 2px rgba(255,255,255,.45)}
.pl2-ws i.c em{position:absolute;bottom:calc(100% + 6px);left:50%;transform:translateX(-12px);white-space:nowrap;font-style:normal;font-size:.6rem;font-weight:800;color:#E31414;background:#fff;border-radius:7px;padding:2px 6px}
.pl2-ws i.c em:after{content:"";position:absolute;left:8px;top:100%;border:4px solid transparent;border-top-color:#fff}
.pl2-tr:has(.c em){padding-top:30px}
.pl2-fl{flex:0 0 auto;display:flex;flex-direction:column;align-items:center;gap:4px;padding-left:6px;border-left:1px dashed rgba(255,255,255,.4)}
.pl2-fl svg{width:16px;height:16px;color:#fff}.pl2-fl small{font-size:.64rem;font-weight:800}
.pl2-wk{background:#fff;border:1.5px solid #F6CFCF;border-radius:24px;overflow:hidden;margin-bottom:16px;box-shadow:0 14px 28px -22px rgba(227,20,20,.5)}
.pl2-wh{display:flex;gap:14px;align-items:center;padding:16px 18px 12px}
.pl2-wn{flex:0 0 auto;width:62px;height:62px;border-radius:18px;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;box-shadow:0 8px 16px -10px rgba(227,20,20,.7)}
.pl2-wn small{font-size:.56rem;letter-spacing:.14em;font-weight:800;opacity:.9}.pl2-wn b{font-size:1.5rem;line-height:1}
.pl2-wt small{display:block;font-size:.76rem;color:#B86A6E;font-weight:700}.pl2-wt b{display:block;font-size:1.08rem;color:#2B1A1F;margin-top:2px}
.pl2-dy{display:grid;grid-template-columns:repeat(7,1fr);gap:6px;padding:0 18px 14px}
.pl2-dy span{display:flex;flex-direction:column;align-items:center;padding:6px 0;border-radius:12px;background:#FFF5F5;color:#7A4A4F}
.pl2-dy small{font-size:.62rem;font-weight:700;opacity:.8}.pl2-dy b{font-size:.9rem}
.pl2-dy span.p{opacity:.45}.pl2-dy span.t{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);color:#fff}
.pl2-pg{position:relative;padding:6px 18px 14px 34px;background:#FFFBFB;border-top:1.5px dashed #F6CFCF;background-image:repeating-linear-gradient(180deg,transparent 0 31px,#FBE3E3 31px 32px)}
.pl2-pg:before{content:"";position:absolute;left:22px;top:0;bottom:0;width:1.5px;background:#F9B4B4}
.pl2-pg ul{list-style:none;margin:0;padding:0}
.pl2-pg li{display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1.5px dashed #F6D9D9}
.pl2-pg li:last-child{border-bottom:0}
.pl2-ck{flex:0 0 26px;width:26px;height:26px;border-radius:9px;border:2px solid #F3B3B3;background:#fff;display:flex;align-items:center;justify-content:center;color:#fff}
.pl2-pg li.ok .pl2-ck{background:linear-gradient(155deg,#FF7A7A,#E31414);border-color:transparent}.pl2-ck svg{width:15px;height:15px}
.pl2-pg li.ok .pl2-tn b{text-decoration:line-through;text-decoration-color:#F24A4A;color:#9B7A7D}
.pl2-tn{flex:1;min-width:0}.pl2-tn b{display:block;font-size:1rem;color:#2B1A1F}
.pl2-sp{display:flex;align-items:center;gap:8px;margin-top:4px;font-size:.72rem;color:#9B7A7D}
.pl2-sp>span:first-child{padding:1px 8px;border-radius:99px;background:#FDECEC;font-weight:700;white-space:nowrap}.pl2-sp>span.on{background:#E31414;color:#fff}
.pl2-mt{flex:1;max-width:90px;height:5px;border-radius:9px;background:#FBE0E0;overflow:hidden}.pl2-mt i{display:block;height:100%;background:linear-gradient(90deg,#FF7A7A,#E31414)}
.pl2-sp em{font-style:normal;font-weight:800;color:#E31414}
.pl2-bt{display:flex;gap:6px;flex:0 0 auto}.pl2-bt button{border:1.5px solid #F3B3B3;background:#fff;color:#E31414;font:inherit;font-weight:800;font-size:.84rem;padding:8px 14px;border-radius:99px;cursor:pointer}
.pl2-bt button.pri{border-color:transparent;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);box-shadow:0 6px 12px -8px rgba(227,20,20,.8)}
.pl2-bt.wide{padding:4px 0 8px}.pl2-bt.wide button{flex:1}
.pl2-rv{margin:12px 0;font-size:.92rem;color:#5A3A3E}
.pl2-tip{margin:8px 0 0;font-size:.7rem;color:#B86A6E}
.pl2-all{background:#fff;border:1.5px solid #F6CFCF;border-radius:24px;padding:16px 16px 14px}
.pl2-ah{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:6px}.pl2-ah b{font-size:1.15rem;color:#2B1A1F}
.pl2-ah button{border:1.5px solid #F3B3B3;background:#FFF5F5;color:#E31414;font:inherit;font-weight:800;font-size:.76rem;padding:7px 12px;border-radius:99px;cursor:pointer}
.pl2-g{margin-top:12px}.pl2-gh{display:flex;align-items:baseline;gap:6px;margin:0 0 4px 2px}
.pl2-gh b{font-size:.86rem;color:#E31414}.pl2-gh small{font-size:.72rem;color:#C9A3A6;font-weight:700}
.pl2-g ol{list-style:none;margin:0;padding:0 0 0 2px;position:relative}
.pl2-g ol:before{content:"";position:absolute;left:17px;top:10px;bottom:10px;width:2px;background:#FBE0E0}
.pl2-g li{position:relative;display:flex;align-items:center;gap:12px;padding:8px 10px 8px 0;border-radius:16px}
.pl2-n{position:relative;z-index:1;flex:0 0 32px;width:32px;height:32px;border-radius:50%;background:#fff;border:2px solid #F6CFCF;color:#E31414;font-weight:800;font-size:.8rem;display:flex;align-items:center;justify-content:center}
.pl2-n svg{width:15px;height:15px}
.pl2-g li>div{flex:1;min-width:0}.pl2-g li small{display:block;font-size:.7rem;color:#B86A6E}.pl2-g li b{display:block;font-size:.92rem;color:#2B1A1F;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pl2-g li em{font-style:normal;font-weight:800;font-size:.78rem;color:#E31414;background:#FFF2F2;padding:3px 9px;border-radius:99px}
.pl2-g li.past{opacity:.55}
.pl2-g li.full .pl2-n{background:linear-gradient(155deg,#FF7A7A,#E31414);border-color:transparent;color:#fff}
.pl2-g li.cur{background:#FFF2F2;box-shadow:inset 0 0 0 1.5px #F6CFCF;padding-left:0}
.pl2-g li.cur .pl2-n{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);border-color:#fff;color:#fff;box-shadow:0 0 0 4px #FDE0E0}
.pl2-g li.rev .pl2-n{background:repeating-linear-gradient(135deg,#FFE3E3 0 4px,#fff 4px 8px)}
.pl2-g li.rev em{background:#E31414;color:#fff}
.pl2-end{display:flex;align-items:center;gap:12px;margin-top:12px;padding:12px;border-radius:18px;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);color:#fff}
.pl2-end span{width:34px;height:34px;border-radius:50%;background:#fff;color:#E31414;display:flex;align-items:center;justify-content:center}.pl2-end svg{width:17px;height:17px}
.pl2-end small{display:block;font-size:.72rem;opacity:.9}.pl2-end b{font-size:1rem}
@media(max-width:380px){.pl2-bt button{padding:7px 11px}.pl2-tk{flex-basis:84px}.pl2-tk b{font-size:1.7rem}}
.pl2-pg{background-image:none!important}

details.pl2-all>summary{list-style:none;cursor:pointer;display:flex!important;align-items:center;justify-content:space-between;gap:12px;margin:0!important}
details.pl2-all>summary::-webkit-details-marker{display:none}
.pl2-sx{display:flex;flex-direction:column;gap:2px}.pl2-sx small{font-size:.74rem;color:#A9767B;font-weight:600}
.pl2-tg{display:inline-flex;align-items:center;gap:4px;padding:8px 14px;border-radius:999px;background:#FFF1F1;border:1.5px solid #F6CFCF;color:#E31414;font-weight:700;font-size:.82rem;white-space:nowrap}
.pl2-tg svg{width:15px;height:15px;transition:transform .25s}
details.pl2-all[open] .pl2-tg svg{transform:rotate(180deg)}
details.pl2-all[open] .pl2-tg{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);color:#fff;border-color:transparent}
.pl2-ab{margin-top:14px}.pl2-rd{display:flex;justify-content:flex-end;margin-bottom:6px}
.pl2-rd button{padding:8px 14px;border-radius:999px;background:#fff;border:1.5px solid #F6CFCF;color:#E31414;font:inherit;font-weight:700;font-size:.8rem}

.pl3-mt{display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;padding:2px 2px 10px;margin:0 -2px}
.pl3-mt::-webkit-scrollbar{display:none}
.pl3-mt button{flex:1 0 auto;min-width:50px;display:flex;flex-direction:column;align-items:center;gap:0;padding:7px 8px 6px;border-radius:14px;border:1.5px solid #F6DADA;background:#fff;font:inherit;color:#8B5A5F;position:relative}
.pl3-mt button b{font-size:.84rem;line-height:1.2}.pl3-mt button small{font-size:.62rem;color:#C9A3A6;font-weight:700}
.pl3-mt button.now:after{content:"";position:absolute;top:5px;right:6px;width:6px;height:6px;border-radius:50%;background:#F24A4A}
.pl3-mt button.on{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);border-color:transparent;color:#fff;box-shadow:0 8px 16px -10px rgba(227,20,20,.7)}
.pl3-mt button.on small{color:rgba(255,255,255,.8)}.pl3-mt button.on.now:after{background:#fff}
.pl3-g{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.pl3-t{display:flex;align-items:center;gap:9px;text-align:left;padding:9px 10px;border-radius:16px;border:1.5px solid #F6DADA;background:#FFFBFB;font:inherit;color:#2B1A1F;min-width:0}
.pl3-n{flex:0 0 32px;height:32px;border-radius:11px;display:grid;place-items:center;font-weight:800;font-size:.8rem;color:#E31414;background:#FFEDED}
.pl3-n svg{width:16px;height:16px}
.pl3-tx{min-width:0;display:flex;flex-direction:column}
.pl3-tx small{font-size:.64rem;color:#B86A6E;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pl3-tx b{font-size:.82rem;line-height:1.3;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.pl3-t.past{opacity:.5}
.pl3-t.full .pl3-n{background:linear-gradient(155deg,#FF7A7A,#E31414);color:#fff}
.pl3-t.cur{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);border-color:transparent;color:#fff;box-shadow:0 10px 20px -12px rgba(227,20,20,.7)}
.pl3-t.cur .pl3-n{background:#fff;color:#E31414}.pl3-t.cur small{color:rgba(255,255,255,.85)}
.pl3-t.rev .pl3-n{background:repeating-linear-gradient(135deg,#FFDCDC 0 4px,#fff 4px 8px)}
.pl3-ft{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:12px;padding-top:12px;border-top:1.5px dashed #F6DADA}
.pl3-lg{display:flex;flex-wrap:wrap;gap:4px 10px;font-size:.68rem;color:#A9767B;font-weight:600}
.pl3-lg span{display:inline-flex;align-items:center;gap:4px}.pl3-lg i{width:10px;height:10px;border-radius:3px;display:inline-block}
.pl3-lg i.c{background:linear-gradient(155deg,#FF7A7A,#E31414)}.pl3-lg i.f{background:#FFEDED;box-shadow:inset 0 0 0 1.5px #F24A4A}.pl3-lg i.r{background:repeating-linear-gradient(135deg,#FFC9C9 0 3px,#fff 3px 6px)}
