.tsx-h{display:flex;align-items:baseline;justify-content:space-between;margin:4px 2px 0;font-size:.9rem}.tsx-h small{font-size:.62rem;font-weight:600;color:var(--muted)}
.tsx-stu{display:grid;grid-template-columns:1fr 1fr;gap:8px}
