.tsx-stu em{font-style:normal;font-size:.62rem;font-weight:700;color:#7A4A44}.tsx-stu em i{font-style:normal;color:#E31414}
.tsx-seg{display:flex;gap:3px;width:100%;margin:6px 0 2px}.tsx-seg i{flex:1;height:5px;border-radius:3px;background:#F4E2DF}
