.tsx-dl{display:flex;flex-direction:column;gap:8px;min-width:0}
.tsx-s{position:relative;display:grid;grid-template-columns:auto 1fr;gap:4px 12px;border-radius:18px;padding:12px 12px 12px 16px;background:#fff;box-shadow:0 0 0 1px #F4E2DF,0 10px 22px -18px rgba(227,20,20,.5);overflow:hidden}
.tsx-s::before{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;background:var(--c)}
.tsx-t{display:flex;flex-direction:column;align-items:center;justify-content:center;min-width:52px;border-radius:12px;padding:6px 4px;background:#FFF4F2}
