.tsx-t small::before{content:"ถึง ";}
.tsx-b{min-width:0}.tsx-who{display:flex;align-items:baseline;gap:6px}.tsx-who strong{font-size:.86rem}.tsx-who span{font-size:.6rem;color:var(--muted)}
.tsx-tp{margin:2px 0 0;font-size:.7rem;line-height:1.45;color:#5A3A3E}.tsx-tp span{display:inline-block;font-size:.58rem;font-weight:800;color:#fff;background:var(--c);border-radius:6px;padding:0 6px;margin-right:5px}
.tsx-s .tsx-seg{--c:inherit}
.tsx-st{grid-column:1/-1;justify-self:end;display:inline-flex;align-items:center;gap:5px;font-size:.6rem;font-weight:800;border-radius:999px;padding:3px 10px}
