.tsx-st.tsx-so{color:#5B7FB8;background:#EEF3FB}.tsx-st.tsx-sw{color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%)}.tsx-st.tsx-sd{color:#9A8380;background:#F6EFEE}
.tsx-s.tsx-p{opacity:.6}.tsx-s.tsx-cf{box-shadow:0 0 0 2px #E31414}
