.tsx-hc-f{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin-top:10px}.tsx-hc-f>span{font-size:.64rem;color:var(--muted);background:#FBF3F2;border-radius:999px;padding:3px 9px}.tsx-hc-f>span b{color:#E31414}.tsx-hc-f>span.tsx-fw{color:#E31414;background:#FFE7E4}
