.tz-dl{display:flex;flex-direction:column;gap:8px;min-width:0}
.tz-s{position:relative;display:grid;grid-template-columns:64px 1fr;border-radius:18px;background:#fff;box-shadow:0 0 0 1px #F4E2DF,0 12px 22px -18px rgba(227,20,20,.55);overflow:hidden}
.tz-stub{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:10px 0;background:var(--c);color:#fff}
.tz-stub::after{content:"";position:absolute;right:-1px;top:8px;bottom:8px;border-right:2px dashed rgba(255,255,255,.75)}
.tz-stub b{font-family:var(--f-display);font-size:1.1rem;line-height:1.1}.tz-stub small{font-size:.54rem;opacity:.92}
.tz-s::before,.tz-s::after{content:"";position:absolute;left:56px;width:14px;height:14px;border-radius:50%;background:var(--paper,#FBF3F2);z-index:1}
.tz-s::before{top:-7px}.tz-s::after{bottom:-7px}
.tz-body{padding:10px 12px;min-width:0}
.tz-who{display:flex;align-items:baseline;gap:6px}.tz-who strong{font-size:.88rem;color:#2B1A1F}.tz-who span{font-size:.6rem;color:var(--muted)}
.tz-topic{margin:3px 0 0;font-size:.72rem;line-height:1.45;color:#5A3A3E}.tz-topic span{display:inline-block;font-size:.56rem;font-weight:800;color:var(--c);background:#FFF4F2;box-shadow:inset 0 0 0 1px var(--c);border-radius:6px;padding:0 5px;margin-right:5px}
.tz-ft{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:7px}
.tz-dots{display:flex;gap:3px}.tz-dots i{width:7px;height:7px;border-radius:50%;background:#F4E2DF}.tz-dots i.d{background:var(--c)}.tz-dots i.n{background:#fff;box-shadow:inset 0 0 0 2px var(--c)}
.tz-st{font-size:.58rem;font-weight:800;border-radius:999px;padding:3px 9px;white-space:nowrap}
.tz-st.tz-so{color:#5B7FB8;background:#EEF3FB}.tz-st.tz-sw{color:#fff;background:#E31414}.tz-st.tz-sd{color:#9A8380;background:#F6EFEE}
.tz-s.tz-p{opacity:.62}.tz-s.tz-p .tz-stub{background:#CDB8B5}.tz-s.tz-cf{box-shadow:0 0 0 2px #E31414}
.tz-pa{border-radius:18px;background:#fff;padding:10px 12px;box-shadow:0 0 0 1px #F4E2DF}
.tz-pa summary{cursor:pointer;font-size:.78rem;font-weight:800;color:#7A4A44}.tz-pa[open] summary{margin-bottom:10px}
.tz-lock{display:flex;align-items:center;justify-content:center;gap:6px;font-size:.62rem;color:var(--muted);margin:6px 0 0}.tz-lock svg{width:14px;height:14px}
.tz-hc{margin:0 0 14px}
.tz-hc-l{list-style:none;margin:10px 0 0;padding:0}
.tz-hc-l li{display:grid;grid-template-columns:8px 1fr auto auto;gap:8px;align-items:center;padding:7px 2px;border-top:1px dashed #F2D4D0;font-size:.72rem}
.tz-hc-l li i{width:8px;height:8px;border-radius:50%;background:var(--c)}.tz-hc-l li b{color:var(--c)}.tz-hc-l li em{font-style:normal;font-weight:700}
.tz-hc-f{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin-top:10px}.tz-hc-f>span{font-size:.64rem;color:var(--muted);background:#FBF3F2;border-radius:999px;padding:3px 9px}.tz-hc-f>span b{color:#E31414}.tz-hc-f>span.tz-fw{color:#E31414;background:#FFE7E4}
.tz-btn{font:inherit;margin-left:auto;border:0;border-radius:999px;padding:8px 14px;font-size:.72rem;font-weight:800;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);cursor:pointer;box-shadow:0 8px 16px -10px rgba(227,20,20,.8)}

/* ---- lesson route (6 stations to the exam) ---- */
.rt{border-radius:24px;padding:18px 16px;margin:14px 0;background:radial-gradient(120% 70% at 100% 0%,#FFE3DE,rgba(255,227,222,0) 60%),#fff;box-shadow:0 18px 30px -22px rgba(190,30,25,.6)}
.rt-k,.rs-top small{display:inline-block;font-size:.6rem;font-weight:800;letter-spacing:.04em;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);border-radius:999px;padding:2px 10px}
.rt-h h3{margin:6px 0 2px;font-size:1.15rem}.rt-h p{margin:0;font-size:.72rem;color:var(--muted)}
.rt-pg{display:grid;grid-template-columns:auto 1fr;gap:2px 10px;align-items:center;margin:12px 0 4px}
.rt-pg span{grid-row:1/3;font-size:.8rem;color:var(--muted)}.rt-pg span b{font-family:var(--f-display);font-size:1.7rem;color:#E31414}
.rt-pg div{height:8px;border-radius:99px;background:#F6E3DF;overflow:hidden}.rt-pg div i{display:block;height:100%;border-radius:99px;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%)}
.rt-pg small{font-size:.6rem;color:var(--muted)}
.rt-l{list-style:none;margin:14px 0 0;padding:0;position:relative}
.rt-l::before{content:"";position:absolute;left:17px;top:18px;bottom:26px;width:4px;border-radius:4px;background:repeating-linear-gradient(180deg,#F2CFCB 0 8px,transparent 8px 14px)}
.rt-l>li{position:relative;display:grid;grid-template-columns:38px 1fr;gap:10px;padding:0 0 12px}
.rt-dot{position:relative;z-index:1;width:38px;height:38px;border-radius:50%;display:grid;place-items:center;font-weight:800;font-size:.86rem;color:#E31414;background:#fff;box-shadow:0 0 0 3px #F6D4CF}
.rt-dot svg{width:18px;height:18px}
.rt-dn .rt-dot{color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);box-shadow:0 0 0 3px #FFE3DE}
.rt-nw .rt-dot{color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);box-shadow:0 0 0 5px rgba(242,74,74,.22);animation:rtP 2s ease-in-out infinite}
@keyframes rtP{50%{box-shadow:0 0 0 9px rgba(242,74,74,.08)}}
@media (prefers-reduced-motion:reduce){.rt-nw .rt-dot{animation:none}}
.rt-l details{border-radius:18px;background:#fff;box-shadow:0 0 0 1px #F4E2DF;overflow:hidden}
.rt-nw details{box-shadow:0 0 0 2px #F24A4A,0 14px 26px -18px rgba(227,20,20,.7)}.rt-dn details{background:#FFF8F7}
.rt-l summary{list-style:none;display:flex;flex-direction:column;gap:2px;padding:10px 12px;cursor:pointer}.rt-l summary::-webkit-details-marker{display:none}
.rt-l summary small{font-size:.6rem;font-weight:800;color:#E31414}.rt-dn summary small{color:#B07A72}
.rt-l summary b{font-size:.88rem;color:#2B1A1F;line-height:1.35}
.rt-c{display:flex;flex-wrap:wrap;gap:4px;margin-top:3px}.rt-c i{font-style:normal;font-size:.56rem;font-weight:700;color:#7A4A44;background:#FBEDEA;border-radius:999px;padding:1px 8px}
.rt-p{list-style:none;margin:0;padding:0 12px 4px}
.rt-p li{display:grid;grid-template-columns:72px 1fr;gap:8px;padding:7px 0;border-top:1px dashed #F2D4D0}
.rt-p li span{font-size:.62rem;font-weight:800;color:#E31414}.rt-p li p{margin:0;font-size:.72rem;line-height:1.55;color:#2B1A1F}
.rt-hw{margin:0 12px 12px;padding:8px 10px;border-radius:12px;background:#FFF1EF;font-size:.68rem;line-height:1.55;color:#7A4A44}.rt-hw b{display:block;font-size:.58rem;color:#E31414}
.rt-ex{padding-bottom:0!important}.rt-ex .rt-dot{color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);border-radius:12px;box-shadow:0 0 0 3px #FFE3DE}
.rt-ex>div{border-radius:18px;padding:12px;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);box-shadow:0 14px 26px -18px rgba(227,20,20,.8)}
.rt-ex small{font-size:.6rem;font-weight:800;opacity:.9}.rt-ex b{display:block;font-size:.92rem;margin-top:2px}.rt-ex p{margin:2px 0 0;font-size:.66rem;opacity:.92}
/* ---- reschedule notice: stamped slip + ticket stubs ---- */
.rs-nt,.rs-pn{position:relative;border-radius:24px;margin:0 0 14px;background:#fff;box-shadow:0 0 0 1.5px #F7C9C4,0 18px 30px -22px rgba(190,30,25,.7);overflow:hidden}
.rs-top{position:relative;padding:16px 16px 14px;background:repeating-linear-gradient(-45deg,#FFF6F4 0 10px,#FFEFEC 10px 20px);border-bottom:2px dashed #F2CFCB}
.rs-top b{display:block;font-size:1.08rem;margin-top:6px;color:#2B1A1F}.rs-top p{margin:4px 0 0;padding-right:70px;font-size:.72rem;line-height:1.55;color:#7A4A44}
.rs-stamp{position:absolute;right:14px;top:14px;transform:rotate(-12deg);font-size:.78rem;font-weight:900;letter-spacing:.06em;color:#E31414;border:2.5px solid #E31414;border-radius:10px;padding:4px 9px;opacity:.85;box-shadow:inset 0 0 0 2px #fff,inset 0 0 0 3.5px rgba(227,20,20,.4)}
.rs-ls{list-style:none;margin:0;padding:6px 16px}
.rs-ls li{display:grid;grid-template-columns:44px 1fr auto;gap:10px;align-items:center;padding:9px 0;border-bottom:1px solid #FBE6E2}.rs-ls li:last-child{border-bottom:0}
.rs-dd{display:flex;flex-direction:column;align-items:center;border-radius:12px;padding:4px 0;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%)}.rs-dd b{font-family:var(--f-display);font-size:1.1rem;line-height:1.1}.rs-dd small{font-size:.52rem}
.rs-w{display:flex;flex-direction:column;font-size:.78rem;font-weight:700}.rs-w s{font-size:.64rem;font-weight:600;color:#B07A72}
.rs-ls em{font-style:normal;font-size:.6rem;font-weight:800;color:#E31414;background:#FFF1EF;border-radius:999px;padding:3px 9px}
.rs-why{margin:0 16px 12px;font-size:.7rem;line-height:1.55;color:var(--muted)}
.rs-go{font:inherit;display:flex;justify-content:center;align-items:center;gap:8px;width:calc(100% - 32px);margin:0 16px 16px;border:0;border-radius:16px;padding:13px;font-size:.86rem;font-weight:800;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);cursor:pointer;box-shadow:0 12px 22px -14px rgba(227,20,20,.9)}
.rs-go span{font-size:1.1rem}
.rs-bd{padding:14px 0 0}
.rs-tk{position:relative;display:grid;grid-template-columns:64px 1fr;margin:0 16px 10px;border-radius:18px;background:#fff;box-shadow:0 0 0 1px #F4E2DF,0 10px 20px -16px rgba(227,20,20,.5);overflow:hidden}
.rs-tk::before,.rs-tk::after{content:"";position:absolute;left:57px;width:14px;height:14px;border-radius:50%;background:#fff;box-shadow:inset 0 0 0 1px #F4E2DF;z-index:1}.rs-tk::before{top:-7px}.rs-tk::after{bottom:-7px}
.rs-stub{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:10px 0;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);border-right:2px dashed rgba(255,255,255,.7)}
.rs-stub b{font-family:var(--f-display);font-size:1.5rem;line-height:1}.rs-stub small{font-size:.6rem;font-weight:700}.rs-stub em{font-style:normal;font-size:.54rem;opacity:.9;margin-top:2px}
.rs-opt{padding:10px 10px 10px 14px;min-width:0}
.rs-old{margin:0 0 7px;font-size:.62rem;color:var(--muted)}.rs-old s{color:#B07A72;font-weight:700}
.rs-ch{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}
.rs-ch button{font:inherit;position:relative;display:flex;flex-direction:column;align-items:center;border:1.5px solid #F2CFCB;border-radius:12px;padding:8px 2px 6px;background:#fff;color:#2B1A1F;cursor:pointer}
.rs-ch b{font-family:var(--f-display);font-size:.98rem;line-height:1.1}.rs-ch small{font-size:.54rem;color:var(--muted)}
.rs-ch i{position:absolute;top:-8px;left:50%;transform:translateX(-50%);font-style:normal;font-size:.5rem;font-weight:800;white-space:nowrap;color:#E31414;background:#fff;border:1px solid #F2CFCB;border-radius:999px;padding:0 6px}
.rs-ch button.rs-on{border-color:transparent;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);box-shadow:0 8px 16px -10px rgba(227,20,20,.9)}.rs-ch button.rs-on small{color:rgba(255,255,255,.9)}
.rs-pv{margin:4px 16px 10px;padding:10px 12px;border-radius:16px;background:#FBF6F5}
.rs-pv>small{font-size:.6rem;font-weight:800;color:#7A4A44}
.rs-pv ol{list-style:none;margin:6px 0 0;padding:0;display:grid;grid-template-columns:repeat(3,1fr);gap:6px}
.rs-pv li{display:grid;grid-template-columns:auto 1fr;gap:0 6px;align-items:center;border-radius:12px;padding:6px 8px;background:#fff;box-shadow:0 0 0 1px #F4E2DF}
.rs-pv li i{grid-row:1/3;width:18px;height:18px;border-radius:6px;display:grid;place-items:center;font-style:normal;font-size:.56rem;font-weight:800;color:#fff;background:#D8C6C3}
.rs-pv li b{font-size:.62rem}.rs-pv li span{font-size:.6rem;color:var(--muted)}
.rs-pv li.rs-cg{box-shadow:0 0 0 1.5px #F24A4A}.rs-pv li.rs-cg i{background:#E31414}.rs-pv li.rs-cg span{color:#E31414;font-weight:800}
.rs-ft{margin:0 16px 10px;font-size:.66rem;color:var(--muted)}

/* ---- tutor timetable v3: teaching diary pages ---- */
.tzx-tl{display:flex;flex-direction:column;gap:12px}
.tzm{display:flex;align-items:center;gap:10px;margin:10px 4px 0;font-size:1rem;color:#2B1A1F}
.tzm::after{content:"";flex:1;height:1px;background:linear-gradient(90deg,#F2CFCB,transparent)}
.tzm em{order:3;font-style:normal;font-size:.6rem;font-weight:800;color:#E31414;background:#FFF1EF;border-radius:999px;padding:2px 9px}
.tzd{position:relative;border-radius:24px;padding:14px 14px 12px;background:#fff;box-shadow:0 0 0 1px #F4E2DF,0 16px 30px -24px rgba(190,30,25,.7);scroll-margin-top:12px}
.tzd-today{box-shadow:0 0 0 2px #F24A4A,0 18px 32px -22px rgba(227,20,20,.8)}
.tzd-h{display:flex;align-items:center;gap:8px}
.tzd-dt{display:flex;align-items:center;gap:8px;flex:1;min-width:0}
.tzd-dt b{font-family:var(--f-display);font-size:2rem;line-height:1;color:#E31414;letter-spacing:-.02em}
.tzd-dt span{display:flex;flex-direction:column;line-height:1.2}.tzd-dt strong{font-size:.86rem;color:#2B1A1F}.tzd-dt small{font-size:.6rem;color:var(--muted)}
.tzd-h>i{font-style:normal;font-size:.58rem;font-weight:800;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);border-radius:999px;padding:2px 9px}
.tzd-h>em{font-style:normal;font-size:.62rem;font-weight:700;color:#7A4A44;background:#FBF3F2;border-radius:999px;padding:3px 10px;white-space:nowrap}
.tzd-bar{margin:12px 0 4px}
.tzd-tr{position:relative;height:10px;border-radius:99px;background:repeating-linear-gradient(90deg,#F7E7E4 0 calc(25% - 1px),#fff calc(25% - 1px) 25%)}
.tzd-tr span{position:absolute;top:0;bottom:0;border-radius:99px;box-shadow:0 0 0 2px #fff}
.tzd-ax{position:relative;height:14px;margin-top:3px}
.tzd-ax small{position:absolute;transform:translateX(-50%);font-size:.5rem;color:#B9A19D}.tzd-ax small:first-child{transform:none}.tzd-ax small:last-child{transform:translateX(-100%)}
.tzd-rows{display:flex;flex-direction:column;gap:8px;margin-top:6px}
.tzr{display:grid;grid-template-columns:54px 1fr;gap:10px;border-radius:18px;padding:10px 12px 10px 10px;background:#fff;background:color-mix(in srgb,var(--c) 6%,#fff)}
.tzr-time{position:relative;display:flex;flex-direction:column;align-items:flex-start;padding-left:10px}
.tzr-time::before{content:"";position:absolute;left:0;top:2px;bottom:2px;width:4px;border-radius:4px;background:var(--c)}
.tzr-time b{font-family:var(--f-display);font-size:1.08rem;line-height:1.15;color:var(--c)}
.tzr-time small{font-size:.6rem;color:var(--muted)}.tzr-time small::before{content:"ถึง "}
.tzr-main{min-width:0}
.tzr-who{display:flex;align-items:center;gap:6px;min-width:0}
.tzr-av{flex:none;width:22px;height:22px;border-radius:8px;display:grid;place-items:center;font-size:.66rem;font-weight:800;color:#fff;background:var(--c)}
.tzr-who strong{font-size:.86rem;color:#2B1A1F;white-space:nowrap}.tzr-who small{font-size:.58rem;color:var(--muted)}
.tzr-st{margin-left:auto;display:inline-flex;align-items:center;gap:3px;font-size:.56rem;font-weight:800;border-radius:999px;padding:2px 8px;white-space:nowrap}
.tzr-st svg{width:10px;height:10px}
.tzr-so{color:#7A4A44;background:#fff;box-shadow:0 0 0 1px #F0DCD8}.tzr-sw{color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%)}.tzr-sd{color:#9A8380;background:#F3ECEB}
.tzr-tp{margin:5px 0 0;font-size:.74rem;line-height:1.45;color:#3E2A2E}
.tzr-tp em{display:block;font-style:normal;font-size:.56rem;font-weight:800;color:var(--c);letter-spacing:.02em}
.tzr-was{margin:5px 0 0;font-size:.6rem;color:#E31414;background:#fff;border-radius:8px;padding:3px 8px;box-shadow:0 0 0 1px #F6D0CB}
.tzr-pg{display:block;height:4px;margin-top:8px;border-radius:99px;background:rgba(255,255,255,.9);box-shadow:inset 0 0 0 1px #F2E2DF;overflow:hidden}
.tzr-pg>span{display:block;height:100%;border-radius:99px;background:var(--c)}
.tzr-past{opacity:.6}.tzr-cf{box-shadow:0 0 0 2px #E31414}
.tz-pa .tzd{box-shadow:0 0 0 1px #F4E2DF}

/* ---- tutor timetable v4: amusement-park admission tickets ---- */
.tkd{display:flex;flex-direction:column;gap:10px;scroll-margin-top:12px}
.tkd-h{display:grid;grid-template-columns:auto auto auto 1fr;gap:8px;align-items:center;padding:0 4px}
.tkd-h>b{font-family:var(--f-display);font-size:1.9rem;line-height:1;color:#E31414}
.tkd-h>span{display:flex;flex-direction:column;line-height:1.2}.tkd-h strong{font-size:.84rem;color:#2B1A1F}.tkd-h small{font-size:.58rem;color:var(--muted)}
.tkd-h>i{font-style:normal;font-size:.56rem;font-weight:800;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);border-radius:999px;padding:2px 8px}
.tkd-bar{grid-column:4;min-width:0}.tkd-bar .tzd-tr{height:8px}.tkd-bar .tzd-ax{height:12px}
.tkd-h:not(:has(>i)) .tkd-bar{grid-column:3/5}
.tkd-l{display:flex;flex-direction:column;gap:12px}
.tkt{--n:86px;position:relative;display:grid;grid-template-columns:1fr var(--n);filter:drop-shadow(0 10px 14px rgba(190,30,25,.16)) drop-shadow(0 0 .6px rgba(190,30,25,.35));
 -webkit-mask:radial-gradient(circle 10px at calc(100% - var(--n)) 0,#0000 97%,#000) top/100% 51% no-repeat,radial-gradient(circle 10px at calc(100% - var(--n)) 100%,#0000 97%,#000) bottom/100% 51% no-repeat;
 mask:radial-gradient(circle 10px at calc(100% - var(--n)) 0,#0000 97%,#000) top/100% 51% no-repeat,radial-gradient(circle 10px at calc(100% - var(--n)) 100%,#0000 97%,#000) bottom/100% 51% no-repeat}
.tkt-m{position:relative;min-width:0;padding:0 14px 12px 20px;border-radius:18px 0 0 18px;overflow:hidden;
 background:repeating-linear-gradient(-45deg,transparent 0 9px,color-mix(in srgb,var(--c) 4%,transparent) 9px 18px),#fff}
.tkt-m::before{content:"";position:absolute;left:0;top:0;bottom:0;width:8px;background:radial-gradient(circle at 0 50%,var(--paper,#FBF3F2) 4px,transparent 4.6px) 0 0/8px 13px repeat-y}
.tkt-band{display:flex;justify-content:space-between;align-items:center;gap:8px;margin:0 -14px 10px -20px;padding:6px 14px 6px 20px;background:var(--c);color:#fff}
.tkt-band span{font-size:.54rem;font-weight:800;letter-spacing:.08em}.tkt-band b{font-family:ui-monospace,Menlo,monospace;font-size:.58rem;letter-spacing:.06em;opacity:.95}
.tkt-b{display:flex;align-items:center;justify-content:space-between;gap:10px}
.tkt-tm b{display:block;font-family:var(--f-display);font-size:1.9rem;line-height:1;color:var(--c);letter-spacing:-.02em}.tkt-tm small{font-size:.6rem;color:var(--muted)}
.tkt-who{display:flex;align-items:center;gap:7px;min-width:0}.tkt-who>div{display:flex;flex-direction:column;line-height:1.2;min-width:0}
.tkt-who strong{font-size:.86rem;color:#2B1A1F;white-space:nowrap}.tkt-who small{font-size:.56rem;color:var(--muted)}
.tkt-av{flex:none;width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font-size:.74rem;font-weight:800;color:var(--c);background:#fff;box-shadow:0 0 0 2px var(--c)}
.tkt-tp{margin:8px 0 0;font-size:.76rem;font-weight:700;line-height:1.4;color:#3E2A2E}
