.tzs-bd{display:flex;flex-direction:column;gap:10px;padding:10px 16px 4px}
.tzs-prev{border-radius:14px;padding:10px 12px;background:#FFF6F4}.tzs-prev small{font-size:.58rem;font-weight:800;color:#B07A72}.tzs-prev p{margin:2px 0 6px;font-size:.74rem;color:#2B1A1F;line-height:1.5}
.tzs-ck{display:flex;align-items:center;gap:8px;font-size:.78rem;font-weight:700;color:#2B1A1F;cursor:pointer}.tzs-ck input{position:absolute;opacity:0;pointer-events:none}
