.tzs-ck input:checked+i{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);box-shadow:none;position:relative}.tzs-ck input:checked+i::after{content:"";position:absolute;left:7px;top:3px;width:6px;height:11px;border:solid #fff;border-width:0 2.5px 2.5px 0;transform:rotate(45deg)}
