.tzs-f{display:flex;flex-direction:column;gap:4px}.tzs-f span{font-size:.64rem;font-weight:800;color:#7A4A44}
.tzs-f textarea,.tzs-f input,.tzs-msg{font:inherit;font-size:.82rem;border:1.5px solid #F2CFCB;border-radius:12px;padding:9px 11px;background:#fff;color:#2B1A1F;resize:vertical;min-width:0}
.tzs-msg{width:100%;box-sizing:border-box;line-height:1.6}
.tzs-go{font:inherit;border:0;border-radius:14px;padding:12px;font-size:.84rem;font-weight:800;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);cursor:pointer;box-shadow:0 10px 18px -12px rgba(227,20,20,.9)}.tzs-go:disabled{opacity:.45;box-shadow:none}
.tzs-hint{margin:0;font-size:.62rem;color:var(--muted);line-height:1.5}
.tzs-seg{display:flex;gap:6px}
