.tzs-row{display:flex;gap:8px}.tzs-sub{font:inherit;flex:1;border:0;border-radius:12px;padding:10px;font-size:.74rem;font-weight:800;color:#7A4A44;background:#FBF1EF;cursor:pointer}.tzs-sub.danger{color:#E31414;background:#FFE7E4}
