.tzsc-h,.tzmo-h{display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap}.tzsc-h b,.tzmo-h b{font-size:.92rem}.tzsc-h small{font-size:.6rem;color:var(--muted)}
.tzsc-g{display:grid;grid-template-columns:1fr 1fr;gap:8px}.tzsc-g label{display:flex;flex-direction:column;gap:4px}.tzsc-g span{font-size:.66rem;font-weight:800;color:#7A4A44}.tzsc-g span small{display:block;font-size:.54rem;font-weight:600;color:var(--muted)}
