.tzsc-bars{display:flex;flex-direction:column;gap:6px}.tzsc-bars div{display:grid;grid-template-columns:56px 1fr 30px;gap:8px;align-items:center}.tzsc-bars small{font-size:.6rem;color:var(--muted)}
.tzsc-bars i{display:block;height:10px;border-radius:99px;background:#F6E3DF;overflow:hidden}.tzsc-bars s{display:block;height:100%;border-radius:99px;background:#E9B8B2}.tzsc-bars s.p{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%)}.tzsc-bars b{font-size:.8rem;text-align:right}
.tzsc-d{margin:0;font-size:.8rem;font-weight:800}.tzsc-d.up{color:#E31414}.tzsc-d.dn{color:#9A8380}
