.tzmo-k{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.tzmo-k span{display:flex;flex-direction:column;align-items:center;border-radius:14px;padding:8px 2px;background:#FFF6F4}.tzmo-k b{font-family:var(--f-display);font-size:1.3rem;color:#E31414}.tzmo-k small{font-size:.54rem;color:var(--muted);text-align:center}
