.tzmo-t td{text-align:center;padding:7px 2px;border-bottom:1px dashed #F3E0DC}.tzmo-t td b{display:block;font-size:.76rem}.tzmo-t td small{font-size:.54rem;color:var(--muted)}
.tzmo-x{border-radius:12px;padding:8px 10px;background:#FFF6F4;display:flex;flex-direction:column;gap:6px}.tzmo-x>small{font-size:.58rem;font-weight:800;color:#B07A72}.tzmo-x div{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:.68rem}
.tzmo-x button{font:inherit;border:0;border-radius:999px;padding:3px 10px;font-size:.6rem;font-weight:800;color:#E31414;background:#fff;box-shadow:0 0 0 1px #F6D0CB;cursor:pointer}
.rt-hw2{display:inline-block;margin-top:4px;font-size:.58rem;font-weight:700;color:#B07A72;background:#FFF6F4;border-radius:8px;padding:2px 8px}.rt-hw2.ok{color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%)}
.k-lsn{background:#F24A4A}
