.at small.k-lsn{color:#E31414;background:none}
.tzs-f textarea{min-height:0!important;height:62px}

/* ---- tutor forms in the same ticket style ---- */
.tzk{background:linear-gradient(112deg,rgba(255,255,255,0) 28%,rgba(255,255,255,.95) 40%,rgba(255,255,255,0) 54%),linear-gradient(165deg,#FFFFFF 0%,#FFF6F5 45%,#FFECE9 100%)!important;padding:0 0 calc(16px + env(safe-area-inset-bottom))!important}
.tzk-hd{position:sticky;top:0;z-index:2;display:flex;align-items:center;gap:8px;padding:14px 16px 12px;border-bottom:1.5px solid #F6D3CE;background:linear-gradient(180deg,rgba(255,255,255,.96),rgba(255,240,238,.96));border-radius:24px 24px 0 0}
.tzk-ty{flex:1;font-size:.7rem;font-weight:800;color:#7A4A44;letter-spacing:.03em}
.tzk-hd b{font-family:ui-monospace,Menlo,monospace;font-size:.62rem;color:#B07A72;letter-spacing:.04em}
.tzk .tzs-x{width:30px;height:30px;font-size:1.05rem;background:#fff;box-shadow:0 0 0 1px #F6D3CE}
.tzk-rt{display:grid;grid-template-columns:auto minmax(18px,1fr) auto;gap:8px;align-items:center;padding:12px 16px 0}
.tzk-st{display:flex;flex-direction:column;line-height:1.1}.tzk-st.tzk-r{align-items:flex-end;text-align:right}
.tzk-st small{font-size:.54rem;font-weight:800;letter-spacing:.08em;color:#B07A72}
.tzk-st b{font-family:var(--f-display);font-size:1.7rem;letter-spacing:-.02em;color:#E31414}.tzk-st.tzk-r b{color:#2B1A1F}
.tzk-st span{font-size:.56rem;color:var(--muted)}
.tzk-ln{display:flex;flex-direction:column;align-items:center;gap:3px}
.tzk-ln i{position:relative;display:block;width:100%;height:10px;background:radial-gradient(circle,#F24A4A 2px,transparent 2.4px) 0 50%/8px 10px repeat-x}
.tzk-ln i::before{content:"";position:absolute;left:-2px;top:50%;width:9px;height:9px;margin-top:-4.5px;border-radius:50%;background:#fff;box-shadow:inset 0 0 0 2.5px #E31414}
.tzk-ln i::after{content:"";position:absolute;right:-2px;top:50%;margin-top:-5px;border-left:9px solid #E31414;border-top:5px solid transparent;border-bottom:5px solid transparent}
.tzk-ln em{font-style:normal;font-size:.54rem;font-weight:800;color:#E31414;background:#fff;border-radius:999px;padding:1px 8px;box-shadow:0 0 0 1px #F6D3CE}
.tzk-f{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr) minmax(0,.8fr);margin:10px 16px 0;border-top:1.5px dashed #EFD3CF;border-bottom:1.5px dashed #EFD3CF}
.tzk-f span{display:flex;flex-direction:column;line-height:1.25;padding:6px 6px 6px 0;min-width:0}.tzk-f span+span{padding-left:8px;border-left:1px solid #F3E0DC}
.tzk-f small{font-size:.5rem;font-weight:800;letter-spacing:.06em;color:#B9A19D}.tzk-f b{font-size:.74rem;color:#2B1A1F;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tzk-tp{margin:8px 16px 0;font-size:.82rem;font-weight:800;color:#3E2A2E;line-height:1.4}.tzk-tp small{display:block;font-size:.5rem;letter-spacing:.06em;color:#B9A19D}
/* tabs = mini tickets */
.tzk .tzs-tb{gap:6px;padding:12px 16px 2px;border-bottom:0}
.tzk .tzs-tb button{position:relative;flex:1;border-radius:12px;padding:9px 6px;font-size:.68rem;color:#2B1A1F;background:radial-gradient(circle 5px at 0 50%,var(--paper,#FBF3F2) 95%,transparent 100%),radial-gradient(circle 5px at 100% 50%,var(--paper,#FBF3F2) 95%,transparent 100%),#fff;box-shadow:inset 0 0 0 1.5px #F6D0CB}
.tzk .tzs-tb button.on{color:#fff;background:radial-gradient(circle 5px at 0 50%,var(--paper,#FBF3F2) 95%,transparent 100%),radial-gradient(circle 5px at 100% 50%,var(--paper,#FBF3F2) 95%,transparent 100%),linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);box-shadow:none}
.tzk .tzs-bd{gap:12px;padding:12px 16px 4px}
/* fields like ticket fields */
.tzk .tzs-f span{font-size:.54rem;font-weight:800;letter-spacing:.06em;color:#B9A19D}
.tzk .tzs-f textarea,.tzk .tzs-f input,.tzk .tzs-msg{border:0;border-radius:14px;background:#fff;box-shadow:inset 0 0 0 1.5px #F6D0CB;padding:10px 12px;font-size:.84rem;color:#2B1A1F}
.tzk .tzs-f textarea:focus,.tzk .tzs-f input:focus,.tzk .tzs-msg:focus{outline:none;box-shadow:inset 0 0 0 2px #F24A4A}
.tzk .tzs-prev{border-radius:14px;background:#fff;box-shadow:inset 0 0 0 1.5px #F6D0CB;border-top:3px solid #F24A4A}
.tzk .tzs-prev small{font-size:.5rem;letter-spacing:.06em;color:#B9A19D}
.tzk .tzs-ck.big{border-radius:14px;box-shadow:inset 0 0 0 1.5px #F6D0CB;background:#fff}
.tzk .tzs-ck i{border-radius:8px}
/* buttons and time slots like the timetable */
.tzk .tzs-go{border-radius:999px;padding:13px;box-shadow:0 10px 18px -12px rgba(227,20,20,.9)}
.tzk .tzs-seg button{flex:1;border-radius:12px;background:#fff;box-shadow:inset 0 0 0 1.5px #F6D0CB;color:#2B1A1F}.tzk .tzs-seg button.on{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);box-shadow:none;color:#fff}
.tzk .tzs-sl button{border:0;border-radius:12px;background:#fff;box-shadow:inset 0 0 0 1.5px #F6D0CB}
.tzk .tzs-sl b{font-family:var(--f-display);font-size:1rem;color:#E31414}
.tzk .tzs-sl button.on{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);box-shadow:none}.tzk .tzs-sl button.on b{color:#fff}
.tzk .tzs-sl button.x{background:#F7EFEE;box-shadow:none}.tzk .tzs-sl button.x b{color:#C9B1AE}
.tzk .tzs-sub{border-radius:999px;background:#fff;box-shadow:inset 0 0 0 1.5px #F6D0CB}.tzk .tzs-sub.danger{box-shadow:inset 0 0 0 1.5px #F2A39A}
/* score + monthly report as tickets */
.tzsc,.tzmo{background:linear-gradient(112deg,rgba(255,255,255,0) 28%,rgba(255,255,255,.95) 40%,rgba(255,255,255,0) 54%),linear-gradient(165deg,#FFFFFF 0%,#FFF6F5 45%,#FFECE9 100%)!important;border-radius:16px!important;box-shadow:0 0 0 1px rgba(205,95,85,.20),0 2px 4px rgba(120,25,20,.07),0 12px 20px -14px rgba(190,30,25,.38)!important}
.tzsc-h,.tzmo-h{padding-bottom:9px;border-bottom:1.5px solid #F6D3CE}
.tzsc-h::before,.tzmo-h::before{content:"MYCROSOC";flex:none;font-size:.54rem;font-weight:900;letter-spacing:.12em;color:#fff;background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%);border-radius:5px;padding:2px 6px}
.tzsc-h b,.tzmo-h>b{flex:1;font-size:.86rem}
.tzsc-g{grid-template-columns:minmax(0,1fr) minmax(0,1fr)!important}.tzsc-g input{width:100%;box-sizing:border-box;border:0;border-radius:14px;background:#fff;box-shadow:inset 0 0 0 1.5px #F6D0CB;font-family:var(--f-display);font-size:1.5rem}
.tzsc-g span{font-size:.54rem;letter-spacing:.06em;color:#B9A19D}.tzsc-g span small{color:var(--muted)}
.tzsc-d{text-align:center;border-radius:999px;padding:6px 10px;background:#fff;box-shadow:inset 0 0 0 1.5px #F6D0CB}
.tzsc .tzs-go,.tzmo .tzs-go{border-radius:999px}
.tzmo-k span{border-radius:12px;background:radial-gradient(circle 5px at 0 50%,#FFF4F2 95%,transparent 100%),radial-gradient(circle 5px at 100% 50%,#FFF4F2 95%,transparent 100%),#fff;box-shadow:inset 0 0 0 1.5px #F6D0CB}
.tzmo-t th{font-size:.5rem;letter-spacing:.06em;color:#B9A19D}
.tzmo-t td{border-bottom:1.5px dashed #EFD3CF}

/* ---- calendar: event dots pinned to the cell corner so the date number never moves ---- */
.day,.cxm .day{position:relative!important;flex-direction:column!important;justify-content:center!important;align-items:center!important;gap:0!important}
.day>i,.cxm .day>i{position:absolute!important;top:6px!important;right:6px!important;left:auto!important;bottom:auto!important;margin:0!important;height:auto!important;display:flex!important;flex-direction:row!important;gap:2px!important;transform:none!important}
.day>i b,.cxm .day>i b{width:6px!important;height:6px!important}
.day>span,.cxm .day>span{position:absolute!important;inset:0!important;display:flex!important;align-items:center!important;justify-content:center!important;margin:0!important;padding:0!important;line-height:1!important;text-align:center!important}
#fcwrap{touch-action:pan-y!important;-webkit-touch-callout:none}
#fcwrap *{-webkit-user-select:none;user-select:none}

/* ---- flashcards: tap to flip, then tap a big answer on the card (swipe is unreliable inside the iOS app viewer) ---- */
.fl-zones{position:absolute;left:12px;right:12px;bottom:12px;z-index:4;display:none;grid-template-columns:1fr 1fr;gap:8px}
.fc-in.flip~.fl-zones{display:grid;animation:fzIn .25s ease-out .2s both}
@keyframes fzIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.fc-in.flip~.fl-zones{animation:none}}
.fl-zones button{font:inherit;display:flex;align-items:center;justify-content:center;gap:6px;border:0;border-radius:14px;padding:12px 6px;font-size:.84rem;font-weight:800;cursor:pointer;-webkit-tap-highlight-color:transparent}
.fl-zones b{font-size:1rem}
.fz-no{color:#E31414;background:#fff;box-shadow:0 8px 16px -10px rgba(120,25,20,.6)}
.fz-ok{color:#E31414;background:#fff;box-shadow:0 0 0 2px #fff,0 8px 16px -10px rgba(120,25,20,.6)}
.fz-ok{background:#FFF1EF}
.fl-zones button:active{transform:scale(.96)}
.fc-in.flip .face.back .fl-tap{visibility:hidden}
#fcwrap .face.back{padding-bottom:76px}

/* ---- foldable end-of-section questions ---- */
.qz-h{cursor:pointer;-webkit-tap-highlight-color:transparent;position:relative}
.qz-chev{display:inline-flex;align-items:center;gap:6px;margin-left:auto;flex:none}
.qz-chev em{font-style:normal;font-size:.6rem;font-weight:800;color:#E31414;background:#FFF1EF;border-radius:999px;padding:2px 8px}
.qz-chev i{width:24px;height:24px;border-radius:50%;background:#FFF1EF;position:relative;flex:none}
.qz-chev i::after{content:"";position:absolute;left:8px;top:6px;width:6px;height:6px;border:solid #E31414;border-width:0 2px 2px 0;transform:rotate(-135deg);transition:transform .2s}
.qz.qz-c .qz-chev i::after{transform:rotate(45deg);top:7px}
.qz.qz-c>*:not(.qz-h){display:none!important}
.qz.qz-c{padding-bottom:12px}
.qz.qz-c .qz-h{margin-bottom:0}
.qz.qz-c .qz-chev i{background:linear-gradient(155deg,#FF7A7A 0%,#F24A4A 50%,#E31414 100%)}.qz.qz-c .qz-chev i::after{border-color:#fff}
.hx-qh.qz-h,.hx-sgh.qz-h{display:flex;align-items:center;gap:8px;flex-wrap:wrap}

/* ==== lesson 1 · bespoke section designs (hz-) ==== */
.lz-body [class^="hz-"] ol,.lz-body [class^="hz-"] ul{list-style:none;margin:0;padding:0!important}
.lz-body [class^="hz-"] li:before{display:none!important}
.lz-body [class^="hz-"] li{padding:0!important}
.hz-crowd{display:flex;gap:3px;flex-wrap:wrap}
.hz-pp{width:15px;height:19px;fill:#E31414}.hz-pp.z-off{fill:none;stroke:#E8A6AC;stroke-width:1.2;stroke-dasharray:2 1.6}
/* 05 route */
.hz-route{position:relative;padding:14px 14px 12px;border-radius:20px;background:radial-gradient(circle at 100% 0,#FFE3E6 0,transparent 55%),#fff;box-shadow:inset 0 0 0 1px #F4DDE0,0 12px 22px -18px rgba(180,30,30,.6);overflow:hidden}
.hz-rh{display:flex;justify-content:space-between;align-items:baseline;gap:8px;margin-bottom:12px}
.hz-rh small{font-size:.6rem;color:#A08C8F}.hz-rh b{font:800 .58rem var(--f-mono,monospace);letter-spacing:.12em;color:#E31414}
.hz-route ol{position:relative;display:grid!important;grid-template-columns:repeat(4,minmax(0,1fr));gap:2px!important}
.hz-route ol:before{content:"";position:absolute;left:12%;right:12%;top:8px;height:3px;border-radius:3px;background:repeating-linear-gradient(90deg,#F24A4A 0 8px,transparent 8px 13px)}
.hz-route li{position:relative;display:flex;flex-direction:column;align-items:center;text-align:center;line-height:1.25;min-width:0}
.hz-route li i{width:19px;height:19px;border-radius:50%;background:#fff;box-shadow:inset 0 0 0 4px #F24A4A;margin-bottom:6px;position:relative;z-index:1}
.hz-route li.z-end i{background:linear-gradient(155deg,#FF7A7A,#F24A4A 50%,#E31414);box-shadow:0 0 0 4px #FFE1E5}
.hz-route li b{font-size:.92rem;color:#2B1A1F;font-variant-numeric:tabular-nums}
.hz-route li span{font-size:.62rem;font-weight:800;color:#E31414;overflow-wrap:anywhere}
.hz-route li small{font-size:.54rem;color:#A08C8F}
/* 05 stamps */
.lz-body .hx-tabs.hz-eu .hx-sg.hz-stamps{grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:8px;padding:2px;background:none;box-shadow:none}
.hx-tabs.hz-eu .hz-stamps button{position:relative;padding:12px 4px 10px!important;border-radius:2px;color:#2B1A1F;background:radial-gradient(circle 3px at 50% 0,#fff 92%,transparent 100%) top/9px 6px repeat-x,radial-gradient(circle 3px at 50% 100%,#fff 92%,transparent 100%) bottom/9px 6px repeat-x,radial-gradient(circle 3px at 0 50%,#fff 92%,transparent 100%) left/6px 9px repeat-y,radial-gradient(circle 3px at 100% 50%,#fff 92%,transparent 100%) right/6px 9px repeat-y,#FFF3F4!important;box-shadow:0 8px 14px -10px rgba(180,30,30,.6)!important}
.hx-tabs.hz-eu .hz-stamps button:after{content:"";position:absolute;inset:7px;border:1px dashed #F2B9BE;border-radius:3px;pointer-events:none}
.hx-tabs.hz-eu .hz-stamps button em{font-style:normal;font-family:var(--f-display);font-size:1.25rem;font-weight:900;line-height:1;color:#E31414}
.hx-tabs.hz-eu .hz-stamps button b{font-size:.74rem;margin-top:3px}.hx-tabs.hz-eu .hz-stamps button small{font-size:.54rem;color:#A08C8F}
.hx-tabs.hz-eu .hz-stamps button.on{background:radial-gradient(circle 3px at 50% 0,#fff 92%,transparent 100%) top/9px 6px repeat-x,radial-gradient(circle 3px at 50% 100%,#fff 92%,transparent 100%) bottom/9px 6px repeat-x,radial-gradient(circle 3px at 0 50%,#fff 92%,transparent 100%) left/6px 9px repeat-y,radial-gradient(circle 3px at 100% 50%,#fff 92%,transparent 100%) right/6px 9px repeat-y,linear-gradient(155deg,#FF7A7A,#F24A4A 50%,#E31414)!important;color:#fff}
.hx-tabs.hz-eu .hz-stamps button.on em,.hx-tabs.hz-eu .hz-stamps button.on small{color:#fff}.hx-tabs.hz-eu .hz-stamps button.on:after{border-color:rgba(255,255,255,.6)}
.hx-tabs.hz-eu .hx-pn,.hx-tabs.hz-ct .hx-pn{padding:0;background:none;box-shadow:none}
.hz-card{display:flex;flex-direction:column;gap:12px;padding:14px;border-radius:20px;background:#fff;box-shadow:inset 0 0 0 1px #F4DDE0,0 14px 24px -20px rgba(180,30,30,.7)}
.hz-ch{display:flex;gap:10px;align-items:center}
.hz-ch>span{flex:none;width:40px;height:40px;border-radius:13px;display:grid;place-items:center;background:linear-gradient(155deg,#FF7A7A,#F24A4A 50%,#E31414);box-shadow:0 8px 14px -8px rgba(227,20,20,.9)}
.hz-ch svg,.hz-tree .z-ic svg,.hz-lens .z-o svg,.hz-wl .z-ic svg,.hz-su .z-ic svg{width:22px;height:22px;fill:none;stroke:#fff;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.hz-ch div{display:flex;flex-direction:column;line-height:1.3;min-width:0}.hz-ch small{font-size:.56rem;color:#A08C8F}.hz-ch b{font-size:.9rem;color:#2B1A1F}
.hz-p{font-size:.78rem;line-height:1.7;color:#3A2A2E}
.hz-stat{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}
.hz-stat div{display:flex;flex-direction:column;align-items:center;text-align:center;padding:10px 4px;border-radius:14px;background:#FFF5F6;box-shadow:inset 0 0 0 1px #F7D3D8}
.hz-stat b{font-family:var(--f-display);font-size:1.4rem;line-height:1.05;color:#E31414}.hz-stat small{font-size:.56rem;line-height:1.35;color:#7A5A5F;margin-top:3px}
.hz-grid14{display:flex;gap:12px;align-items:center}
.hz-grid14>div{flex:none;display:grid;grid-template-columns:repeat(7,9px);gap:3px;padding:7px;border-radius:10px;box-shadow:inset 0 0 0 1.5px #F24A4A}
.hz-grid14 i{width:9px;height:9px;border-radius:2px;background:#F9C5CA}.hz-grid14 i:nth-child(3n){background:#F24A4A}
.hz-grid14 span{font-size:.7rem;line-height:1.6;color:#4A3A3D}.hz-grid14 span b{display:block;color:#E31414;font-size:.74rem}
.hz-pol{display:flex;flex-direction:column;gap:6px}
.hz-pol>div{display:flex;align-items:stretch;border-radius:12px;background:#fff;box-shadow:inset 0 0 0 1px #F4DDE0;overflow:hidden}
.hz-pol em{flex:none;width:58px;display:grid;place-items:center;font-style:normal;font-family:var(--f-display);font-size:1.02rem;font-weight:900;color:#fff;background:linear-gradient(155deg,#FF7A7A,#F24A4A 50%,#E31414);position:relative}
.hz-pol em:after{content:"";position:absolute;right:-4px;top:0;bottom:0;width:8px;background:radial-gradient(circle 3px at 4px 50%,#fff 96%,transparent) 0 0/8px 9px repeat-y}
.hz-pol span{display:flex;flex-direction:column;padding:8px 12px;line-height:1.3;min-width:0}
.hz-pol small{font:700 .5rem var(--f-mono,monospace);letter-spacing:.1em;color:#C9A4A8}.hz-pol b{font-size:.8rem;color:#2B1A1F}.hz-pol i{font-style:normal;font-size:.6rem;color:#A08C8F}
.hz-flow{display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:4px}
.hz-flow span{font-size:.64rem;font-weight:800;color:#C21A1A;padding:5px 9px;border-radius:999px;background:#FFF0F1;box-shadow:inset 0 0 0 1px #F7D3D8}
.hz-flow span.z-f{background:#fff;box-shadow:inset 0 0 0 1.5px #F24A4A}.hz-flow span.z-r{color:#fff;background:linear-gradient(155deg,#FF7A7A,#F24A4A 50%,#E31414);box-shadow:none}
.hz-flow i{font-style:normal;font-size:.7rem;font-weight:800;color:#F2A0A8}
.hz-rep{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px}
.hz-rep>div{position:relative;display:flex;flex-direction:column;gap:2px;padding:12px 10px 10px;border-radius:4px 14px 14px 14px;background:linear-gradient(180deg,#fff,#FFF8F8);box-shadow:inset 0 0 0 1px #F4DDE0,0 8px 14px -12px rgba(150,30,30,.6)}
.hz-rep>div:before{content:"";position:absolute;right:0;top:0;width:16px;height:16px;background:linear-gradient(225deg,#FBF3F2 50%,#F7D3D8 50%);border-radius:0 14px 0 4px}
.hz-rep small{font:800 .5rem var(--f-mono,monospace);letter-spacing:.08em;color:#C9A4A8}.hz-rep b{font-size:.8rem;color:#2B1A1F}.hz-rep span{font-size:.6rem;color:#A08C8F;line-height:1.35}
.hz-rep p{margin-top:6px!important;padding-top:6px;border-top:1px dashed #F4D6DA;font-size:.7rem;line-height:1.6;color:#4A3A3D}
.hz-rep .z-mi{background:linear-gradient(180deg,#FFF5F6,#FFE9EC);box-shadow:inset 0 0 0 1.5px #F24A4A}.hz-rep .z-mi small{color:#E31414}
.hz-out{display:flex;flex-wrap:wrap;align-items:center;gap:5px}.hz-out small{width:100%;font-size:.58rem;font-weight:800;color:#E31414}
.hz-out span{font-size:.64rem;color:#4A3A3D;padding:5px 9px;border-radius:10px;background:#fff;box-shadow:inset 0 0 0 1px #F4DDE0}.hz-out span b{color:#E31414;margin-right:4px}
.hz-gate{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px}
.hz-gate>div{display:flex;flex-direction:column;gap:6px;padding:12px;border-radius:18px;background:#fff;box-shadow:inset 0 0 0 1px #F4DDE0}
.hz-gate>div.z-all{background:linear-gradient(155deg,#FFF5F6,#FFE6EA);box-shadow:inset 0 0 0 1.5px #F24A4A}
.hz-gate small{font:800 .5rem var(--f-mono,monospace);letter-spacing:.08em;color:#E31414}.hz-gate b{font-size:.78rem;line-height:1.35;color:#2B1A1F}
.hz-gate p{font-size:.66rem;line-height:1.55;color:#5A4448}
/* 08 tree */
.hz-tree{display:flex;flex-direction:column;align-items:stretch}
.hz-tree .z-rt{display:flex;justify-content:center;gap:6px;position:relative;padding-bottom:14px}
.hz-tree .z-rt span{font-size:.62rem;font-weight:800;color:#fff;padding:5px 12px;border-radius:999px;background:linear-gradient(155deg,#FF7A7A,#F24A4A 50%,#E31414)}
.hz-tree .z-rt:after{content:"";position:absolute;left:50%;bottom:0;width:2px;height:14px;background:#F2A0A8}
.hz-tree .z-br{position:relative;display:flex;flex-direction:column;gap:8px;padding-left:22px}
.hz-tree .z-br:before{content:"";position:absolute;left:8px;top:-1px;bottom:26px;width:2px;background:#F2A0A8;border-radius:2px}
.hz-tree .z-br>div{position:relative;display:grid;grid-template-columns:auto minmax(0,1fr);column-gap:10px;padding:12px;border-radius:16px;background:#fff;box-shadow:inset 0 0 0 1px #F4DDE0}
.hz-tree .z-br>div:before{content:"";position:absolute;left:-14px;top:26px;width:14px;height:2px;background:#F2A0A8}
.hz-tree .z-ic{grid-row:span 3;width:38px;height:38px;border-radius:12px;display:grid;place-items:center;background:linear-gradient(155deg,#FF7A7A,#F24A4A 50%,#E31414)}
.hz-tree em{font-style:normal;font:800 .56rem var(--f-mono,monospace);color:#E31414}.hz-tree b{font-size:.86rem;color:#2B1A1F;line-height:1.3}.hz-tree small{font-size:.6rem;color:#A08C8F}
.hz-tree p{grid-column:1/-1;margin-top:6px!important;font-size:.72rem;line-height:1.6;color:#4A3A3D}
/* 08 debate */
.hz-deb{border-radius:20px;background:#fff;box-shadow:inset 0 0 0 1px #F4DDE0,0 14px 24px -20px rgba(180,30,30,.7);overflow:hidden}
.hz-deb .z-hd{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;padding:12px;background:linear-gradient(90deg,#FFF5F6,#fff 50%,#FFE6EA)}
.hz-deb .z-hd div{display:flex;flex-direction:column;line-height:1.25}.hz-deb .z-hd .z-r{text-align:right;align-items:flex-end}
.hz-deb .z-hd small{font:800 .52rem var(--f-mono,monospace);letter-spacing:.1em;color:#E31414}.hz-deb .z-hd b{font-size:.9rem;color:#2B1A1F}.hz-deb .z-hd span{font-size:.56rem;color:#A08C8F}
.hz-deb .z-hd i{font-style:normal;width:30px;height:30px;border-radius:50%;display:grid;place-items:center;font-size:.6rem;font-weight:900;color:#fff;background:linear-gradient(155deg,#FF7A7A,#F24A4A 50%,#E31414);box-shadow:0 0 0 4px #fff}
.hz-deb .z-rw{position:relative;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);border-top:1px dashed #F4D6DA;padding:18px 0 9px}
.hz-deb .z-rw:before{content:"";position:absolute;left:50%;top:0;bottom:0;width:1.5px;background:#F7D3D8}
.hz-deb .z-rw em{position:absolute;left:50%;top:0;transform:translate(-50%,-50%);font-style:normal;font-size:.56rem;font-weight:800;color:#E31414;background:#fff;padding:2px 9px;border-radius:999px;box-shadow:inset 0 0 0 1px #F2C9CC;white-space:nowrap;z-index:1}
.hz-deb .z-rw p{font-size:.7rem;line-height:1.55;color:#3A2A2E;padding:0 12px;text-align:right}.hz-deb .z-rw p.z-r{text-align:left}
.hz-deb .z-ft{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:#F7D3D8}
.hz-deb .z-ft span{font-size:.66rem;font-weight:800;color:#E31414;padding:9px 10px;background:#FFF5F6;text-align:center}.hz-deb .z-ft span.z-r{color:#fff;background:linear-gradient(155deg,#FF7A7A,#F24A4A 50%,#E31414)}
/* 08 merge */
.hz-merge{display:flex;flex-direction:column}
.hz-merge .z-two{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px;align-items:start}
.hz-merge .z-jn{position:relative;height:22px}
.hz-merge .z-jn i{position:absolute;top:0;height:22px;width:calc(25% + 2px);border-bottom:2px solid #F2A0A8}
.hz-merge .z-jn i:first-child{left:25%;border-left:2px solid #F2A0A8;border-radius:0 0 0 14px}
.hz-merge .z-jn i:last-child{right:25%;border-right:2px solid #F2A0A8;border-radius:0 0 14px 0}
.hz-merge .z-jn:after{content:"";position:absolute;left:50%;bottom:-10px;width:2px;height:12px;margin-left:-1px;background:#F2A0A8}
.hz-merge>.hz-n.z-M{margin-top:10px;box-shadow:inset 0 0 0 1.5px #F24A4A,0 12px 20px -14px rgba(227,20,20,.8)!important;background:linear-gradient(155deg,#FFF5F6,#fff)!important}
.hz-merge .z-trunk{position:relative;display:flex;flex-direction:column;gap:8px;margin-top:8px;padding-left:20px}
.hz-merge .z-trunk:before{content:"";position:absolute;left:7px;top:-8px;bottom:18px;width:2px;background:#F2A0A8}
.hz-merge .z-trunk .hz-n:before{content:"";position:absolute;left:-17px;top:17px;width:10px;height:10px;border-radius:50%;background:#fff;box-shadow:inset 0 0 0 2.5px #F24A4A;display:block!important}
.hz-merge .z-two .hz-n>button{flex-wrap:wrap;gap:6px}.hz-merge .z-two .hz-n>button span{flex-basis:100%;order:3}.hz-merge .z-two .hz-n>button svg{margin-left:auto}
.hz-n .hx-dt{margin:0!important}
.hz-merge .hz-n{overflow:visible!important}
.hz-4p{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px}
.hz-4p span{display:flex;flex-direction:column;padding:7px 9px;border-radius:10px;background:#fff;box-shadow:inset 0 0 0 1px #F4DDE0;font-size:.62rem;color:#7A5A5F;line-height:1.3}
.hz-4p b{font-size:.74rem;color:#E31414}
.hz-zoom{display:flex;flex-direction:column;align-items:center;gap:10px;padding:14px;border-radius:20px;background:#fff;box-shadow:inset 0 0 0 1px #F4DDE0}
.hz-zoom>div{display:flex;flex-direction:column;align-items:center}
.hz-zoom .z-c3,.hz-zoom .z-c2,.hz-zoom .z-c1{border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:flex-start;text-align:center;line-height:1.2}
.hz-zoom .z-c3{width:230px;height:230px;padding-top:12px;background:#FFF5F6;box-shadow:inset 0 0 0 1.5px #F7D3D8}
.hz-zoom .z-c2{width:160px;height:160px;padding-top:10px;margin-bottom:6px;background:#FFE3E7;box-shadow:inset 0 0 0 1.5px #F2A0A8}
.hz-zoom .z-c1{width:84px;height:84px;justify-content:center;margin-bottom:6px;background:linear-gradient(155deg,#FF7A7A,#F24A4A 50%,#E31414);color:#fff}
.hz-zoom b{font-size:.68rem;color:#C21A1A}.hz-zoom small{font:800 .52rem var(--f-mono,monospace);color:#E8A0A8}
.hz-zoom .z-c1 b,.hz-zoom .z-c1 small{color:#fff}
.hz-zoom p{font-size:.74rem;line-height:1.7;color:#3A2A2E;text-align:center}
/* 09 spectrum + lenses */
.hz-spec{display:flex;flex-direction:column;gap:6px;padding:12px 14px;border-radius:18px;background:#fff;box-shadow:inset 0 0 0 1px #F4DDE0}
.hz-spec .z-bar{height:10px;border-radius:999px;background:linear-gradient(90deg,#FFE3E6,#FF9A9A 40%,#F24A4A 70%,#E31414)}
.hz-spec .z-lb{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:2px}.hz-spec .z-lb span{font-size:.58rem;font-weight:800;color:#C21A1A;text-align:center;line-height:1.3}
.hz-spec small{display:flex;justify-content:space-between}.hz-spec small b{font-size:.54rem;color:#A08C8F}
.lz-body .hx-tabs.hz-ct .hx-sg.hz-lens{grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:8px;padding:0;background:none;box-shadow:none}
.hx-tabs.hz-ct .hz-lens button{gap:3px;padding:10px 4px 9px!important;border-radius:18px;background:#fff!important;box-shadow:inset 0 0 0 1px #F4DDE0!important;color:#2B1A1F}
.hx-tabs.hz-ct .hz-lens .z-o{width:44px;height:44px;border-radius:50%;display:grid;place-items:center;background:#FFF0F1;box-shadow:inset 0 0 0 1.5px #F7C9CE,0 0 0 4px #fff;margin-bottom:3px}
.hx-tabs.hz-ct .hz-lens .z-o svg{stroke:#E31414}
.hx-tabs.hz-ct .hz-lens b{font-size:.74rem}.hx-tabs.hz-ct .hz-lens small{font-size:.54rem;color:#A08C8F}
.hx-tabs.hz-ct .hz-lens button.on{background:linear-gradient(180deg,#FFF5F6,#FFE6EA)!important;box-shadow:inset 0 0 0 2px #E31414,0 10px 18px -12px rgba(227,20,20,.8)!important}
.hx-tabs.hz-ct .hz-lens button.on .z-o{background:linear-gradient(155deg,#FF7A7A,#F24A4A 50%,#E31414);box-shadow:0 0 0 4px #FFD3D9}.hx-tabs.hz-ct .hz-lens button.on .z-o svg{stroke:#fff}
.hx-tabs.hz-ct .hz-lens button.on b{color:#E31414}
.hz-lp{display:flex;flex-direction:column;gap:12px;padding:14px;border-radius:20px;background:#fff;box-shadow:inset 0 0 0 1px #F4DDE0,0 14px 24px -20px rgba(180,30,30,.7)}
.hz-lp blockquote{margin:0;padding:12px 14px;border-radius:16px;background:linear-gradient(155deg,#FF7A7A,#F24A4A 50%,#E31414);color:#fff;font-size:.84rem;line-height:1.65}
.hz-lp blockquote small{display:block;font-size:.56rem;font-weight:800;opacity:.85;margin-bottom:2px}.hz-lp blockquote b{color:#fff}
.hz-rings{display:flex;justify-content:center;align-items:center;padding:4px 0}
.hz-rings span{display:grid;place-items:center;font-size:.56rem;font-weight:800;color:#C21A1A;border-radius:999px;padding:6px 8px;margin-left:-6px;background:#fff;box-shadow:inset 0 0 0 1.5px #F2A0A8}
.hz-rings span:first-child{margin-left:0;color:#fff;background:linear-gradient(155deg,#FF7A7A,#F24A4A 50%,#E31414);box-shadow:none}
.hz-pcs>div{padding:8px;border-radius:16px;background:#FFF5F6;box-shadow:inset 0 0 0 1.5px #F7D3D8}
.hz-pcs div div{margin-top:6px;padding:8px;border-radius:12px;background:#FFE3E7;box-shadow:inset 0 0 0 1.5px #F2A0A8}
.hz-pcs div div div{background:linear-gradient(155deg,#FF7A7A,#F24A4A 50%,#E31414);box-shadow:none;color:#fff;text-align:center}
.hz-pcs b{font-family:var(--f-display);font-size:.95rem;color:#E31414;margin-right:6px}.hz-pcs small{font-size:.62rem;font-weight:700;color:#7A3A40}
.hz-pcs div div div b,.hz-pcs div div div small{color:#fff}
.hz-ph{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px}
.hz-ph div{position:relative;display:flex;flex-direction:column;align-items:center;text-align:center;padding:9px 4px;background:#FFF0F1;line-height:1.3;clip-path:polygon(0 0,88% 0,100% 50%,88% 100%,0 100%,10% 50%)}
