.psx-route{position:relative;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;padding:6px 0 4px}
.psx-fly{position:absolute;left:0;right:0;top:44%;width:100%;height:40px;z-index:0}
.psx-st{position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;text-align:center;gap:2px;padding:9px 6px 8px;color:#E31414;background:rgba(255,249,250,.85);border:2px solid currentColor;border-radius:10px;box-shadow:inset 0 0 0 2px #FFF9FA,inset 0 0 0 3px currentColor;mix-blend-mode:multiply}
.psx-st.a{transform:rotate(-5deg)}
.psx-st.b{transform:rotate(3deg) translateY(6px);border-radius:999px/60%;padding:12px 8px;color:#F24A4A}
.psx-st.c{transform:rotate(-2deg)}
.psx-st small{font-size:.44rem;font-weight:800;letter-spacing:.04em;line-height:1.3}
.psx-st em{font-style:normal;font-size:.5rem;font-weight:700;opacity:.8}
.psx-st b{font-size:.7rem;font-weight:800;line-height:1.3;color:#C8141E}
.psx-st span{font-size:.5rem;font-weight:800;padding:1px 6px;border-top:1px solid currentColor;margin-top:2px;font-family:"IBM Plex Mono",ui-monospace,monospace}
.psx-end{align-self:flex-end;display:flex;align-items:center;gap:6px;padding:5px 12px;border:1.5px dashed #F24A4A;border-radius:8px;transform:rotate(-1.5deg);color:#E31414}
.psx-end span{font-size:.58rem;font-weight:700;color:#8A6A70}.psx-end b{font-size:.8rem;font-weight:800}.psx-end i{font-style:normal;font-size:.46rem;font-weight:800;letter-spacing:.08em;opacity:.7}
.psx-stat{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}
.psx-stat div{display:flex;flex-direction:column;align-items:center;gap:1px;padding:8px 2px;border-radius:12px;background:#fff;box-shadow:inset 0 0 0 1px #F6DCE0}
.psx-stat b{font-size:.96rem;font-weight:800;color:#E31414}.psx-stat small{font-size:.5rem;font-weight:700;color:#8A6A70}
.psx-mrz{display:flex;flex-direction:column;gap:2px;padding:10px 10px 8px;margin:0 -16px -16px;background:#FFF0F2;border-top:1px solid #F6C9CF;overflow:hidden}
.psx-mrz span{font-family:"IBM Plex Mono",ui-monospace,monospace;font-size:clamp(.56rem,2.9vw,.8rem);font-weight:600;letter-spacing:.12em;color:#6A3A42;white-space:nowrap}
@media(min-width:600px){.psx-main{grid-template-columns:110px minmax(0,1fr)}.psx-ph{width:110px;height:140px}.psx-ph canvas{width:100px;height:100px;left:5px}.psx-f{grid-template-columns:repeat(3,1fr)}.psx-st b{font-size:.84rem}.psx-st small{font-size:.54rem}}
.ntx{--L:2.05rem;position:relative;padding:14px 4px 6px}
.ntx-tape{position:absolute;z-index:2;top:2px;left:50%;width:120px;height:30px;margin-left:-60px;transform:rotate(-3deg);background:repeating-linear-gradient(45deg,rgba(255,122,138,.55) 0 8px,rgba(255,179,190,.55) 8px 16px);box-shadow:0 2px 4px rgba(160,30,30,.12);clip-path:polygon(3% 0,97% 4%,100% 50%,96% 100%,2% 96%,0 48%)}
.ntx:before{content:"";position:absolute;inset:18px 10px 0 12px;border-radius:6px;background:#FFF2F4;transform:rotate(2.2deg);box-shadow:0 10px 24px -18px rgba(160,30,30,.6)}
.ntx-pp{position:relative;padding:calc(var(--L)*1) 18px calc(var(--L)*1) 48px;border-radius:6px;transform:rotate(-.6deg);background-color:#FFFCFC;background-image:linear-gradient(90deg,transparent 36px,#F7A1AC 36px,#F7A1AC 37.5px,transparent 37.5px),radial-gradient(circle at 16px 50%,#F7EFF0 0 6px,transparent 6.5px),repeating-linear-gradient(180deg,transparent 0,transparent calc(var(--L) - 1px),#F4D6DB calc(var(--L) - 1px),#F4D6DB var(--L));background-size:100% 100%,32px calc(var(--L)*4),100% var(--L);background-repeat:no-repeat,repeat-y,repeat;background-position:0 0,0 calc(var(--L)*1.5),0 0;box-shadow:0 1px 0 #F4D3D8,0 20px 34px -24px rgba(160,30,30,.65),inset 0 0 0 1px #F6DCE0;font-family:"Mali",var(--f-body),sans-serif;color:#3A2A2E}
.ntx-pp:after{content:"";position:absolute;right:0;bottom:0;width:34px;height:34px;background:linear-gradient(135deg,#FFE3E7 0,#FFE3E7 50%,#F3E9EA 50%);border-radius:0 0 6px 0;box-shadow:-2px -2px 4px rgba(160,30,30,.08)}
.ntx-hd{display:flex;justify-content:space-between;align-items:center;gap:8px;height:var(--L);line-height:var(--L)}
.ntx-hd small{font-size:.62rem;font-weight:600;color:#E31414}
.ntx-hd em{font-style:normal;font-size:.66rem;color:#8A6A70}
.ntx-pp h3{margin:0;font-size:1.45rem;line-height:calc(var(--L)*1.5);height:calc(var(--L)*1.5);font-weight:700;color:#E31414;font-family:"Mali",var(--f-display),sans-serif;padding-top:calc(var(--L)*.25)}
.ntx-pp p{margin:0 0 var(--L);font-size:.9rem;line-height:var(--L);text-indent:1.4em}
.ntx-cl{text-indent:0!important;font-weight:700;color:#2B1A1F}
.ntx-cl mark{background:linear-gradient(180deg,transparent 52%,rgba(255,122,138,.42) 52%,rgba(255,122,138,.42) 88%,transparent 88%);color:inherit;-webkit-box-decoration-break:clone;box-decoration-break:clone;padding:0 2px}
.ntx-sg{margin:0!important;text-align:right;text-indent:0!important;font-size:.82rem!important;color:#E31414;font-weight:600}
.ntx-pp h3{line-height:calc(var(--L)*2);height:calc(var(--L)*2);padding-top:0}
.ntx-pp{background-position:0 0,0 calc(var(--L)*1.5),0 calc(var(--L)*-0.2)}
.psx-mrz{display:none}
.psx-bc{display:flex;flex-direction:column;align-items:center;gap:6px;padding:12px 18px 10px;margin:0 -16px -16px;background:#fff;border-top:1px dashed #F6C9CF}
.psx-bc svg{display:block;width:100%;max-width:340px;height:46px;fill:#5A2A33}
.psx-bc span{font-family:"IBM Plex Mono",ui-monospace,monospace;font-size:.6rem;font-weight:600;letter-spacing:.18em;color:#6A3A42;text-align:center}
/* v1174: passport cover header */
.psx-top{display:flex!important;flex-direction:column;align-items:center;text-align:center;gap:0;padding:22px 18px 20px!important;overflow:hidden;background:radial-gradient(90% 70% at 50% 35%,rgba(255,255,255,.14),rgba(255,255,255,0) 70%),repeating-radial-gradient(circle at 30% 40%,rgba(255,255,255,.035) 0 1px,transparent 1px 3px),linear-gradient(160deg,#F65A5A 0%,#E92E32 45%,#C8141E 100%)!important}
.psx-top:after{background:none!important}
.psx-top:before{content:"";position:absolute;inset:8px;border:1px solid rgba(255,255,255,.28);border-radius:16px;pointer-events:none}
.psx-gl{position:absolute;inset:0;width:100%;height:100%;opacity:.13;pointer-events:none}
.psx-chip{position:absolute;right:20px;bottom:18px;width:30px;height:20px;fill:none;stroke:rgba(255,255,255,.8);stroke-width:1.6}
.psx-seal{position:relative;width:86px;height:86px;margin-bottom:10px}
.psx-seal svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.psx-seal .r1{fill:none;stroke:rgba(255,255,255,.75);stroke-width:1.2}
.psx-seal .r2{fill:none;stroke:rgba(255,255,255,.5);stroke-width:.8;stroke-dasharray:1 2.2}
.psx-seal text{font-size:6.6px;font-weight:700;letter-spacing:.9px;fill:rgba(255,255,255,.9);font-family:var(--f-body),sans-serif}
.psx-orb{position:absolute;left:50%;top:50%;width:46px;margin:-26px 0 0 -23px;filter:drop-shadow(0 4px 6px rgba(120,0,0,.3))}
.psx-orb .orb-svg{width:46px}
.psx-k{position:relative;font-size:.56rem!important;font-weight:800;letter-spacing:.42em;opacity:.85;margin-right:-.42em}
.psx-t{position:relative;margin-top:4px;font-size:1.12rem;font-weight:800;letter-spacing:.06em;background:linear-gradient(180deg,#fff 0,#FFE3E7 100%);-webkit-background-clip:text;background-clip:text;color:transparent;text-shadow:0 1px 0 rgba(120,0,0,.15)}
.psx-e{position:relative;font-style:normal;font-size:.62rem;font-weight:700;letter-spacing:.5em;margin-right:-.5em;opacity:.92;margin-top:2px}
.psx-top h1{position:relative;margin:12px 0 0!important;padding:6px 16px;font-size:1.08rem!important;font-weight:800;border-radius:999px;background:rgba(255,255,255,.16);box-shadow:inset 0 0 0 1px rgba(255,255,255,.35)}
.psx-emb{display:none}
.psx-seal .psx-orb svg{position:static;width:46px;height:auto}
.psx-seal text{letter-spacing:.55px;font-size:6.3px}
/* v1175: ruled lines locked to whole pixels */
.ntx{--L:32px}
.ntx-pp{background-image:linear-gradient(90deg,transparent 36px,#F7A1AC 36px,#F7A1AC 37.5px,transparent 37.5px),radial-gradient(circle at 16px 50%,#F7EFF0 0 6px,transparent 6.5px),repeating-linear-gradient(180deg,transparent 0 31px,#F4D6DB 31px 32px)!important;background-size:100% 100%,32px 128px,100% 100%!important;background-repeat:no-repeat,repeat-y,no-repeat!important;background-position:0 0,0 48px,0 -6px!important;padding-top:32px!important;padding-bottom:32px!important}
.ntx-pp p,.ntx-pp p *{line-height:32px!important}
.ntx-pp p{font-size:15px!important;margin:0 0 32px!important}
.ntx-pp p.ntx-sg{margin:0!important}
.ntx-hd{height:32px!important;line-height:32px!important}
.ntx-pp h3{height:64px!important;line-height:64px!important;font-size:23px!important}
.ntx-cl mark{padding:0!important}
/* v1176: traits, strengths, more people */
.st-rel.many{flex-wrap:wrap}
.st-rel.many span{flex:1 1 calc(33.33% - 6px)}
.str-g{display:grid;grid-template-columns:repeat(auto-fill,minmax(92px,1fr));gap:6px}
.str-g button{border:0;font:inherit;font-size:.78rem;font-weight:700;color:#2B1A1F;padding:11px 6px;border-radius:14px;background:#FFF8F9;box-shadow:inset 0 0 0 1px #F4D3D8;cursor:pointer;touch-action:manipulation}
.str-g button.on{color:#fff;background:linear-gradient(135deg,#FF7A7A,#E31414);box-shadow:0 8px 14px -8px rgba(227,20,20,.8)}
.trx-l{display:flex;flex-direction:column;gap:12px}
.trx-l>div{display:flex;flex-direction:column;gap:5px}
.trx-l>div>small{font-size:.6rem;font-weight:800;color:#E31414}
.trx-b{display:grid;grid-template-columns:minmax(0,1fr) 38% minmax(0,1fr);gap:8px;align-items:center}
.trx-b em{font-style:normal;font-size:.64rem;font-weight:600;color:#A08C8F;line-height:1.35}
.trx-b em:last-child{text-align:right}
.trx-b em.on{color:#2B1A1F;font-weight:800}
.trx-b i{position:relative;display:block;height:8px;border-radius:999px;background:linear-gradient(90deg,#FFD6DC,#FFF0F2 50%,#FFD6DC)}
.trx-b i:before{content:"";position:absolute;left:50%;top:-2px;bottom:-2px;width:1.5px;background:#F6B3BB}
.trx-b u{position:absolute;top:50%;width:16px;height:16px;margin:-8px 0 0 -8px;border-radius:50%;background:linear-gradient(135deg,#FF7A7A,#E31414);box-shadow:0 0 0 3px #fff,0 4px 8px -2px rgba(227,20,20,.6)}
.trx-s{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.trx-s>div{display:flex;flex-direction:column;gap:6px;padding:10px;border-radius:14px;background:#FFF8F9}
.trx-s small{font-size:.58rem;font-weight:800;color:#8A6A70}
.trx-s p{margin:0;display:flex;flex-wrap:wrap;gap:4px}
.trx-s b{font-size:.66rem;font-weight:700;padding:3px 8px;border-radius:999px;background:#fff;color:#2B1A1F;box-shadow:inset 0 0 0 1px #F4D3D8}
.trx-s b.m{background:#E31414;color:#fff;box-shadow:none}
.lfh-auth{margin:16px 0 0}
/* v1179: SW edition */
.orb-ed{display:grid;grid-template-columns:1fr 1fr;gap:6px;padding:5px;border-radius:20px;background:#fff;box-shadow:inset 0 0 0 1px #F4D3D8}
.orb-ed button{display:flex;flex-direction:column;gap:2px;align-items:center;text-align:center;border:0;font:inherit;padding:10px 6px;border-radius:15px;background:none;cursor:pointer;color:#8A6A70;touch-action:manipulation}
.orb-ed button b{font-size:.78rem;font-weight:800;line-height:1.3}
.orb-ed button small{font-size:.58rem;font-weight:600}
.orb-ed button[aria-selected="true"]{color:#fff;background:linear-gradient(135deg,#FF7A7A,#F24A4A 55%,#E31414);box-shadow:0 8px 16px -10px rgba(227,20,20,.85)}
.lf-hb+.lf-hb{margin-top:10px}
.psx-route.sw{grid-template-columns:repeat(3,minmax(0,1fr));row-gap:14px}
.psx-route.sw .psx-st b{font-size:.62rem}
